

const STORAGE_KEY = "spk_suivi_optimisation_v1";
const LEGACY_KEY = "spk_op10_bilan_v3"; // ancien format mono-reference, repris automatiquement

/* Identifiants uniques : prefix + timestamp base36 + aleatoire. Date.now() seul collisionne
   des qu'un meme geste crée plusieurs objets dans la meme milliseconde (double-clic,
   import, scripts) — la collision ecrase silencieusement des donnees (audit v4.4.0).
   Pattern deja utilise pour e/p/t/g, etendu a s/l/r/o. pj reste gere par normalizeProjet. */
function uid(prefix){ return prefix + Date.now().toString(36) + Math.random().toString(36).slice(2,6); }

/* ---- dialogues in-app + focus des panneaux (v4.6) ----
   Derniers vestiges de fenetres natives : 27 alert(), 20 confirm() et 4 prompt() s'affichaient
   en fenetres systeme grises. Deux problemes : elles cassaient l'identite visuelle (et le mode
   nuit), et leur texte ne supportait aucune mise en forme — les messages les plus importants
   de l'outil (panne de stockage, garde-fou double comptage) etaient des murs de texte brut.
   Ces dialogues gardent la semantique du natif : Echap / clic hors panneau = Annuler,
   Entree = valider, promesse resolue avec la valeur (booleen, ou texte saisi / null).
   Placé ici, avant loadAll() : le garde-fou anti-arbre-vide peut poser sa question des
   le chargement — les declarations "let" du bloc seraient en zone morte plus bas. */
let panneauPile = [];
let focusAvantPanneau = null;
let dialogEnAttente = null;
const SELECTEUR_FOCUSABLE = 'button:not([disabled]), input:not([disabled]):not([type="file"]), select:not([disabled]), textarea:not([disabled]), a[href], [tabindex]:not([tabindex="-1"])';

function dlgTexte(t){
  return String(t ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/\n/g,"<br>");
}
function ouvrirDialogue(opts){
  return new Promise(resolve => {
    fermerDialogue(); // un dialogue oublie ouvert ne doit pas laisser sa promesse en suspens
    const row = document.getElementById("dialogInputRow");
    const input = document.getElementById("dialogInput");
    const avecSaisie = Object.prototype.hasOwnProperty.call(opts, "saisie");
    document.getElementById("dialogTitle").textContent = opts.titre || "Information";
    document.getElementById("dialogBody").innerHTML = opts.html || "";
    row.hidden = !avecSaisie;
    if(avecSaisie){ input.value = opts.saisie || ""; input.placeholder = opts.placeholder || ""; }
    const annuler = document.getElementById("dialogCancel");
    const ok = document.getElementById("dialogOk");
    annuler.hidden = opts.sansAnnuler === true;
    ok.textContent = opts.okLabel || (opts.sansAnnuler ? "Fermer" : "Confirmer");
    ok.classList.toggle("danger", opts.danger === true);
    dialogEnAttente = { resolve, avecSaisie };
    ouvrirPanneau("dialogPanel");
    if(avecSaisie){ input.focus(); input.select(); }
    else if(!annuler.hidden) annuler.focus(); // defaut au clavier : le geste reversible
    else ok.focus();
  });
}
function fermerDialogue(valeur){
  const pan = document.getElementById("dialogPanel");
  if(!pan || pan.hidden) return;
  pan.hidden = true;
  panneauPile = panneauPile.filter(id => id !== "dialogPanel");
  if(!panneauPile.length){
    document.getElementById("panelBackdrop").hidden = true;
    restaurerFocusPanneau();
  }
  if(dialogEnAttente){
    const d = dialogEnAttente; dialogEnAttente = null;
    d.resolve(valeur === undefined ? (d.avecSaisie ? null : false) : valeur);
  }
}
function dialogueAlerte(texte, titre){
  return ouvrirDialogue({ titre: titre || "Information", html: dlgTexte(texte), sansAnnuler: true });
}
function dialogueConfirmer(texte, opts){
  opts = opts || {};
  return ouvrirDialogue({ titre: opts.titre || "Confirmer ?", html: opts.html || dlgTexte(texte), danger: opts.danger, okLabel: opts.okLabel }).then(ok => !!ok);
}
function dialogueDemander(texte, valeur, opts){
  opts = opts || {};
  return ouvrirDialogue({ titre: opts.titre || "Saisie", html: dlgTexte(texte), saisie: valeur, placeholder: opts.placeholder, okLabel: opts.okLabel || "Valider", danger: opts.danger });
}
function restaurerFocusPanneau(){
  if(focusAvantPanneau && document.contains(focusAvantPanneau)){
    try{ focusAvantPanneau.focus({ preventScroll:true }); }catch(e){}
  }
  focusAvantPanneau = null;
}
document.getElementById("dialogOk").addEventListener("click", () => {
  if(!dialogEnAttente) return;
  fermerDialogue(dialogEnAttente.avecSaisie ? document.getElementById("dialogInput").value : true);
});
document.getElementById("dialogCancel").addEventListener("click", () => fermerDialogue(false));
document.getElementById("dialogInput").addEventListener("keydown", e => {
  if(e.key === "Enter"){ e.preventDefault(); fermerDialogue(document.getElementById("dialogInput").value); }
});
/* Tab reste piege dans le panneau du dessus : sans cela, le focus s'echappe derriere
   le voile — on tabule dans une page invisible, et Echap devient le seul recours. */
document.addEventListener("keydown", e => {
  if(e.key !== "Tab") return;
  const idPan = panneauPile[panneauPile.length - 1];
  if(!idPan) return;
  const pan = document.getElementById(idPan);
  if(!pan || pan.hidden) return;
  const items = Array.from(pan.querySelectorAll(SELECTEUR_FOCUSABLE)).filter(el => el.getClientRects().length > 0);
  if(!items.length) return;
  const dedans = pan.contains(document.activeElement);
  if(e.shiftKey){
    if(!dedans || document.activeElement === items[0]){ e.preventDefault(); items[items.length - 1].focus(); }
  } else {
    if(!dedans || document.activeElement === items[items.length - 1]){ e.preventDefault(); items[0].focus(); }
  }
});

/* ---- dossier local (photos + backup) ----
   Les photos ne doivent JAMAIS gonfler le localStorage/JSON echange entre collegues : elles
   sont ecrites comme de vrais fichiers dans un dossier choisi sur le disque (API File System
   Access, Edge/Chrome uniquement, necessite https:// ou localhost). Seule une reference legere
   (nom de fichier) est gardee dans les donnees. Disponible seulement depuis la version en ligne
   (Surge) ou un serveur local — pas depuis le fichier ouvert en file://. */
let photosDirHandle = null;
function fsPhotosSupported(){ return typeof window.showDirectoryPicker === "function"; }
function idbOpenFs(){
  return new Promise((resolve, reject) => {
    const req = indexedDB.open("spk_suivi_fs", 1);
    req.onupgradeneeded = () => req.result.createObjectStore("handles");
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}
async function idbSetHandle(key, handle){
  const db = await idbOpenFs();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("handles", "readwrite");
    tx.objectStore("handles").put(handle, key);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}
async function idbGetHandle(key){
  const db = await idbOpenFs();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("handles", "readonly");
    const req = tx.objectStore("handles").get(key);
    req.onsuccess = () => resolve(req.result || null);
    req.onerror = () => reject(req.error);
  });
}
function slugify(txt){
  return String(txt||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"")
    .replace(/[^a-zA-Z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,40) || "x";
}
/* redimensionne cote client avant ecriture : une photo de telephone peut peser plusieurs
   Mo, inutile de la garder brute pour une consultation a l'ecran */
function compressImageFile(file, maxDim, quality){
  return new Promise((resolve, reject) => {
    // ObjectURL plutot qu'un data URL base64 : evite de doubler la photo en memoire
    // (base64 gonfle ~33%, plus la decompression de l'<img>) — sensible sur un JPEG de
    // telephone a 8+ Mo, potentiellement OOM sur mobile/Safari
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.onload = () => {
      const scale = Math.min(1, maxDim / Math.max(img.width, img.height));
      const canvas = document.createElement("canvas");
      canvas.width = Math.round(img.width * scale);
      canvas.height = Math.round(img.height * scale);
      canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
      URL.revokeObjectURL(url);
      canvas.toBlob(blob => blob ? resolve(blob) : reject(new Error("compression échouée")), "image/jpeg", quality);
    };
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error("lecture image échouée")); };
    img.src = url;
  });
}
async function connectPhotosDir(){
  if(!fsPhotosSupported()){
    dialogueAlerte("Cette fonction (dossier photos local) nécessite Edge ou Chrome sur ordinateur, et d'ouvrir l'outil via son adresse en ligne (https://...) plutôt que le fichier local.", "Dossier local indisponible");
    return;
  }
  try{
    const handle = await window.showDirectoryPicker({ id: "spk-photos", mode: "readwrite" });
    photosDirHandle = handle;
    await idbSetHandle("photosDir", handle);
    updatePhotosDirUI();
    render();
  }catch(e){ /* utilisateur a annulé la sélection */ }
}
async function tryReconnectPhotosDir(){
  if(!fsPhotosSupported()) return;
  try{
    const handle = await idbGetHandle("photosDir");
    if(!handle) return;
    const perm = await handle.queryPermission({ mode: "readwrite" });
    if(perm === "granted"){ photosDirHandle = handle; }
    updatePhotosDirUI();
  }catch(e){}
}
function updatePhotosDirUI(){
  const el = document.getElementById("photosDirStatus");
  if(!el) return;
  if(!fsPhotosSupported()){ el.textContent = ""; return; }
  el.textContent = photosDirHandle ? "📁 Dossier photos connecté (" + photosDirHandle.name + ")" : "📁 Dossier photos non connecté";
  el.className = "save-status" + (photosDirHandle ? " saved" : "");
}
async function writePhotoBlob(filename, blob){
  const fh = await photosDirHandle.getFileHandle(filename, { create: true });
  const w = await fh.createWritable();
  await w.write(blob);
  await w.close();
}
async function readPhotoURL(filename){
  try{
    const fh = await photosDirHandle.getFileHandle(filename);
    const file = await fh.getFile();
    return URL.createObjectURL(file);
  }catch(e){
    // l'echec peut venir d'une permission revoquee en cours de session (parametres du
    // navigateur) : sans ce controle, ca restait invisible — la prochaine lecture photo
    // echouait silencieusement, sans indication a l'utilisateur
    checkPhotosDirPermission();
    return null;
  }
}
async function checkPhotosDirPermission(){
  if(!photosDirHandle) return;
  try{
    const perm = await photosDirHandle.queryPermission({ mode:"readwrite" });
    if(perm !== "granted"){ photosDirHandle = null; updatePhotosDirUI(); }
  }catch(e){ photosDirHandle = null; updatePhotosDirUI(); }
}
async function deletePhotoFile(filename){
  try{ await photosDirHandle.removeEntry(filename); }catch(e){}
}
/* v4.16 — lecture d'une photo quel que soit son mode. Version de base ici (dossier
   local, photos cloud indisponibles) : le bloc cloud, chargé juste après, RÉDÉFINIT
   cette fonction avec le téléchargement + cache. Un stub est nécessaire parce que
   loadPhotoThumbnails tourne au premier rendu, AVANT que le bloc cloud n'existe. */
let cloudPhotoErreurDerniere = "";
function photoObjectURL(p){
  if(!p) return null;
  if(p.stockage === "cloud") return null; // le bloc cloud apporte le vrai chargement
  return readPhotoURL(p.filename);
}
/* backup general dans le meme dossier (sous-dossier backups/), independant du localStorage :
   filet de securite supplementaire, au plus 1 ecriture toutes les 5 minutes, 20 fichiers gardes */
let lastFolderBackupAt = 0;
async function writeBackupToFolder(){
  if(!photosDirHandle) return;
  const now = Date.now();
  if(now - lastFolderBackupAt < 5*60*1000) return;
  lastFolderBackupAt = now;
  try{
    const backupsDir = await photosDirHandle.getDirectoryHandle("backups", { create: true });
    const stamp = new Date().toISOString().replace(/[:.]/g,"-");
    const payload = { outil:"SPK Suivi optimisation", format:8, toolVersion:TOOL_VERSION, revision, exporteLe:new Date().toISOString(), exportePar:auteurNom, lignes, projets, activeProjetId, responsables, backlog };
    const fh = await backupsDir.getFileHandle(stamp + ".json", { create: true });
    const w = await fh.createWritable();
    await w.write(JSON.stringify(payload));
    await w.close();
    // purge : ne garde que les 20 plus recents (tri par nom = tri chronologique, stamp ISO)
    const noms = [];
    for await (const [name] of backupsDir.entries()) noms.push(name);
    noms.sort();
    const trop = noms.length - 20;
    for(let i=0;i<trop;i++){ try{ await backupsDir.removeEntry(noms[i]); }catch(e){} }
  }catch(e){}
}

