document.getElementById("resetBtn").addEventListener("click", () => {
  const nbEssais = lignes.reduce((n, l) => n + l.references.reduce((n2, r) => n2 + r.ops.reduce((n3, o) => n3 + o.scenarios.reduce((n4, s) => n4 + (s.essais||[]).length, 0), 0), 0), 0);
  const nbRef = lignes.reduce((n, l) => n + l.references.length, 0);
  const nbOp = lignes.reduce((n, l) => n + l.references.reduce((n2, r) => n2 + r.ops.length, 0), 0);
  // un simple clic sur "OK" se fait sans y penser (surtout avec ce bouton juste a cote des
  // autres actions courantes) : on exige de taper un mot exact, comme un vrai "sont-vous sur"
  // qui force une action deliberee plutot qu'un reflexe de souris.
  // dialogue in-app (v4.6) : la validation reste un mot exact a taper — le geste est
  // deliberé, pas un reflexe de souris — mais dans la famille visuelle de l'outil.
  dialogueDemander(
    "Réinitialiser l'outil ?\n\nTOUTES les lignes de production, TOUTES les références disque (" + nbRef + "), TOUTES les OP (" + nbOp + "), tous les scénarios et les " + nbEssais + " essai(s) saisis seront effacés et remplacés par les valeurs de départ.\n\nExportez d'abord le suivi si vous voulez le conserver.\n\nPour confirmer, tapez exactement : REINITIALISER",
    "", { titre: "Réinitialiser l'outil ?", okLabel: "Réinitialiser", danger: true }
  ).then(saisie => {
    if(saisie !== "REINITIALISER"){ if(saisie !== null) dialogueAlerte("Réinitialisation annulée — le texte tapé ne correspond pas.", "Annulée"); return; }
    backupSnapshot("Réinitialiser");
    lignes = defaultLignes();
    projets = []; activeProjetId = null; responsables = [];
    backlog = [];
    activeLigneId = lignes[0].id;
    activeReferenceId = lignes[0].references[0].id;
    activeOpId = lignes[0].references[0].ops[0].id;
    data = lignes[0].references[0].ops[0].scenarios;
    config = lignes[0].references[0].ops[0].config;
    activeId = data[0].id;
    recomputeCycles();
    saveData();
    updateRestoreUI();
    render();
  });
});

