/* ---- panneaux modaux ---- */
function ouvrirPanneau(id){
  const pan = document.getElementById(id);
  if(panneauPile.indexOf(id) === -1){
    if(!panneauPile.length && !focusAvantPanneau) focusAvantPanneau = document.activeElement;
    panneauPile.push(id);
  }
  pan.hidden = false;
  // role dialogue pose dynamiquement (v4.6) : chaque panneau se comporte comme une fenetre
  // modale pour les lecteurs d'ecran, et le piege de Tab ci-dessus s'appuie sur la pile.
  pan.setAttribute("role", "dialog");
  pan.setAttribute("aria-modal", "true");
  if(!pan.hasAttribute("aria-label")){
    const t = pan.querySelector("h3");
    if(t) pan.setAttribute("aria-label", t.textContent.trim());
  }
  document.getElementById("panelBackdrop").hidden = false;
  // le focus entre dans le panneau ouvert : premier champ, sinon le panneau lui-meme —
  // sinon il reste derriere le voile et Tab ressort de la fenetre invisible.
  const cible = pan.querySelector(SELECTEUR_FOCUSABLE);
  if(cible && cible.getClientRects().length) cible.focus();
  else { pan.tabIndex = -1; pan.focus({ preventScroll:true }); }
}
function fermerPanneaux(){
  fermerDialogue();
  document.getElementById("panelBackdrop").hidden = true;
  // tous les panneaux, sans liste en dur : projetCreatePanel oublie ici restait ouvert
  // apres la creation d'un projet, empile sous le panneau d'info (et un 2e clic sur
  // "Creer le projet" creait un doublon). Un futur panneau sera couvert d'office.
  document.querySelectorAll(".panel").forEach(p => { p.hidden = true; });
  annot = null;
  importEnAttente = null;
  document.getElementById("toolbarMore").hidden = true;
  panneauPile = [];
  restaurerFocusPanneau();
}
