// silencieusement sur Echap ou un clic hors panneau — confirmation ajoutee, uniquement
// s'il y a vraiment quelque chose de different de l'etat charge (annotDirty)
function annotDirty(){
  if(!annot) return false;
  return JSON.stringify({ crop: annot.crop, shapes: annot.shapes, legende: annot.legendeDraft }) !== annot.snapshot;
}
function fermerPanneauxConfirme(){
  const annotWrap = document.getElementById("photoAnnotWrap");
  if(annotWrap && !annotWrap.hidden && annotDirty()){
    // dialogue in-app (v4.6) : le refus laisse le panneau ouvert, comme avant avec confirm().
    dialogueConfirmer("Fermer sans enregistrer ? Le rognage, les formes et la légende ajoutés à cette photo seront perdus.", { titre: "Fermer sans enregistrer ?", danger: true, okLabel: "Fermer sans enregistrer" }).then(ok => {
      if(!ok) return;
      annot = null;
      fermerPanneaux();
    });
    return;
  }
  annot = null;
  fermerPanneaux();
}
