/* etat du cout machine (v4.7) : l'ancienne note statique des "quatre choses a faire"
   disait trop — le calcul reel (coutMachinePiece/cycleSecondes) n'exige que le module
   actif, le cycle de reference et le cout horaire ; l'affichage en secondes est une
   commodite, pas une condition. L'outil le dit maintenant depuis le code, pas depuis
   un texte qui pouvait deriver de lui. */
function etatCoutMachine(cfg, ligne){
  cfg = cfg || config;
  const l = ligne || getActiveLigne();
  const taux = l ? parseFloat(l.coutHoraire) : NaN;
  const manquants = [];
  if(cfg.cycleRefSec === "" || isNaN(parseFloat(cfg.cycleRefSec))) manquants.push("le temps de cycle du scénario de référence (s)");
  if(isNaN(taux) || taux <= 0) manquants.push("le coût horaire de la ligne (€/h)");
  return { actif: !!cfg.coutMachineActif && !manquants.length, taux, manquants };
}
function majStatutCoutMachine(){
  const el = document.getElementById("optCoutMachineStatut");
  if(!el) return;
  if(!config.coutMachineActif){ el.hidden = true; return; }
  const et = etatCoutMachine();
  el.hidden = false;
  if(et.manquants.length){
    el.className = "opt-statut ko";
    el.innerHTML = `Coût machine incomplet — il manque encore ${et.manquants.join(" et ")}. Tant qu'il manque, le coût pièce ignore le temps machine : aucun écart de cycle ne pèse dans le gain annuel.`;
  } else {
    el.className = "opt-statut ok";
    el.innerHTML = `Coût machine actif — ${fmt(et.taux,2)} €/h × temps de cycle. Les écarts de cycle pèsent maintenant dans le coût pièce et le gain annuel.`;
  }
}
function majChampsOptions(){
  document.getElementById("optCoutRebutField").classList.toggle("on", optCoutRebut.checked);
  document.getElementById("optCycleRefField").classList.toggle("on", optCycleSec.checked || optCoutMachine.checked);
  document.getElementById("optCoutMachineField").classList.toggle("on", optCoutMachine.checked);
  document.getElementById("optVolumeField").classList.toggle("on", optVolume.checked);
  majStatutCoutMachine();
}
function syncOptionsUI(){
  optLimitLabel.value = config.limitLabel ?? "";
  optLimitValue.value = config.limitValue ?? "";
  optCoutRebut.checked = !!config.coutRebutActif;
  optCoutDisque.value = config.coutDisque ?? "";
  optCycleSec.checked = !!config.cycleSecActif;
  optCycleRefSec.value = config.cycleRefSec ?? "";
  optCoutMachine.checked = !!config.coutMachineActif;
  optPartCoupante.value = config.partCoupante ?? "";
  optCycleDetail.checked = !!config.cycleDetailActif;
  optPieces.checked = !!config.piecesActif;
  optVolume.checked = !!config.volumeActif;
  const ref = getActiveReference();
  optProductionAnnuelle.value = ref ? (ref.productionAnnuelle ?? "") : "";
  optForceRatio.checked = !!config.forceRatioActif;
  optEcartCharniere.value = config.ecartCharniereTolerance ?? 0.5;
  // contexte (v4.7) : les reglages d'Options ne portent pas tous la meme portee — on dit
  // laquelle, d'un coup, en tete de panneau, plutot que de la deviner champ par champ.
  const lg = getActiveLigne(), op = getActiveOp();
  document.getElementById("optionsContexte").innerHTML =
    `${escapeAttr(op ? op.nom : "—")} · ${escapeAttr(ref ? ref.nom : "—")} · ${escapeAttr(lg ? lg.nom : "—")}` +
    ` — chaque réglage porte son badge de portée : <i class="opt-scope">OP</i>, <i class="opt-scope">Référence</i>, <i class="opt-scope">Ligne</i> ou <i class="opt-scope">Tous</i>.`;
  // v4.23 — le champ volume porte sa cible en toutes lettres : ligne › référence, plus
  // la trace de la dernière modification. Fini le doute « ce chiffre s'applique à qui ? »
  const optVolumeTarget = document.getElementById("optVolumeTarget");
  if(optVolumeTarget){
    const dernierVol = ref && ref.volumeHistorique && ref.volumeHistorique[0];
    const volDate = dernierVol ? new Date(dernierVol.date).toLocaleDateString("fr-FR") : "";
    optVolumeTarget.innerHTML = ref && lg
      ? `<b>S'applique à : ${escapeAttr(lg.nom)} › ${escapeAttr(ref.nom)}</b>` +
        (dernierVol ? ` — dernière modification : ${escapeAttr(dernierVol.valeur === "" ? "champ vidé" : fmt(parseFloat(dernierVol.valeur),0) + " disques/an")} par ${escapeAttr(dernierVol.par || "?")}${volDate ? " le " + volDate : ""}` : "")
      : "";
  }
  // le cout horaire vit sur la ligne : champ en place (v4.7), meme donnee que l'icone ⚙
  optCoutHoraire.value = lg ? (lg.coutHoraire ?? "") : "";
  // v4.9 : specs usine affichées, toujours reverrouillées à l'ouverture du panneau
  usineUnlockOk = false;
  optUsineBatt.value = specsUsine.battement;
  optUsineVE.value = specsUsine.ve;
  optUsineBatt.disabled = true;
  optUsineVE.disabled = true;
  optUsineUnlock.textContent = "Modifier";
  majChampsOptions();
  renderFicheOutil();
  renderResponsablesOptions();
}

/* Gestion des responsables (v4.2), dans Options : liste geree independamment des projets --
   supprimer un responsable ne supprime jamais un projet, il repasse a "aucun responsable"
   (voir supprimerResponsable). */
function renderResponsablesOptions(){
  const el = document.getElementById("responsablesListe");
  if(!el) return;
  el.innerHTML = responsables.length
    ? responsables.map(r => `
        <div class="responsable-ligne" data-responsable="${r.id}">
          <input type="color" class="responsable-couleur" value="${r.couleur || "#94a3b8"}" title="Couleur de ${escapeAttr(r.nom)}">
          <span class="responsable-nom">${escapeAttr(r.nom)}</span>
          <button class="log-del" data-suppr-responsable="${r.id}" title="Supprimer">✕</button>
        </div>`).join("")
    : `<p class="opt-note">Aucun responsable pour l'instant — ajoutez-en un ci-dessous, ou directement depuis le panneau d'un projet.</p>`;
  el.querySelectorAll(".responsable-couleur").forEach(inp => {
    inp.addEventListener("change", () => {
      const r = responsables.find(x => x.id === inp.closest("[data-responsable]").getAttribute("data-responsable"));
      if(r){ r.couleur = inp.value; saveData(); render(); }
    });
  });
  el.querySelectorAll("[data-suppr-responsable]").forEach(btn => {
    btn.addEventListener("click", () => {
      const id = btn.getAttribute("data-suppr-responsable");
      const r = responsables.find(x => x.id === id);
      if(!r) return;
      const nbProjets = projets.filter(p => p.responsableId === id).length;
      dialogueConfirmer(`Supprimer « ${r.nom} » de la liste des responsables ?` + (nbProjets ? `\n\n${nbProjets} projet(s) actuellement piloté(s) par cette personne repasseront à « Aucun » — ils ne sont pas supprimés.` : ""), { titre: "Supprimer le responsable ?", danger: true, okLabel: "Supprimer" }).then(ok => {
        if(!ok) return;
        responsables = responsables.filter(x => x.id !== id);
        projets.forEach(p => { if(p.responsableId === id) p.responsableId = ""; });
        saveData(); render(); renderResponsablesOptions();
      });
    });
  });
}
document.getElementById("responsableAjouter").addEventListener("click", () => {
  const nomEl = document.getElementById("responsableNouveauNom");
  const couleurEl = document.getElementById("responsableNouvelleCouleur");
  const nom = nomEl.value.trim();
  if(!nom){ dialogueAlerte("Indiquez un nom.", "Nom manquant"); return; }
  responsables.push(normalizeResponsable({ nom, couleur: couleurEl.value }));
  nomEl.value = "";
  couleurEl.value = prochaineCouleurLibre(responsables.map(x => x.couleur));
  saveData(); render(); renderResponsablesOptions();
});

function appliquerOptions(){
  config.limitLabel = optLimitLabel.value;
  config.limitValue = optLimitValue.value === "" ? "" : parseFloat(optLimitValue.value);
  config.coutRebutActif = optCoutRebut.checked;
  config.coutDisque = optCoutDisque.value === "" ? "" : parseFloat(optCoutDisque.value);
  config.cycleSecActif = optCycleSec.checked;
  config.cycleRefSec = optCycleRefSec.value === "" ? "" : parseFloat(optCycleRefSec.value);
  config.coutMachineActif = optCoutMachine.checked;
  config.partCoupante = optPartCoupante.value === "" ? 100 : parseFloat(optPartCoupante.value);
  config.cycleDetailActif = optCycleDetail.checked;
  config.piecesActif = optPieces.checked;
  config.volumeActif = optVolume.checked;
  const ref = getActiveReference();
  if(ref) enregistrerVolumeAnnuel(ref, optProductionAnnuelle.value === "" ? "" : parseFloat(optProductionAnnuelle.value));
  // cout horaire saisi en place (v4.7) : il ecrit dans la ligne active, comme le ferait
  // l'icone ⚙ de son onglet — meme champ, deux portes d'entree, zero changement de format
  const lgOpt = getActiveLigne();
  if(lgOpt) lgOpt.coutHoraire = optCoutHoraire.value;
  config.forceRatioActif = optForceRatio.checked;
  config.ecartCharniereTolerance = optEcartCharniere.value === "" ? 0.5 : parseFloat(optEcartCharniere.value);
  majChampsOptions();
  saveData();
  render();
}
// chaque frappe dans un champ number d'Options declenchait un saveData()+render() complet
// (perceptible sur un gros arbre) : debounce leger sur "input", "change" (blur/Entree)
// reste instantane
let optionsInputDebounce = null;
[optCoutRebut, optCoutDisque, optCycleSec, optCycleRefSec, optCoutMachine, optPartCoupante, optCycleDetail,
 optPieces, optVolume, optProductionAnnuelle, optLimitLabel, optLimitValue, optForceRatio, optEcartCharniere, optCoutHoraire].forEach(el => {
  el.addEventListener("change", () => { clearTimeout(optionsInputDebounce); appliquerOptions(); });
  el.addEventListener("input", () => {
    if(el.type !== "number") return;
    clearTimeout(optionsInputDebounce);
    optionsInputDebounce = setTimeout(appliquerOptions, 150);
  });
});
document.getElementById("optionsBtn").addEventListener("click", () => { syncOptionsUI(); ouvrirPanneau("optionsPanel"); });

/* v4.9 — modification des specs usine : double validation. Le bouton déverrouille les
   champs après confirmation explicite ; les valeurs ne sont écrites qu'au
   reverrouillage (« Verrouiller et enregistrer »), et le panneau reverrouille tout seul
   à sa prochaine ouverture. */
let usineUnlockOk = false;
document.getElementById("optUsineUnlock").addEventListener("click", () => {
  const b = document.getElementById("optUsineUnlock");
  const batt = document.getElementById("optUsineBatt");
  const ve = document.getElementById("optUsineVE");
  if(usineUnlockOk){
    if(batt.value !== "" && !isNaN(parseFloat(batt.value))) specsUsine.battement = parseFloat(batt.value);
    if(ve.value !== "" && !isNaN(parseFloat(ve.value))) specsUsine.ve = parseFloat(ve.value);
    usineUnlockOk = false;
    batt.disabled = ve.disabled = true;
    b.textContent = "Modifier";
    saveData();
    dialogueAlerte("Specs usine enregistrées : Battement ≤ " + fmt(specsUsine.battement,3) + " · VE ≤ " + fmt(specsUsine.ve,3) + ".", "Specs usine");
    return;
  }
  dialogueConfirmer("Modifier les spécifications usine ?\n\nCes valeurs (battement max et variation d'épaisseur max mesurées Marposs sur disque fini, après OP40) servent de référence pour TOUS les disques de l'usine et ne changent normalement jamais.\n\nNe continuer que si la spécification a réellement été revue officiellement.", { titre: "Modifier les specs usine ?", danger: true, okLabel: "Déverrouiller" }).then(ok => {
    if(!ok) return;
    usineUnlockOk = true;
    batt.disabled = ve.disabled = false;
    batt.focus();
    b.textContent = "Verrouiller et enregistrer";
  });
});
["projetNom","projetProblematique","projetStatut","projetDateCible"].forEach(id => {
  const el = document.getElementById(id);
  if(el) el.addEventListener("change", enregistrerProjetInfo);
});
document.getElementById("projetResponsable").addEventListener("change", (e) => {
  if(e.target.value === "__nouveau__") ajouterResponsableDepuisSelect();
  else enregistrerProjetInfo();
});
document.getElementById("projetInfoClose").addEventListener("click", () => { enregistrerProjetInfo(); fermerPanneaux(); });
document.getElementById("projetSupprimer").addEventListener("click", supprimerProjetActif);
/* creation projet (v4.5) : panneau dedie, Enter valide, echap/annuler ferme */
document.getElementById("projetCreateGo").addEventListener("click", validerCreationProjet);
document.getElementById("projetCreateAnnuler").addEventListener("click", fermerPanneaux);
document.getElementById("projetCreateNom").addEventListener("keydown", (e) => { if(e.key === "Enter") validerCreationProjet(); });
document.getElementById("optionsClose").addEventListener("click", fermerPanneaux);

/* fiche outil (PDF ou image) : n° d'outils et trajectoires par logement, par OP.
   Stockee en base64 directement dans l'OP — voyage avec l'export/import JSON, sans
   dossier a part (contrairement aux photos d'essai, sur fichiers reels locaux). */
function renderFicheOutil(){
  const wrap = document.getElementById("ficheOutilWrap");
  if(!wrap) return;
  const op = getActiveOp();
  const f = op && op.ficheOutil;
  // les fiches jointes avant la v3.19 n'ont pas de champ "stockage" : elles sont en base64
  const enDossier = f && f.stockage === "dossier";
  wrap.innerHTML = f
    ? `<div class="plan-outil">
         <span class="plan-icone">${(f.mime||"").startsWith("image/") ? "🖼" : "📄"}</span>
         <span class="plan-nom">${escapeAttr(f.nomOrigine || f.filename)}</span>
         <span class="plan-ou">${enDossier ? "dossier local" : "intégrée au fichier de suivi"}</span>
         <button class="ghost small" id="ficheOutilOpen" type="button">Ouvrir</button>
         <button class="ghost small" id="ficheOutilDel" type="button">Retirer</button>
       </div>`
    : `<label class="plan-ajout">📎 Joindre la fiche outil de l'OP <span>(PDF ou image)</span>
         <input type="file" accept=".pdf,image/*" id="ficheOutilInput" hidden>
       </label>`;
  if(f){
    document.getElementById("ficheOutilOpen").addEventListener("click", () => ouvrirPieceJointe(f));
    document.getElementById("ficheOutilDel").addEventListener("click", () => {
      dialogueConfirmer("Retirer la fiche outil de cette OP ?" + (enDossier ? `

Le fichier reste dans le dossier local, seul le lien est supprimé.` : ""), { titre: "Retirer la fiche outil ?", danger: true, okLabel: "Retirer" }).then(ok => {
        if(!ok) return;
        const op2 = getActiveOp();
        if(op2) op2.ficheOutil = null;
        saveData(); renderFicheOutil();
      });
    });
  } else {
    document.getElementById("ficheOutilInput").addEventListener("change", async (e) => {
      const file = e.target.files && e.target.files[0];
      if(!file) return;
      const op2 = getActiveOp();
      if(!op2) return;
      const pj = await attacherPieceJointe(file, "ficheoutil_" + slugify(op2.nom || "op"));
      e.target.value = "";
      if(!pj) return;
      op2.ficheOutil = pj;
      saveData(); renderFicheOutil();
    });
  }
}

