const TOOL_VERSION = "4.89.0";
const CLE_VERSION_VUE = "spk_derniere_version_vue";
const CLE_NOUVEAUTES_OFF = "spk_nouveautes_masquees";

function nouveautesHTML(){
  /* v4.25 — la popup au démarrage ne raconte que le très récent : au-delà de 10 jours,
     les modifs ont été vues ou n'intéressent plus (Matis). On garde la dizaine écoulée,
     date illisible exceptée (prudence), et jamais une liste vide. */
  const limite = Date.now() - 10 * 24 * 3600 * 1000;
  const recentes = NOUVEAUTES.filter(n => {
    const [j, m, a] = (n.date || "").split("/").map(Number);
    if(!j || !m || !a) return true;
    return new Date(a, m - 1, j).getTime() >= limite;
  });
  const liste = recentes.length ? recentes : NOUVEAUTES.slice(0, 1);
  return liste.map((n, i) => `
    <div class="nv-bloc${i === 0 ? " nv-actuelle" : ""}">
      <div class="nv-tete">
        <span class="nv-version">Version ${n.version}</span>
        <span class="nv-date">${n.date}</span>
      </div>
      <ul>${n.points.map(p => `<li>${p}</li>`).join("")}</ul>
    </div>`).join("");
}
function ouvrirNouveautes(){
  const wrap = document.getElementById("nouveautesPanel");
  const masquees = (() => { try { return localStorage.getItem(CLE_NOUVEAUTES_OFF) === "1"; } catch(e){ return false; } })();
  wrap.innerHTML = `
    <h3>Nouveautés de l'outil</h3>
    <p class="panel-hint">Vous utilisez la version <b>${TOOL_VERSION}</b>. Voici ce qui a changé depuis vos dernières utilisations — inutile d'attendre un e-mail.</p>
    <p class="panel-hint">Une évolution ci-dessous répond à une suggestion que vous aviez notée ? Pensez à passer son statut sur <b>Traité</b> (menu <b>•••</b> → <b>Suggestions</b>) — l'outil ne le fait pas tout seul.</p>
    ${nouveautesHTML()}
    <label class="opt-row" style="margin-top:18px;">
      <input type="checkbox" id="nvMasquer" ${masquees ? "checked" : ""}>
      <span><b>Ne plus afficher cette fenêtre automatiquement</b>
      <em>Vous ne serez plus prévenu des évolutions suivantes. Les nouveautés resteront consultables dans le menu <b>•••</b>.</em></span>
    </label>
    <div class="panel-actions"><button class="primary" id="nvFermer">J'ai vu</button></div>`;
  wrap.querySelector("#nvFermer").addEventListener("click", () => {
    try {
      localStorage.setItem(CLE_VERSION_VUE, TOOL_VERSION);
      localStorage.setItem(CLE_NOUVEAUTES_OFF, wrap.querySelector("#nvMasquer").checked ? "1" : "0");
    } catch(e){}
    fermerPanneaux();
  });
  ouvrirPanneau("nouveautesPanel");
}
/* au chargement : on n'ouvre que si la version a change depuis la derniere lecture.
   Aucune valeur enregistree = premiere fois qu'on croise cette fonction, on affiche
   (c'est ce qui fait que le premier deploiement atteint bien tout le monde). */
function verifierNouveautes(){
  let vue = null, off = false;
  try {
    vue = localStorage.getItem(CLE_VERSION_VUE);
    off = localStorage.getItem(CLE_NOUVEAUTES_OFF) === "1";
  } catch(e){ return; }
  if(off || vue === TOOL_VERSION) return;
  ouvrirNouveautes();
}

/* ---- parcours de demarrage (v4.6) ----
   La regole v4.4 — "poser la production d'abord, creer les projets ensuite" — n'etait qu'une
   convention a transmettre oralement. Elle est maintenant dans l'outil : un panneau checklist
   (menu ••• → Démarrer un suivi) et un bandeau qui s'affiche sur un suivi vierge (ni scenario
   en production, ni projet) tant que la premiere etape n'est pas faite. Le bandeau se cache
   tout seul des qu'un scénario ★ existe ou qu'un projet est créé — la cle "masquer" ne sert
   que si l'utilisateur veut garder un suivi vide sans rappel. */
const CLE_PARCOURS_MASQUE = "spk_parcours_masque";
function etatParcours(){
  const op = getActiveOp();
  const scenarios = op ? (op.scenarios || []) : [];
  return {
    prod: scenarios.some(s => s.baseline),
    projet: (projets || []).length > 0
  };
}
function ouvrirParcours(){
  const wrap = document.getElementById("parcoursPanel");
  const et = etatParcours();
  const etape = (n, titre, fait, corps) => `
    <div class="pc-step${fait ? " pc-fait" : ""}">
      <span class="pc-num">${fait ? "✓" : n}</span>
      <div class="pc-corps"><b>${titre}</b>${corps}</div>
    </div>`;
  wrap.innerHTML = `
    <h3>Démarrer un suivi</h3>
    <p class="panel-hint">L'ordre recommandé : la production d'abord, l'organisation ensuite.
    Les étapes se cochent toutes seules au fur et à mesure.</p>
    ${etape(1, "Une ligne de production", true,
      "Déjà en place — c'est le premier ruban en haut de page. « + Ligne de production » en ajoute d'autres : EMAG 2, WEISSER, HESSAP…")}
    ${etape(2, "Un scénario en production (★) sur l'OP", et.prod, et.prod
      ? "C'est le process réellement en série : il sert de base 100 à toutes les comparaisons."
      : "Le process réellement en série sur la machine : coûts, cycle, outillage. C'est la base 100 de toutes les comparaisons. S'il n'existe pas encore, ajoutez un scénario puis désignez-le avec sa pastille ★.")}
    ${etape(3, "Un premier projet", et.projet, et.projet
      ? "L'organisation du travail d'optimisation est en place : les scénarios sont étiquetés par problématique."
      : "Il regroupe les scénarios qui répondent à une même problématique (coût, qualité, « Essais Step 3 »…). Créez-le avec « + Créer un projet » : il rattachera automatiquement les scénarios de l'OP ouvert, ajustez ensuite les étiquettes.")}
    <p class="opt-note">Les projets sont facultatifs : un scénario vit très bien sans projet.
    L'essentiel est d'avoir d'abord un scénario en production à comparer.</p>
    <div class="panel-actions"><button class="primary" id="parcoursFermer">C'est parti</button></div>`;
  wrap.querySelector("#parcoursFermer").addEventListener("click", fermerPanneaux);
  ouvrirPanneau("parcoursPanel");
}
function renderParcours(){
  const el = document.getElementById("parcoursBandeau");
  if(!el) return;
  let masque = false;
  try{ masque = localStorage.getItem(CLE_PARCOURS_MASQUE) === "1"; }catch(e){}
  const et = etatParcours();
  const montrer = !et.prod && !et.projet && !masque;
  el.hidden = !montrer;
  if(!montrer) return;
  el.innerHTML = `
    <b>Démarrer</b>
    <span>Suivi vierge : commencez par poser le <b>scénario en production (★)</b> — le process réellement en série — puis créez vos projets par-dessus. C'est l'ordre recommandé pour que les comparaisons aient un sens dès le premier jour.</span>
    <button class="primary" id="parcoursVoir">Voir le parcours</button>
    <button class="ghost" id="parcoursMasquer" title="Ne plus afficher ce rappel sur ce poste">Masquer</button>`;
  el.querySelector("#parcoursVoir").addEventListener("click", ouvrirParcours);
  el.querySelector("#parcoursMasquer").addEventListener("click", () => {
    try{ localStorage.setItem(CLE_PARCOURS_MASQUE, "1"); }catch(e){}
    renderParcours();
  });
}

/* ---- tableau de bord : toutes les lignes d'un coup ----
   Le moteur lit la tolerance et le scenario de reference dans les globales `config` et
   `data`, qui pointent sur l'OP active. Pour parcourir les AUTRES OP sans threader un
   parametre dans toute la chaine de calcul, on bascule temporairement le contexte puis on
   le remet. Tout est synchrone : rien ne peut s'intercaler entre les deux. */
function dansContexteOp(op, fn){
  const cfgAvant = config, dataAvant = data;
  config = op.config; data = op.scenarios;
  try { return fn(); } finally { config = cfgAvant; data = dataAvant; }
}

/* ════════════════════════════════════════════════════════════════════════════
   v4.51.0 — Carte atelier, couche 0 : le calcul pur du poste (sans un pixel d'UI)

   Deux fonctions PURES, testées, placées juste avant renderDashboard() (L11547) parce
   que la carte atelier est une évolution du tableau de bord : même source, jamais un
   second agrégat de gains. gainPoste() alimente la tuile et, plus tard, l'A4 Mission ;
   etatTuile() donne l'état de la tuile (gagné / en cours / à chiffrer / opportunité)
   sans jamais qu'une cascade de « if » dans le HTML décide de la couleur.

   Rappel D3 : la tuile n'affiche JAMAIS un chiffre que le bandeau du scénario
   n'afficherait pas. D'où le choix de bilanAnnuel() : c'est lui qui applique déjà
   perimetreCompare() (v4.45) et qui signale perimetrePartiel. On ne recalcule rien.
   ────────────────────────────────────────────────────────────────────────── */

/* Un poste = un couple (ligne x opCode). On ne dessine que les couples DÉCLARÉS :
   les machines de la ligne viennent de LIGNES_SEPT_FONS (v4.50), et les OP sans
   code exploitable (opCode "?", v4.50) ne dessinent aucune tuile — elles restent
   atteignables par la navigation experte. */
function postesLigne(ligne, lignesSeptFons){
  const def = (lignesSeptFons || []).find(d => d.nom === (ligne && ligne.nom));
  const machines = (def && def.machines) || [];
  return machines.map(m => ({ code: m.code, nom: m.nom || "", ligne }));
}

/* Les scénarios d'une ligne qui portent l'OP demandée (par CODE, pas par nom :
   « OP 30 Perçages » et « OP30 » sont le même poste). */
function scenariosPostes(ligne, opCode){
  const out = [];
  (ligne && ligne.references ? ligne.references : []).forEach(ref => {
    (ref.ops || []).forEach(op => {
      if((op.opCode || "?") !== opCode) return;
      out.push({ ref, op, scs: op.scenarios || [] });
    });
  });
  return out;
}

/* ── Le cœur : le gain d'un poste, périmètre commun obligatoire ──────────────
   Un poste peut être servi par plusieurs références (EMAG 1 : 356x26 + 304x28) :
   on additionne référence par référence, chaque delta passant par bilanAnnuel() —
   donc par perimetreCompare() (v4.45). Jamais une soustraction de deux totaux bruts.
   Le cas asymétrique réel (une OP avec prod chiffrable, une sans) sort du calcul,
   il ne devient pas 0 : il est compté dans nonChiffres.

   Renvoie { ligne, opCode, nom, refs, gainActe, gainProjete, coutProd, coutEnCours,
             cibleCPP, chemin, essaiOuvert, nonChiffres, refDominante } */
function gainPoste(ligne, opCode, lignesSeptFons){
  const poste = (postesLigne(ligne, lignesSeptFons) || []).find(p => p.code === opCode)
              || { code: opCode, nom: "", ligne };
  const blocs = scenariosPostes(ligne, opCode);
  const refs = [];
  let gainActe = 0, gainProjete = 0, coutProd = 0, coutEnCours = 0;
  let essaiOuvert = false, nonChiffres = 0;

  blocs.forEach(b => {
    /* v4.51.2 — la cible se lit AVANT tout calcul de coût. Une référence qui porte une
       cible mais aucun scénario chiffrable est justement le cas « à chiffrer » (H1-a) :
       elle doit pouvoir le dire, donc être enregistrée dans refs même sans prod. Avant,
       le return ci-dessous la faisait disparaître de refs et la tuile tombait en
       « opportunité » — l'invitation que l'atelier doit voir disparaissait. */
    const cibleBl = cibleCPPDe(b.ref);
    /* la prod d'une OP, c'est D'ABORD la prod réelle (★), l'excel en repli (v4.49.4) */
    const excel = (b.scs || []).find(x => /base excel/i.test(x.name || ""));
    const star  = (b.scs || []).find(x => x.baseline);
    const prodSc = star || excel || null;
    if(!prodSc){
      nonChiffres++;
      if(cibleBl !== null) refs.push({ ref: b.ref, prodSc: null, meilleur: null, tBase: null,
                                       gain: null, serie: false, volume: volumeAnnuel(b.ref, b.op.config),
                                       essaiOuvert: false, nonChiffre: true });
      return;
    }

    const tBase = coutsDetail(prodSc, b.op.config, ligne).total;
    if(tBase === null){
      nonChiffres++;
      if(cibleBl !== null) refs.push({ ref: b.ref, prodSc, meilleur: null, tBase: null,
                                       gain: null, serie: false, volume: volumeAnnuel(b.ref, b.op.config),
                                       essaiOuvert: false, nonChiffre: true });
      return;
    }

    /* le meilleur scénario non-prod chiffrable : le gain ne peut se comparer que si
       l'autre côté de la comparaison est chiffrable aussi (v4.45) */
    let meilleur = null;
    (b.scs || []).forEach(sc => {
      if(prodSc.id === sc.id) return;
      const t = coutsDetail(sc, b.op.config, ligne).total;
      if(t === null) return;
      if(!meilleur || t < meilleur.cout) meilleur = { sc, cout: t };
    });

    /* même formule, même périmètre que le bandeau : bilanAnnuel() applique déjà
       perimetreCompare() et signale les postes exclus. On ne recalcule rien. */
    const an = meilleur ? bilanAnnuel(meilleur.sc, b.op.config, ligne, b.ref, prodSc) : null;
    let gain = null;
    if(an && an.gainAnnuel !== undefined) gain = an.gainAnnuel;

    const serie = !!(meilleur && meilleur.sc.statut === "serie");
    if(gain !== null){
      if(serie) gainActe += gain;
      else      gainProjete += gain;
    }
    coutProd    += tBase;
    /* v4.51.1 — « en cours » = ce que la pièce coûte AUJOURD'HUI. On crédite le
       meilleur scénario SANS condition de statut, exactement comme le fait
       pieceCPPComplet() (v4.49) : `meilleur.cout < tBase ? meilleur.cout : tBase`.
       Ma première version (4.51.0) ne créditait que le projeté, ce qui faisait
       diverger la carte du bandeau sur un poste acté (Z Code, revue croisée du §2) :
       un gain réalisé ne faisait plus bouger le chemin prod → cible, alors que c'est
       justement le chiffre que la hiérarchie doit voir. D3 (source unique) prime :
       deux modules ne doivent jamais raconter deux histoires différentes. */
    coutEnCours += (meilleur && meilleur.cout < tBase) ? meilleur.cout : tBase;

    if((b.scs || []).some(x => (x.essais || []).length)) essaiOuvert = true;

    refs.push({ ref: b.ref, prodSc, meilleur, tBase, gain, serie,
                volume: volumeAnnuel(b.ref, b.op.config), essaiOuvert: (meilleur && (meilleur.sc.essais || []).length) || false });
  });

  /* la référence DOMINANTE = celle du plus gros volume de série : c'est elle qui
     décide du chemin prod → cible affiché sur la tuile. Une tuile multi-références
     n'affiche qu'une seule cible, sinon deux chiffres se contredisent. */
  const dominante = refs.slice().sort((a, b) => (b.volume || 0) - (a.volume || 0))[0];
  const refDominante = dominante ? dominante.ref : null;
  const cible = refDominante ? cibleCPPDe(refDominante) : null;

  let chemin = null;
  if(cible !== null && cible > 0 && coutProd > cible && coutProd > 0){
    chemin = Math.max(0, Math.min(100, ((coutProd - coutEnCours) / (coutProd - cible)) * 100));
  }

  return { ligne, opCode, nom: poste.nom, refs, gainActe, gainProjete, coutProd, coutEnCours,
           cibleCPP: cible, chemin, essaiOuvert, nonChiffres, refDominante };
}

/* la cible CPP d'une référence, normalisée (nombre > 0, sinon « pas de cible ») */
function cibleCPPDe(ref){
  if(!ref || ref.cibleCPP === "" || ref.cibleCPP == null) return null;
  const v = parseFloat(ref.cibleCPP);
  return isNaN(v) || v <= 0 ? null : v;
}

/* ── L'état de la tuile : UNE fonction, jamais une cascade de if dans le HTML ──
   a) gagne      : un gain déjà acté (scénario en série) ;
   b) encours    : un essai existe sur ce poste sans gain acté ;
   c) aChiffrer  : la référence dominante a une cible CPP, mais rien n'est chiffré ;
   d) opportunite: rien de tout cela — le poste est déclaré mais pas travaillé. */
function etatTuile(poste){
  if(!poste) return "opportunite";
  if(poste.gainActe > 0) return "gagne";
  if(poste.essaiOuvert) return "encours";
  if(poste.cibleCPP !== null && poste.cibleCPP > 0) return "aChiffrer";
  return "opportunite";
}

/* ═══ v4.59.0 — gainLigne : la ligne ENTIÈRE, rollup de ses postes (Q6-B) ══════════
   La tuile-ligne de l'écran d'accueil (maquette Hermes, Benjamin : option B) lit
   TOUT ici — elle ne recalcule rien. La règle D3 s'applique au niveau au-dessus :
   ce rollup consomme gainPoste()/etatTuile()/prochaineEtapePoste()/pieceCPPComplet(),
   les sources déjà testées, et n'invente aucun second agrégat.

   Le coût pièce est ÉTIQUETÉ (décision Benjamin, Q6-B) : c'est celui de la référence
   DOMINANTE de la ligne — la plus gros volume. Un coût multi-références sans étiquette
   serait un chiffre mensonger (§3.5). L'état de la ligne n'est PAS décidé ici : la
   fonction rend les comptages factuels, la pastille se choisira au tour UI de la
   carte, devant Benjamin, avec des captures — on ne déduit pas en silence ce qui
   se présente.

   Rend { ligne, postes[t], gainActe, gainProjete, etats{gagne,encours,aChiffrer,
   opportunite}, nonChiffres, refDominante, coutPiece, etapes[{opCode,etat,texte}] } */
function gainLigne(ligne, lignesSeptFons){
  const postes = (postesLigne(ligne, lignesSeptFons) || []).map(p => {
    const poste = gainPoste(ligne, p.code, lignesSeptFons);
    const etat = etatTuile(poste);
    return { poste, etat, refs: poste.refs || [],
             etape: prochaineEtapePoste({ poste, etat, refs: poste.refs || [] }) };
  });
  const etats = { gagne: 0, encours: 0, aChiffrer: 0, opportunite: 0 };
  let gainActe = 0, gainProjete = 0, nonChiffres = 0;
  postes.forEach(t => {
    etats[t.etat]++;
    gainActe += t.poste.gainActe || 0;
    gainProjete += t.poste.gainProjete || 0;
    nonChiffres += t.poste.nonChiffres || 0;
  });
  /* la dominante de la ligne : le plus gros volume ANNUEL — même critère que la
     carte pour la dominante d'un poste (4.51.2), un niveau au-dessus */
  const refDominante = (ligne.references || []).slice()
    .sort((a, b) => (volumeAnnuel(b, (b.ops || [])[0] && b.ops[0].config) || 0)
                  - (volumeAnnuel(a, (a.ops || [])[0] && a.ops[0].config) || 0))[0] || null;
  /* v4.60 — le volume de la dominante, rendu avec elle : la tuile n'a pas à
     recalculer (D3), et « pas de volume » devient un cas LISIBLE (Q10) au lieu
     du choix arbitraire silencieux signalé par Hermes au Tour 13. */
  const volumeDominante = refDominante
    ? volumeAnnuel(refDominante, (refDominante.ops || [])[0] && refDominante.ops[0].config) : null;
  const coutPiece = refDominante ? pieceCPPComplet(refDominante, ligne) : null;
  const etapes = postes.map(t => ({ opCode: t.poste.opCode, etat: t.etat, texte: t.etape }));
  return { ligne, postes, gainActe, gainProjete, etats, nonChiffres, refDominante, volumeDominante, coutPiece, etapes };
}

/* ════════════════════════════════════════════════════════════════════════════
   v4.55.0 — LE CLASSEUR MATIS, source de production RÉELLE (option C de l'analyse
   du 29/09). Règle constitution §4.2 : rien ne quitte le poste — la lecture est
   OPTIONNELLE, manuelle, sur un fichier que l'utilisateur choisit lui-même.

   Ce que ce bloc apporte, et pourquoi c'est un changement de nature :
   · jusqu'ici la production était un SCÉNARIO déguisé (un booléen `baseline` posé
     sur un scénario d'essai) ; chaque calcul cherchait « ★ d'abord, excel en repli » ;
   · le classeur de Matis donne la production RÉELLE, chiffrée, par couple
     ligne × référence (volume en case B1 de chaque feuille « Cout pièce »), avec
     le CPP réel consommé et l'écart à la théorie ;
   · donc : le scénario-★ reste la RÉFÉRENCE DE COMPARAISON (son rôle historique,
     intact), et la production réelle devient une DONNÉE à part, importable, datée.

   Décision C (Benjamin) : on importe et on MESURE l'écart théorie/réel avant de
   décider si la production doit devenir une entité de premier niveau. Rien ici ne
   change le format des données : c'est un bloc d'observation, pas une migration.

   Un .xlsm est une archive ZIP. On lit son XML directement — aucune bibliothèque,
   aucun réseau, rien à installer. La décompression utilise DecompressionStream
   (natif Chrome/Edge, donc « un seul fichier » reste vrai).
   ────────────────────────────────────────────────────────────────────────── */

function _xmlUnescape(s){
  return String(s).replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)))
    .replace(/&amp;/g, "&");
}

/* décompresse une entrée ZIP (deflate-raw ou stored) → Uint8Array */
async function _zipRead(ent){
  if(ent.method === 0) return ent.data;
  if(typeof DecompressionStream === "undefined"){
    throw new Error("Ce navigateur ne sait pas lire un classeur Excel. Utilise Chrome ou Edge.");
  }
  const ds = new DecompressionStream("deflate-raw");
  const buf = await new Response(new Blob([ent.data]).stream().pipeThrough(ds)).arrayBuffer();
  return new Uint8Array(buf);
}

/* inventaire des entrées ZIP + accès par nom de feuille */
async function _zipOpen(file){
  const bytes = new Uint8Array(await file.arrayBuffer());
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const u16 = o => dv.getUint16(o, true), u32 = o => dv.getUint32(o, true);
  let eocd = -1;
  for(let i = bytes.length - 22; i >= Math.max(0, bytes.length - 66000); i--){
    if(u32(i) === 0x06054b50){ eocd = i; break; }
  }
  if(eocd < 0) throw new Error("Ce fichier n'est pas un classeur Excel (archive illisible).");
  const count = u16(eocd + 10);
  let off = u32(eocd + 16);
  const entries = {};
  for(let i = 0; i < count; i++){
    if(u32(off) !== 0x02014b50) break;
    const method = u16(off + 10), csize = u32(off + 20);
    const nlen = u16(off + 28), elen = u16(off + 30), clen = u16(off + 32);
    const lho = u32(off + 42);
    const name = new TextDecoder("utf-8").decode(bytes.subarray(off + 46, off + 46 + nlen));
    const lnlen = u16(lho + 26), lelen = u16(lho + 28);
    const start = lho + 30 + lnlen + lelen;
    entries[name] = { method, csize, data: bytes.subarray(start, start + csize) };
    off += 46 + nlen + elen + clen;
  }
  return entries;
}

/* les chaînes partagées (le classeur les utilise pour tous les libellés) */
async function _xlSharedStrings(entries){
  const key = Object.keys(entries).find(k => /^xl\/sharedStrings\.xml$/.test(k));
  if(!key) return [];
  const xml = new TextDecoder("utf-8").decode(await _zipRead(entries[key]));
  const out = [];
  const re = /<si>([\s\S]*?)<\/si>/g;
  let m;
  while((m = re.exec(xml))){
    out.push(_xmlUnescape([...m[1].matchAll(/<t[^>]*>([\s\S]*?)<\/t>/g)].map(x => x[1]).join("")));
  }
  return out;
}

/* <c r="A1" t="s"><v>3</v></c> → { A1: valeur } */
function _xlCells(xml, shared){
  const cells = {};
  const re = /<c r="([A-Z]+\d+)"([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g;
  let m;
  while((m = re.exec(xml))){
    const ref = m[1], attrs = m[2] || "", inner = m[3] || "";
    const t = (attrs.match(/t="([^"]+)"/) || [])[1];
    if(t === "inlineStr"){
      cells[ref] = _xmlUnescape([...inner.matchAll(/<t[^>]*>([\s\S]*?)<\/t>/g)].map(x => x[1]).join(""));
      continue;
    }
    const vm = inner.match(/<v>([\s\S]*?)<\/v>/);
    if(!vm) continue;
    const raw = _xmlUnescape(vm[1]);
    if(t === "s") cells[ref] = shared[parseInt(raw, 10)] ?? "";
    else if(t === "b") cells[ref] = raw === "1";
    else { const n = parseFloat(raw); cells[ref] = isNaN(n) ? raw : n; }
  }
  return cells;
}

/* le lien nom-de-feuille → fichier XML (workbook.xml + rels) */
async function _xlSheetMap(entries){
  const wbKey = "xl/workbook.xml", relKey = "xl/_rels/workbook.xml.rels";
  if(!entries[wbKey] || !entries[relKey]) return {};
  const wb = new TextDecoder("utf-8").decode(await _zipRead(entries[wbKey]));
  const rels = new TextDecoder("utf-8").decode(await _zipRead(entries[relKey]));
  const relMap = {};
  for(const m of rels.matchAll(/<Relationship[^>]*Id="([^"]+)"[^>]*Target="([^"]+)"[^>]*\/?>/g)){
    relMap[m[1]] = m[2].replace(/^\/?xl\//, "").replace(/^\.\//, "");
  }
  const map = {};
  for(const m of wb.matchAll(/<sheet[^>]*name="([^"]+)"[^>]*r:id="([^"]+)"[^>]*\/?>/g)){
    const target = relMap[m[2]];
    if(target) map[_xmlUnescape(m[1])] = "xl/" + target;
  }
  return map;
}

/* une feuille « Cout pièce » = un couple ligne × référence */
function _matisFeuille(nomFeuille, cells){
  const m = nomFeuille.match(/^Co[uû]t\s+pi[eè]ce\s+([EH])(\d)\s+(.+)$/i);
  if(!m) return null;
  const numOp = r => String(r || "").trim();
  const outils = [];
  for(let row = 4; row <= 140; row++){
    const numOutil = numOp(cells["A" + row]);
    if(!numOutil) continue;
    const op = numOp(cells["B" + row]);
    const mOp = op.match(/^OP\s?(\d+)/i);
    if(!mOp) continue;                     // ligne de garde : seuls les outils comptent
    const f = k => { const v = parseFloat(cells[k + row]); return isNaN(v) ? null : v; };
    /* v4.73 (Tour 34, passation Tour 33) — une ligne Excel = UN LOGEMENT : la
       connaissance métier (un porte-outil T513 porte les positions D1/D2 ; un
       MABEC = une plaquette = un logement) n'est plus perdue à la lecture.
       La ligne garde TOUS ses champs (MABEC, prix, arêtes, DDV, CPP) — rien
       n'est fabriqué. La séparation porte-outil/position est faite par
       matisPorteOutilPosition(), la fusion par reparerOutilsD1D2() en sortie. */
    /* v4.74.2 (Benjamin n°4) — l'en-tête du classeur est explicite :
       A = « N° d'outil / N° correcteur », C = « ISO », D = « MABEC ».
       L'ISO va dans logement.ref (la référence plaquette) — il était lu
       puis jeté dans « article » — et le correcteur (D1/D2 de la colonne A)
       dans outil.correcteur. */
    const iso = numOp(cells["C" + row]);
    const { position } = matisPorteOutilPosition(numOutil);
    outils.push({
      numero: numOutil, opCode: "OP" + mOp[1],
      correcteur: position || "", article: iso, mabec: numOp(cells["D" + row]),
      aretes: f("F"), prix: f("G"), ddv: f("H"),
      cppTheorique: f("I"), qteTheorique: f("J"),
      coutReelAnnuel: f("L"), cppReel: f("M"), qteReelle: f("N"), ecart: f("O"),
      logements: [ {
        nom: "logement 1",
        ref: iso,
        mabec: numOp(cells["D" + row]), article: iso,
        prix: f("G"), aretes: f("F"), charniere: f("H")
      } ]
    });
  }
  const prod = parseFloat(cells["B1"]);
  return {
    codeLigne: m[1].toUpperCase() + m[2],
    ref: m[3].trim(),
    refComplete: (numOp(cells["C2"])) || m[3].trim(),
    production: isNaN(prod) ? null : prod,
    outils: reparerOutilsD1D2(outils)
  };
}

/* ═══ La fonction pure : le récapitulatif, testable sans fichier ═══════════
   Elle prend les feuilles déjà lues et rend ce que l'écran affiche. Aucun accès
   disque ici — c'est ce qui permet de la tester (constitution : source unique). */
function matisRecap(feuilles){
  const couples = {};
  feuilles.forEach(f => {
    if(!f) return;
    const key = f.codeLigne + "·" + f.ref;
    if(!couples[key]) couples[key] = { key, codeLigne: f.codeLigne, ref: f.ref, refComplete: f.refComplete,
      production: 0, aProduction: false, outils: [], cppTheorique: 0, cppReel: 0 };
    const c = couples[key];
    if(f.production !== null && f.production > 0){ c.production = f.production; c.aProduction = true; }
    c.outils = c.outils.concat(f.outils);
  });
  const liste = Object.keys(couples).map(k => couples[k]);
  liste.forEach(c => {
    c.outils.forEach(o => {
      if(o.cppTheorique) c.cppTheorique += o.cppTheorique;
      if(o.cppReel) c.cppReel += o.cppReel;
    });
    c.ecart = (c.cppReel && c.cppTheorique) ? c.cppReel - c.cppTheorique : null;
    c.ecartPct = (c.ecart !== null && c.cppTheorique) ? (c.ecart / c.cppTheorique) * 100 : null;
    c.coutAnnuelReel = c.aProduction && c.cppReel ? c.cppReel * c.production : null;
    c.coutAnnuelTheorique = c.aProduction && c.cppTheorique ? c.cppTheorique * c.production : null;
    c.gapAnnuel = (c.coutAnnuelReel !== null && c.coutAnnuelTheorique !== null)
      ? c.coutAnnuelReel - c.coutAnnuelTheorique : null;
  });
  return liste.sort((a, b) => (b.production || 0) - (a.production || 0));
}

/* l'écart, dit en atelier — jamais un chiffre nu sans sa raison (constitution §3.5) */
function libelleEcartMatis(c){
  if(c.ecart === null) return "non mesurable — pas de CPP réel relevé sur ce couple";
  if(Math.abs(c.ecart) < 0.0005) return "consommation conforme au budget-outillage";
  if(c.ecart > 0) return `surconsommation de ${fmt(Math.abs(c.ecart), 4)} €/pièce`;
  return `sous-consommation de ${fmt(Math.abs(c.ecart), 4)} €/pièce`;
}

/* ═══ La lecture du fichier (asynchrone, manuelle, locale) ═════════════════ */
async function matisLireClasseur(file){
  const entries = await _zipOpen(file);
  const shared = await _xlSharedStrings(entries);
  const map = await _xlSheetMap(entries);
  const feuilles = [];
  for(const nom of Object.keys(map)){
    if(!entries[map[nom]]) continue;
    const xml = new TextDecoder("utf-8").decode(await _zipRead(entries[map[nom]]));
    const f = _matisFeuille(nom, _xlCells(xml, shared));
    if(f) feuilles.push(f);
  }
  return { fichier: file.name, luLe: new Date().toISOString().slice(0, 10),
           feuilles, couples: matisRecap(feuilles) };
}


/* ═══ L'ÉCRAN — le rendu de la mesure, et son ouverture ═══════════════════ */

/* le résultat de la dernière lecture : en mémoire seulement, JAMAIS écrit dans
   les données du suivi. C'est une observation, pas un import (option C). */
let matisLecture = null;

/* le couple « ligne × référence » du classeur, rapproché de la ligne de l'outil
   quand elle existe. Le classeur dit « E1 », l'outil dit « EMAG 1 » : le
   rapprochement est explicite et visible, jamais deviné en silence. */
const MATIS_LIGNE_OUTIL = { E1: "EMAG 1", E2: "EMAG 2", E3: "EMAG 3", H: "HESSAPP" };

function matisRapproche(c){
  const nomLigne = MATIS_LIGNE_OUTIL[c.codeLigne] || c.codeLigne;
  const lg = lignes.find(l => (l.nom || "").toUpperCase() === nomLigne.toUpperCase());
  const ref = lg ? lg.references.find(r => (r.nom || "").toUpperCase().includes(String(c.ref).split(" ")[0].toUpperCase())) : null;
  return { nomLigne, ligneId: lg ? lg.id : null, referenceId: ref ? ref.id : null, ref, ligne: lg || null };
}

/* ═══════════════════════════════════════════════════════════════════════════
   v4.71.0 — LA RÉPARATION DES OUTILS DÉJÀ SAISIS EN DOUBLE
   ═══════════════════════════════════════════════════════════════════════════
   Benjamin, 30/09 : « encore pas réglé le problème des logements ». Les
   garde-fous protègent la saisie à venir ; ils ne réparent rien. Or les
   doublons sont DÉJÀ dans les scénarios.

   Fonction PURE : elle rend un nouveau tableau, ne modifie aucune donnée, et
   n'est jamais appelée d'elle-même. L'atelier la déclenche, il voit le
   résultat, il accepte ou il refuse (constitution §3.1 — on ne corrige jamais
   quelqu'un contre son gré, et §3.2 — rien n'est supprimé en silence).

   Ce qu'elle fait, et RIEN D'AUTRE :
   · regroupe les outils dont la CLÉ de porte-outil est identique ;
   · donne à chaque logement le nom de sa POSITION (D1, D2…) ;
   · un logement encore provisoire qui n'a reçu aucune position prend le
     numéro de la position LIBRE la plus basse — il ne disparaît pas ;
   · MABEC, prix, arêtes, analyses, mesures et scénarios voyagent INTACTS.
   Elle ne fusionne JAMAIS deux outils de clés différentes, et ne touche
   JAMAIS à un outil qui a déjà ses positions. */
/* v4.77.0 — deux corrections sur les DONNÉES de Benjamin, avant tout regroupement.

   CAS 1 — « T2D1 », « T5D1 ». Le porte-outil et le correcteur sont collés dans le
   numéro, sans espace. matisPorteOutilPosition() sait déjà les séparer ; on
   l'applique ICI, sur les données, en écrivant le correcteur dans le champ
   `correcteur` de l'outil ET en nommant le logement. L'affichage du numéro
   devient propre (« T2 ») : c'est ce que l'atelier appelle l'outil.

   CAS 2 — « T1 » avec SEPT logements du même nom. Un merge
   sans le vouloir a empilé des logements de même nom dans un seul outil : 4 + 2
   + 1. Un outil ne peut pas avoir deux fois le même correcteur. On réduit en
   gardant le logement le plus RENSEIGNÉ — jamais le premier arrivé, qui peut être
   le plus vide — et on ne signale rien d'autre : les données du écarté ne sont
   pas perdues, elles sont simplement redondantes avec la conservée. */
function renseignerCorrecteur(outil){
  const o = outil;
  if(!o) return o;
  /* v4.77.0 — Benjamin, 01/10, sur ses données : « un outil appelé T2D1 alors que
     l'outil est T2 et le correcteur D1, non renseigné dans le bon champ ».

     Le NUMÉRO garde la valeur écrite — c'est le contrat de l'outil (les tests le
     verrouillent), et l'atelier reconnaît son propre numéro. Ce qui manquait,
     c'est le champ `correcteur`, celui que Matis remplit et qu'on veut voir.

     On le remplit donc, depuis la position, qu'elle vienne du numéro
     (« T2D1 », « T2 D1 ») ou des logements déjà nommés. Et si l'outil n'a
     aucun logement, on lui en crée un qui porte ce correcteur : sans lui,
     l'outil n'a pas de point de départ, et l'écran ne peut rien afficher. */
  const position = positionDeOutil(o);
  if(!position) return o;
  const sortie = Object.assign({}, o);
  const deja = String(o.correcteur || "").trim();
  if(!deja){
    sortie.correcteur = position;
  } else if(!deja.match(/^D\d+$/)){
    /* plusieurs correcteurs déjà notés (« D1, D2 ») : on ne rajoute pas un
       doublon si la position y est déjà. */
    const liste = deja.split(/[,;\s]+/).map(x => x.trim().toUpperCase()).filter(Boolean);
    if(!liste.includes(position)) sortie.correcteur = deja + ", " + position;
  }
  const logs = (o.logements || []).map(l => Object.assign({}, l));
  if(!logs.length){
    sortie.logements = [normalizeLogement({ nom: position })];
  } else if(!logs.some(l => String(l.nom || "").trim().toUpperCase() === position)){
    /* Règle v4.71.0, appliquée aussi ici : si l'outil ne porte QU'UN logement et
       qu'il est encore au nom de DÉFAUT (« Logement 1 »), c'est LUI qui devient
       la position. On ne crée pas un deuxième logement à côté d'un provisoire :
       ce serait exactement le fantôme que Benjamin a signalé. Un logement au nom
       d'atelier en revanche n'est pas touché — il dit plus que la position. */
    const defaut = /^\s*logement\s*\d*\s*$/i;
    const tousProvisoires = logs.every(l => defaut.test(String(l.nom || "")));
    if(logs.length === 1 && tousProvisoires){
      logs[0] = Object.assign({}, logs[0], { nom: position });
      sortie.logements = logs;
    } else {
      logs.push(normalizeLogement({ nom: position }));
      sortie.logements = logs;
    }
  }
  return sortie;
}

/* Réduit les logements de MÊME nom à un seul. On garde le plus renseigné, et à
   égalité le premier : on ne préfère jamais « le plus récent », car l'outil
   n'a aucune date de saisie par logement, et en inventer une serait exactement
   le genre de donnée fabriquee qu'on refuse partout ailleurs. */
function dedoublonnerLogements(outil){
  const logs = (outil && outil.logements) || [];
  if(logs.length < 2) return outil;
  const compte = logs.reduce((a, l) => {
    const k = String(l.nom || "").trim().toUpperCase();
    a[k] = (a[k] || 0) + 1; return a;
  }, {});
  if(!Object.values(compte).some(n => n > 1)) return outil;
  const CHAMPS = ["mabec","codeArticle","prix","charniere","ref","vc","f",
                   "kappaR","rayonBec","apPiste","tempsCoupe","tempsDeplacement"];
  const rempli = l => CHAMPS.reduce((n, c) =>
    n + (l[c] !== undefined && l[c] !== null && l[c] !== "" && l[c] !== 0 ? 1 : 0), 0);
  const vus = new Set();
  const gardes = [];
  logs.forEach(l => {
    const k = String(l.nom || "").trim().toUpperCase();
    if(!vus.has(k)){ vus.add(k); gardes.push(l); return; }
    const deja = gardes.find(g => String(g.nom || "").trim().toUpperCase() === k);
    /* on complète le logement déjà gardé avec ce que celui-ci apporte de plus :
       on ne remplace jamais une donnée par une case vide. */
    if(rempli(l) > rempli(deja)){
      for(const c of CHAMPS)
        if((deja[c] === undefined || deja[c] === "" || deja[c] === 0) && l[c] !== undefined && l[c] !== "")
          deja[c] = l[c];
    }
  });
  return Object.assign({}, outil, { logements: gardes },
    { _fusionReparee: outil._fusionReparee, nbOutils: outil.nbOutils });
}

/* v4.77.0 — Où est la POSITION d'un outil ? Elle peut vivre à trois endroits,
   selon l'âge de la donnée — et c'est exactement pour ça que la réparation ne
   voyait plus rien :

   1. dans le numéro, tant que la saisie est brute      : « T543 D1 »
   2. dans le champ `correcteur`, une fois separé        : T543 / correcteur D1
   3. dans le nom des logements, quand le champ est vide : T543 / logement « D1 »

   renseignerCorrecteur() (ci-dessus) fait passer la donnée du (1) au (2). Si le
   regroupement continuait de lire le (1) seul, il ne verrait PLUS jamais rien :
   les deux outils devenaient « T543 » et « T543 », sans position, et la fusion
   ne se déclenchait plus. On lit donc les trois, dans cet ordre, et c'est le
   (2) qui gagne quand il est rempli — parce qu'il a été écrit à la main par
   l'atelier, et qu'il fait autorité sur une déduction. */
function positionDeOutil(o){
  const depuisNumero = matisPorteOutilPosition(o && o.numero).position;
  if(depuisNumero) return depuisNumero;
  const c = String((o && o.correcteur) || "").trim().toUpperCase();
  if(c.match(/^D\d+$/)) return c;
  /* plusieurs correcteurs dans le champ (« D1, D2 ») : ce n'est pas UNE
     position, c'est un outil déjà groupé — on ne le dédouble pas. */
  if(c) return null;
  const positions = ((o && o.logements) || [])
    .map(l => String(l.nom || "").trim().toUpperCase())
    .filter(n => n.match(/^D\d+$/));
  return positions.length === 1 ? positions[0] : null;
}

function reparerOutilsD1D2(outils){
  const liste = (outils || []).map(renseignerCorrecteur);
  /* v4.77.0 — un seul outil n'a rien à regrouper, mais il peut encore avoir des
     logements en double : c'est EXACTEMENT le cas « T1 avec 7 logements ». Le
     retour rapidecourt-circuité le dédoublonnage et laissait le cas intact. */
  if(liste.length < 2) return liste.map(dedoublonnerLogements);
  const defaut = /^\s*logement\s*\d*\s*$/i;
  /* v4.73 (Tour 34) — la clé d'identité d'un outil : les outils SAISIS ont un
     id ; les lignes du LECTEUR du classeur n'en ont pas (chaque ligne Excel est
     plate). Sans fallback, fusionnes.get(undefined) ne remplace rien et
     consomme personne : l'outil fusionné était rendu DEUX FOIS (constat au
     harnais, DIAG). Déclaré AVANT tout usage (constat : TDZ). */
  const cleId = o => o.id !== undefined ? o.id : "__pos_" + o.numero;
  const groupes = new Map();
  const autres = [];
  for(const o of liste){
    const porte = matisPorteOutilPosition(o.numero).porte;
    const position = positionDeOutil(o);
    const cle = matisClePorteOutil(porte);
    /* Un outil sans position (« T543 » nu) est LAISSE TEL QUEL. On ne le verse
       pas d'office dans le groupe : il peut être un vrai outil à lui seul, et
       fusionner à l'aveugle détruirait une distinction réelle. Il est en
       revanche SIGNALÉ dans le rapport — c'est souvent lui, le parent, et
       c'est à l'atelier de trancher (constitution §3.1). */
    if(!position){ autres.push(o); continue; }
    if(!groupes.has(cle)) groupes.set(cle, []);
    groupes.get(cle).push(o);
  }
  const out = autres.slice();
  const orphelins = [];
  const fusionnes = new Map();   /* id du 1er outil du groupe -> outil fusionné */
  const consomme = new Set();
  for(const [cle, groupe] of groupes){
    if(groupe.length < 2){ if(!out.includes(groupe[0])) out.push(groupe[0]); continue; }
    /* le numéro d'affichage : celui qui a le plus de lettres, sinon le premier.
       « T 513 D1 » gagne sur « T513 D1 » — c'est la forme de l'atelier. */
    let numero = null, melhor = -1;
    for(const o of groupe){
      const n = String(o.numero || "");
      const nPortee = n.replace(/\s*[Dd]\d*\s*$/, "").trim();
      const score = nPortee.replace(/\s/g, "").length * 10 + (nPortee.includes(" ") ? 1 : 0);
      if(score > melhor){ melhor = score; numero = nPortee; }
    }
    const logements = [];
    for(const o of groupe){
      const position = positionDeOutil(o);
      for(const l of (o.logements || [])){
        const copie = Object.assign({}, l);
        const nom = String(l.nom || "").trim();
        /* un logement déjà nommé garde son nom d'atelier (« Bol », « Piste ») :
           il porte une information que la position ne dit pas.
           un logement provisoire, lui, prend la position de son outil. */
        if(defaut.test(nom)) copie.nom = position;
        logements.push(copie);
      }
    }
    /* un provisoire resté sans position n'est pas perdu : il
       reçoit la plus petite position libre. On ne supprime JAMAIS une ligne. */
    for(const o of groupe){
      const position = positionDeOutil(o);
      if(position) continue;
      for(const l of (o.logements || [])){
        const copie = Object.assign({}, l);
        if(defaut.test(String(l.nom || ""))){
          let n = 1;
          while(logements.some(x => x.nom === "D" + n)) n++;
          copie.nom = "D" + n;
        }
        logements.push(copie);
      }
    }
    /* La fusion apparaît à la place du PREMIER outil du groupe : l'atelier
       retrouve ses outils dans l'ordre où il les a saisis. Une réparation qui
       réordonne la liste pourrais le faire chercher au mauvais endroit. */
    /* v4.73 (Tour 34) — la clé d'identité : les outils SAISIS ont un id ; les
       lignes du LECTEUR du classeur n'en ont pas (chaque ligne Excel est plate).
       Sans fallback, fusionnes.get(undefined) ne remplace rien et consomme
       personne : l'outil fusionné était rendu DEUX FOIS (constat au harnais). */
    /* v4.74.2 — le correcteur : les positions du groupe (« D1 », « D2 »…),
       restituées dans le champ Correcteur de l'outil — c'est le mot de
       l'atelier, Benjamin : « le correcteur, c'est la ref après l'outil ». */
    const correcteurs = groupe.map(o => matisPorteOutilPosition(o.numero).position).filter(Boolean);
    /* l'ISO : un logement frère du même MABEC avec une ref qui n'est pas un
       MABEC la connaît (scénarios « base excel ») — on la rapporte au lieu de
       laisser le champ vide. Best effort : absent, ref reste vide. */
    const isoParMabec = {};
    liste.forEach(o => (o.logements || []).forEach(lg => {
      const m = String(lg.mabec || "").replace(/\s+/g, " ").trim();
      const r = String(lg.ref || "").trim();
      if(m && r && !estCodeMabec(r) && !isoParMabec[m]) isoParMabec[m] = r;
    }));
    logements.forEach(lg => {
      const m = String(lg.mabec || "").replace(/\s+/g, " ").trim();
      if(m && !String(lg.ref || "").trim() && isoParMabec[m]) lg.ref = isoParMabec[m];
    });
    fusionnes.set(cleId(groupe[0]), { id: groupe[0].id, numero: numero, correcteur: correcteurs.join(", "),
               logements: logements, position: "", nbOutils: groupe.length, _fusionReparee: true });
    for(const o of groupe) consomme.add(cleId(o));
    /* un outil NU de la même clé (souvent le parent) est signalé, pas touché */
    for(const o of autres){
      if(matisClePorteOutil(o.numero) === cle)
        orphelins.push('un outil « ' + o.numero + ' » sans position existe aussi : '
          + 'à vous de dire s il est le parent ou un outil distinct');
    }
  }
  /* On reconstruit dans l'ordre d'origine : chaque groupe remplacé par son
     outil fusionné, à la place de son PREMIER membre. Les autres membres sont
     absorbés. Une réparation qui réordonnerait la liste pourrait faire
     chercher un outil au mauvais endroit — et l'atelier ne le retrouverait pas. */
  const ordre = [];
  for(const o of liste){
    const fusion = fusionnes.get(cleId(o));
    if(fusion){ ordre.push(fusion); continue; }   /* 1er membre : à sa place */
    if(consomme.has(cleId(o))) continue;          /* membre absorbé : disparaît */
    if(!ordre.includes(o)) ordre.push(o);
  }
  /* v4.77.0 — en dernier, on réduit les logements en double À L'INTÉRIEUR d'un
     outil. C'est le cas « T1 avec 7 logements » : on ne peut pas avoir deux fois
     le même correcteur sur le même porte-outil. */
  const reduits = ordre.map(dedoublonnerLogements);
  reduits._orphelins = orphelins;
  reduits._reduits = ordre.length - reduits.length;
  return reduits;
}

/* Ce que la réparation a changé, en mots — pas en nombre. L'écran doit dire
   ce qu'il va advenir, sinon on demande une confiance aveugle. */
function reparerOutilsRapport(avant, apres){
  const lignes = [];
  const a = (avant || []).filter(o => o._fusionReparee);
  const b = (apres || []).filter(o => o._fusionReparee);
  for(const o of b){
    const n = (o.nbOutils || 1);
    const parts = (o.logements || []).map(l => String(l.nom || "").toUpperCase());
    lignes.push(n + " outils « " + o.numero + " » meetings en 1, avec " +
      parts.length + " logements : " + parts.join(", "));
  }
  return lignes;
}

/* ═══ v4.74.0 — LA MIGRATION des outils D1/D2 séparés, dans les DONNÉES ════════
   Le lecteur du classeur a reçu la règle (4.73) ; les données créées AVANT
   n'ont jamais été migrées : la composition de Benjamin montre encore
   « T543 D1 » et « T543 D2 » en deux outils. On ne migre PAS en silence
   (§7.4 : les données se touchent avec consentement et rapport) :
   détection au chargement → bandeau avec les noms → correction à la demande
   → rapport → sauvegarde. La fonction reparerOutilsD1D2 fait le travail :
   elle regroupe, nomme les logements par position, conserve tout, ne
   fusionne pas un outil nu. */

/* les scénarios portant AU MOINS un groupe fusionnable (2+ outils même porte,
   avec position) — avec les noms, pour le bandeau */
function detecterOutilsD1D2(scenarios){
  const touches = [];
  (scenarios || []).forEach(sc => {
    const avant = (sc.outils || []);
    const apres = reparerOutilsD1D2(avant);
    const fusions = apres.filter(o => o._fusionReparee && (o.nbOutils || 1) > 1);
    if(fusions.length){
      touches.push({ sc, fusions, apres, completOnly: false });
      return;
    }
    /* v4.81.2 — la branche « correcteur manquant » (4.74.3) est RETIRÉE du
       déclencheur. Elle détectait tout outil à logements D1/D2 dont le champ
       `correcteur` est vide : c'était le cas de TOUTE la base propre — le
       générateur laisse ce champ vide VOLONTAIREMENT, les positions vivent sur
       les logements (un logement = un correcteur, constitution 2 ter). Le
       bandeau criait donc sur un état sain, et Benjamin (13/10) : « c'est
       source de problème ! ». La détection ne voit plus que les VRAIS
       regroupements : des outils distincts qui fusionneraient. Le champ
       `correcteur` d'un outil reste rempli par la réparation elle-même
       (renseignerCorrecteur, 4.77) quand un vrai regroupement a lieu. */
  });
  return touches;
}

/* applique la correction sur TOUT le suivi (chaque scénario), rend le rapport
   en mots — l'appelant sauvegarde et rend */
function migrerOutilsD1D2(){
  const lignesModifiees = new Set();
  const rapport = [];
  lignes.forEach(l => (l.references || []).forEach(r => (r.ops || []).forEach(op =>
    (op.scenarios || []).forEach(sc => {
      const avant = sc.outils || [];
      const touches = detecterOutilsD1D2([ sc ]);
      if(!touches.length) return;
      /* reparerOutilsD1D2 rend une NOUVELLE liste (jamais la même) : c'est elle
         qui devient les outils du scénario — la mutation touche la donnée réelle */
      sc.outils = touches[0].apres.map(o => {
        const copie = Object.assign({}, o);
        delete copie._fusionReparee; delete copie.nbOutils;  /* marqueurs de rapport, pas de données */
        return copie;
      });
      lignesModifiees.add(l.nom || "?");
      /* v4.81.2 — plus de branche « correcteur rempli » : la détection ne voit
         plus que des regroupements réels (voir detecterOutilsD1D2). */
      touches[0].fusions.forEach(f => rapport.push(
        (l.nom || "?") + " · " + (r.nom || "?") + " · " + (op.nom || "?") + " : "
        + f.nbOutils + " outils « " + f.numero + " » regroupés en 1, avec "
        + (f.logements || []).length + " logements : " + (f.logements || []).map(l => l.nom).join(", ")));
    }))));
  return { rapport, lignes: Array.from(lignesModifiees) };
}

/* ═══ v4.74.1 — L'INVERSION ISO / MABEC, détectée et permutée ══════════════════
   (Benjamin, retour d'usage n°3 : « les codes MABEC du T543 sont dans le champ
   référence plaquette »). Le mapping correct est documenté depuis l'import
   4.72 : colonne ISO → logement.ref, colonne MABEC → logement.codeArticle.
   Six logements des scénarios d'atelier portaient le MABEC dans ref, sans
   codeArticle. La permutation est SÛRE à détecter : le format MABEC
   (Z000 455 182 — lettre + 3×3 chiffres) ne ressemble à aucun ISO
   (SNGN090416T00520 SN60). À la demande, comme la migration D1/D2. */
function estCodeMabec(v){
  return /^[A-Z]\d{3}\s\d{3}\s\d{3}$/.test(String(v || "").replace(/\s+/g, " ").trim());
}

function detecterInversionMabec(scenarios){
  const touches = [];
  (scenarios || []).forEach(sc => {
    const cibles = [];
    (sc.outils || []).forEach(o => (o.logements || []).forEach(lg => {
      const ref = String(lg.ref || "").trim(), ca = String(lg.codeArticle || "").trim(), mb = String(lg.mabec || "").trim();
      /* cas 1 (4.74.1) : le MABEC dans ref, sans codeArticle — à permuter ;
         cas 2 (4.74.2, conséquence de la correction) : le MABEC déjà remis
         dans codeArticle mais ref VIDE alors que l'ISO est connu ailleurs
         (base excel) — à compléter. Les deux se corrigent au même bouton. */
      if(estCodeMabec(ref) && !ca && !mb) cibles.push(lg);
      else if(!ref && ca && isoConnuPourMabec(ca)) cibles.push(lg);
    }));
    if(cibles.length) touches.push({ sc, cibles });
  });
  return touches;
}

/* l'ISO d'un MABEC, cherché dans tout le suivi (les scénarios « base excel »
   l'ont : ref = ISO, codeArticle = MABEC). null si inconnu. */
function isoConnuPourMabec(mabec){
  const cible = String(mabec || "").replace(/\s+/g, " ").trim();
  if(!cible) return null;
  let iso = null;
  lignes.forEach(l => (l.references || []).forEach(rf => (rf.ops || []).forEach(op =>
    (op.scenarios || []).forEach(sc => (sc.outils || []).forEach(ou =>
      (ou.logements || []).forEach(lg => {
        const ca = String(lg.codeArticle || "").replace(/\s+/g, " ").trim();
        const mb = String(lg.mabec || "").replace(/\s+/g, " ").trim();
        const ref = String(lg.ref || "").trim();
        if((ca === cible || mb === cible) && ref && !estCodeMabec(ref) && !iso) iso = ref;
      }))))));
  return iso;
}

function migrerInversionMabec(){
  const rapport = [];
  lignes.forEach(l => (l.references || []).forEach(rf => (rf.ops || []).forEach(op =>
    (op.scenarios || []).forEach(sc => {
      const touches = detecterInversionMabec([ sc ]);
      if(!touches.length) return;
      touches[0].cibles.forEach(lg => {
        const mabec = estCodeMabec(lg.ref) ? lg.ref : (String(lg.codeArticle || "").trim() || String(lg.mabec || "").trim());
        if(estCodeMabec(lg.ref)) lg.ref = "";  /* cas 1 : le MABEC quitte ref */
        lg.codeArticle = mabec;
        /* v4.74.2 — l'ISO du même MABEC est-il connu ailleurs (base excel) ? */
        let iso = isoConnuPourMabec(mabec);
        lignes.forEach(l2 => (l2.references || []).forEach(r2 => (r2.ops || []).forEach(o2 =>
          (o2.scenarios || []).forEach(sc2 => (sc2.outils || []).forEach(ou =>
            (ou.logements || []).forEach(lg2 => {
              const m2 = String(lg2.mabec || lg2.codeArticle || "").replace(/\s+/g, " ").trim();
              const r2v = String(lg2.ref || "").trim();
              if(m2 === mabec && r2v && !estCodeMabec(r2v) && !iso) iso = r2v;
            }))))));
        if(iso) lg.ref = iso;
        rapport.push((l.nom || "?") + " · " + (rf.nom || "?") + " · " + (op.nom || "?")
          + " · " + (lg.nom || "logement") + " (" + (sc.name || "?") + ") : MABEC " + mabec
          + " remis dans le champ MABEC"
          + (iso ? ", référence plaquette complétée depuis le classeur (" + iso + ")" : " — référence plaquette à saisir (l'ISO n'était pas dans les données)"));
      });
    }))));
  return rapport;
}

function compterInversionsMabec(){
  let n = 0;
  lignes.forEach(l => (l.references || []).forEach(rf => (rf.ops || []).forEach(op =>
    (op.scenarios || []).forEach(sc => { n += detecterInversionMabec([ sc ]).reduce((a, t) => a + t.cibles.length, 0); }))));
  return n;
}

/* le nombre de groupes fusionnables sur tout le suivi (pour la détection) */
function compterOutilsD1D2(){
  let n = 0;
  lignes.forEach(l => (l.references || []).forEach(r => (r.ops || []).forEach(op =>
    (op.scenarios || []).forEach(sc => {
      /* v4.74.3 : les cas « correcteur manquant » (completOnly) ne comptent pas
         comme des regroupements — le bandeau les annonce à part */
      n += detecterOutilsD1D2([ sc ]).reduce((a, t) => a + (t.completOnly ? 0 : t.fusions.length), 0);
    }))));
  return n;
}

/* v4.74.3 — les outils déjà regroupés dont le correcteur manque (corrigés avant
   la 4.74.2) : comptés à part, le bandeau ne dira pas « en outils séparés »
   pour un outil qui ne l'est plus. */
/* v4.81.2 — compterCorrecteursManquants est retiré : il comptait la branche
   « correcteur manquant » du détecteur, elle-même retirée (le champ est porté
   par les logements dans le modèle v3 — le compter, c'était annoncer un défaut
   là où il n'y en a pas). Le bandeau ne compte plus que les regroupements et
   les inversions ISO/MABEC. */

/* v4.58 — le porte-outil et sa position, lus du numéro du classeur (Q4).
   « T517 D2 » = le porte-outil T517, position D2 ; « T533 » = porte-outil seul,
   position inconnue. Fonction pure au service du rapprochement par article. */
function matisPorteOutilPosition(numero){
  const s = String(numero || "").trim().replace(/\s+/g, " ");
  const m = s.match(/^(.*?)\s*([Dd]\d+)$/);
  return m ? { porte: m[1].trim(), position: m[2].toUpperCase() } : { porte: s, position: null };
}

/* v4.71.0 — Benjamin, 30/09 : « l'outil T543 a 2 correcteurs D1 et D2, cela
   signifie qu'il a 2 logements, chaque logement correspond à un correcteur ».

   DÉFAUT 1 : « T 543 D1 » et « T543 D1 » sont le MÊME porte-outil. L'atelier
   tape les deux formes, et son classeur contient les deux. En l'état la
   comparaison se faisait sur la chaîne brute : deux outils distincts, pour la
   même pièce. C'est un doublon de SAISIE, pas une information.

   On ne touche PAS à ce qui est affiché — « T 513 D1 » reste « T 513 D1 ».
   On normalise seulement la CLÉ de rapprochement. */
function matisClePorteOutil(numero){
  return String(numero || "").toUpperCase().replace(/[^A-Z0-9]/g, "") || "0";
}

/* ════════════════════════════════════════════════════════════════════════════
   v4.66.0 — LE GARDE-FOU PORTE-OUTIL / LOGEMENT
   Benjamin, 30/09 : « toujours des outils créés en double au lieu d'un outil
   avec 2 logements ». Le MODÈLE est juste depuis le début — un outil porte
   une liste de logements, et « + Ajouter un logement » existe déjà. Le défaut
   est dans le VOCABULAIRE : l'atelier écrit « T517 D1 », « T517 D2 » dans son
   classeur, et l'outil propose un champ « n° d'outil » ; on saisit donc
   « T517 D1 » comme numéro d'outil, puis « T517 D2 » comme un AUTRE outil.

   C'est la confusion du 04/09 (T517 D1/D2), revenue parce que l'outil ne
   l'attrapait pas là où elle se produit : la saisie. On avait écrit la
   convention dans une infobulle — invisible tant qu'on ne survole pas, et
   surtout inutile quand on a DÉJÀ tapé le numéro.

   matisPorteOutilPosition() savait déjà séparer porte-outil et position ;
   elle n'était appelée que par le rapprochement avec le classeur.

   Ici elle est appelée À LA SAISIE, et elle ne modifie RIEN : elle propose,
   c'est un clic explicite qui réunit. On ne corrige jamais quelqu'un contre
   son gré.
   ════════════════════════════════════════════════════════════════════════ */
function proposerFusionLogement(numero, outils, outilId){
  const { porte, position } = matisPorteOutilPosition(numero);
  if(!position || !porte) return null;
  const autres = (outils || []).filter(o => o.id !== outilId);
  /* On compare les PORTES-OUTILS, pas les numéros exacts. C'est le cas réel :
     « T517 D1 » existe déjà, et l'on saisit « T517 D2 » à côté — deux numéros
     différents, un seul porte-outil. Comparer les numéros n'aurait rien vu. */
  const cible = autres.find(o => matisPorteOutilPosition(o.numero).porte === porte);
  if(!cible) return null;
  /* Si la cible porte DÉJÀ cette position, c'est un vrai doublon : rien à proposer.
     On regarde DEUX endroits, parce que la position peut vivre dans le numéro de
     l'outil (« T517 D1 », saisie maladroite) OU dans le nom du logement
     (« T517 » + logement « D1 », saisie correcte). */
  const posCible = matisPorteOutilPosition(cible.numero).position;
  if(posCible === position) return null;
  if((cible.logements || []).some(l => String(l.nom || "").trim().toUpperCase() === position)) return null;
  const mode = matisPorteOutilPosition(cible.numero).position ? "complet" : "simple";
  return { porte, position, cible, mode };
}

/* La fusion, en fonction PURE : elle rend un NOUVEAU tableau d'outils et ne
   touche jamais l'ancien — si elle se trompe, rien n'est perdu.
     simple  : le logement du doublon est versé dans l'outil propre « porte » ;
     complet : l'outil mal saisi est renommé « porte », tous ses logements y
               sont versés, et le doublon disparaît.                        */
function fusionnerOutils(outils, outilId, prop){
  if(!prop) return (outils || []).slice();
  const src = (outils || []).find(o => o.id === outilId);
  if(!src) return (outils || []).slice();
  const reste = (outils || []).filter(o => o.id !== outilId && o.id !== prop.cible.id);
  const cible = Object.assign({}, prop.cible);
  /* un logement « Logement 1 / 2 / 3 » porte un nom de DÉFAUT, pas un nom
     d'atelier : c'est ce qui le distingue de « Bol » ou « Piste », et c'est
     donc lui seul qu'on renomme d'après la position. */
  const defaut = /^\s*logement\s*\d*\s*$/i;
  const srcDefaut0 = (src.logements || []).filter(l => defaut.test(l.nom || ""));
  const logements = (cible.logements || []).map(l => Object.assign({}, l));
  const posCible = matisPorteOutilPosition(prop.cible.numero).position;
  if(prop.mode === "complet" && posCible && logements.length && defaut.test(logements[0].nom || "")){
    logements[0].nom = posCible;
  }
  const srcLogements = src.logements || [];
  /* v4.71.0 — le logement PROVISOIRE est réclamé par la première position.
     Benjamin, 30/09 : « l'outil T543 a 2 correcteurs D1 et D2, cela signifie
     qu'il a 2 logements ». Or la saisie donneait :
         T543 [Logement 1]  +  « T543 D1 »  +  « T543 D2 »
       =>  T543 [Logement 1 , D1 , D2]     ← TROIS logements pour deux correcteurs

     La règle : quand l'outil nu ne contient QU'UN logement, encore au nom de
     défaut et ENCORE VIDE, c'est ce logement-là qui devient la position. On ne
     crée rien, on ne supprime rien — on donne à un provisoire le nom qu'il
     attendait, et le reste de la liste est conservé tel quel.

     Deux conditions, et elles sont ce qui rend la règle sûre :
     · le logement doit être au nom de DÉFAUT — un logement au nom d'atelier
       (« Bol », « Piste ») dit plus que la position, on ne le touche pas ;
     · il doit être VIDE — s'il porte un MABEC, un prix ou une mesure, il
       raconte quelque chose : on ne l'écrase pas, on AJOUTE la position à côté
       et on laisse l'atelier trancher. */
  /* « VIDE » ne se teste pas sur tous les champs : `normalizeLogement` remplit
     aretes:8 et suiviTolerance:true par DÉFAUT. Les compter comme des données
     saisie rendrait la règle inapplicable — aucun logement du monde ne serait
     jamais vide. On regarde donc SEULEMENT ce que l'atelier a réellement tapé
     ou choisi : un MABEC, un prix, un code article, une référence, une mesure,
     une condition de coupe. Tout le reste, c'est la structure. */
  const CHAMPS_SAISIS = ["mabec","codeArticle","prix","charniere","ref","vc","f",
                         "kappaR","rayonBec","apPiste","tempsCoupe","tempsDeplacement"];
  const vide = l => !l || CHAMPS_SAISIS.every(c => l[c] === undefined || l[c] === null
                 || l[c] === "" || l[c] === 0);
  const premier = logements[0];
  if(prop.mode === "simple" && srcDefaut0.length === 1 && premier
     && defaut.test(premier.nom || "") && vide(premier)){
    const dejaLa = logements.some(l => String(l.nom || "").trim().toUpperCase() === prop.position);
    if(!dejaLa){
      const fusionne = Object.assign({}, premier, { nom: prop.position });
      for(const champ of Object.keys(srcDefaut0[0])){
        if(fusionne[champ] === undefined || fusionne[champ] === "" || fusionne[champ] === 0)
          fusionne[champ] = srcDefaut0[0][champ];
      }
      const gardes = logements.slice(1);   /* les autres logements sont conservés */
      return reste.concat([Object.assign({}, cible,
        { numero: prop.porte, logements: [fusionne].concat(gardes) })]);
    }
  }
  /* Règle : on renomme un logement PORTE UN NOM DE DÉFAUT (« Logement 1 »),
     parce que c'est un nom provisoire que personne n'a voulu taper. Un logement
     AU NOM d'atelier (« Bol », « Piste exterieur ») garde son nom — et dans ce
     cas on ne crée PAS de logement D2 supplémentaire : il porterait une
     information que le nom contient déjà, et il n'existe pas réellement.
     On ne fabrique jamais un logement pour satisfaire une convention. */
  const srcDefaut = srcLogements.filter(l => defaut.test(l.nom || ""));
  const srcAutres = srcLogements.filter(l => !defaut.test(l.nom || ""));
  for(const l of srcAutres) logements.push(Object.assign({}, l));
  /* le logement du doublon prend le nom de la position, en gardant ses
     données (prix, arêtes, charnière…) : la saisie n'est jamais perdue */
  const porteDonnees = srcDefaut[0];
  if(porteDonnees) logements.push(Object.assign({}, porteDonnees, { nom: prop.position }));
  cible.numero = prop.porte;
  cible.logements = logements;
  reste.push(cible);
  return reste;
}

/* v4.58 — le rapprochement par MABEC + contexte porte-outil (décision Q4 de Benjamin :
   JAMAIS le MABEC seul — une même plaquette se réutilise sur plusieurs porte-outils,
   c'est normal, et ça doit se lire comme une information, pas comme une erreur).
   Le MABEC vit sur le logement dans le champ code article (champ existant raccordé,
   pas un doublon : D3, deux champs pour la même donnée raconteraient deux histoires).
   Rend un état ET sa phrase (constitution §3.5) :
   · "match"   : ce MABEC est suivi sur CE porte-outil → le logement et son OP ;
   · "ailleurs": MABEC suivi sur un autre porte-outil — réutilisation normale ;
   · "absent"  : personne ne porte ce MABEC → l'invitation à le saisir ;
   · "sans"    : la ligne du classeur n'a pas de MABEC, rien à rapprocher.
   La lecture reste un CONSTAT : cette fonction ne touche à aucune donnée. */
function matisRapprocheMabec(oc, ligne){
  const mabec = String((oc && oc.mabec) || "").trim();
  if(!mabec) return { statut: "sans", texte: "—" };
  const { porte } = matisPorteOutilPosition(oc.numero);
  const norm = s => String(s || "").trim().toUpperCase().replace(/\s+/g, " ");
  let ailleurs = null;
  const matchs = [];
  ((ligne && ligne.references) || []).forEach(ref =>
    (ref.ops || []).forEach(op =>
      (op.scenarios || []).forEach(sc =>
        (sc.outils || []).forEach(ou => {
          const outNum = String(ou.numero || "").trim();
          /* le contexte porte-outil rattrape aussi la saisie plate « T517 D1 » en
             numéro d'outil : le porte T517 du classeur doit la reconnaître */
          const surPorte = porte && (outNum.toUpperCase() === porte.toUpperCase()
                          || outNum.toUpperCase().startsWith(porte.toUpperCase() + " "));
          (ou.logements || []).forEach(l => {
            if(norm(l.codeArticle) !== norm(mabec)) return;
            if(surPorte) matchs.push({ logement: l, outNum, opCode: op.opCode || op.nom || "" });
            else if(!ailleurs) ailleurs = { outNum: outNum || "sans n°" };
          });
        }))));
  if(matchs.length){
    const m = matchs[0];
    return { statut: "match",
             texte: `suivi : ${m.outNum} · ${m.logement.nom || "logement"}${m.opCode ? " (" + m.opCode + ")" : ""}` };
  }
  if(ailleurs) return { statut: "ailleurs", texte: `MABEC suivi ailleurs : ${ailleurs.outNum} (même plaquette, autre porte-outil)` };
  return { statut: "absent", texte: "pas encore saisi dans le suivi" };
}

/* le rapprochement, dit en atelier (4.56.0) : le classeur parle « E1 · 356x26 »,
   l'outil déclare « EMAG 1 » et ses références. Chaque couple se voit dire s'il
   existe des deux côtés, et si la production raconte la même chose des deux —
   le cas « l'excel dit 50, le terrain dit 30 » doit sauter aux yeux à la lecture,
   pas se découvrir des mois plus tard. Raison toujours à côté de l'état, jamais un
   chiffre nu (constitution §3.5) ; `attention` porte la couleur (ambre, comme les
   autres avertissements de cet écran). La lecture reste un CONSTAT : ce libellé
   n'écrit rien dans le suivi (option C, 4.55.0). */
function libelleRapprochementMatis(c, r){
  if(!r.ligneId) return { texte: `hors suivi — la ligne ${r.nomLigne} n'est pas déclarée dans l'outil`, attention: true };
  if(!r.ref) return { texte: `la référence ${c.ref} n'est pas déclarée sur la ligne ${r.nomLigne}`, attention: true };
  const dansSuivi = `dans le suivi : ${r.nomLigne} · ${r.ref.nom}`;
  if(!c.aProduction) return { texte: `${dansSuivi} — pas de production relevée dans le classeur`, attention: false };
  const ps = parseFloat(r.ref.productionAnnuelle);
  if(isNaN(ps)) return { texte: `${dansSuivi} — pas de production annuelle déclarée dans l'outil`, attention: false };
  const pc = c.production;
  const conforme = Math.abs(pc - ps) <= 0.005 * Math.max(Math.abs(pc), Math.abs(ps));
  return conforme
    ? { texte: `${dansSuivi} — production conforme (${fmt(ps, 0)}/an)`, attention: false }
    : { texte: `production en divergence — le classeur dit ${fmt(pc, 0)}/an, l'outil déclare ${fmt(ps, 0)}/an`, attention: true };
}

function matisVueHTML(){
  if(!matisLecture) return `<p class="panel-hint">Aucun classeur lu pour l'instant. Choisissez le fichier
    « SUIVI DES CONSOMMATIONS… » de Matis : il est lu <b>sur ce poste uniquement</b>, rien n'est envoyé
    nulle part, et rien n'est écrit dans le suivi.</p>
    <div class="mt-recap">
      <label class="ghost" for="mtFichier" style="cursor:pointer;padding:8px 13px;">📂 Lire le classeur de Matis…</label>
      <input type="file" id="mtFichier" accept=".xlsm,.xlsx" hidden>
    </div>`;

  const couples = matisLecture.couples || [];
  const produits = couples.filter(c => c.aProduction);
  const totalTheo = couples.reduce((a, c) => a + (c.coutAnnuelTheorique || 0), 0);
  const totalReel = couples.reduce((a, c) => a + (c.coutAnnuelReel || 0), 0);
  const ecart = totalReel - totalTheo;
  const ecartPct = totalTheo ? (ecart / totalTheo) * 100 : null;

  const tuiles = `
    <div class="mt-bilan">
      <div class="mt-tuile">
        <div class="mt-l">Budget-outillage / an</div>
        <div class="mt-v">${fmtEuroCourt(Math.round(totalTheo))}</div>
        <div class="mt-sub">théorique, d'après prix et durées de vie</div>
      </div>
      <div class="mt-tuile">
        <div class="mt-l">Consommé / an</div>
        <div class="mt-v">${fmtEuroCourt(Math.round(totalReel))}</div>
        <div class="mt-sub">réel, d'après le relevé de Matis</div>
      </div>
      <div class="mt-tuile ${ecart > 0 ? "alerte" : (ecart < 0 ? "ok" : "")}">
        <div class="mt-l">Écart</div>
        <div class="mt-v ${ecart > 0 ? "mt-ecart-pos" : (ecart < 0 ? "mt-ecart-neg" : "")}">${ecart >= 0 ? "+" : "−"}${fmtEuroCourt(Math.round(Math.abs(ecart)))}</div>
        <div class="mt-sub">${ecartPct === null ? "—" : (ecartPct >= 0 ? "+" : "−") + fmt(Math.abs(ecartPct), 0) + " % vs théorie"}</div>
      </div>
      <div class="mt-tuile">
        <div class="mt-l">Couples produits</div>
        <div class="mt-v">${produits.length}<small> / ${couples.length}</small></div>
        <div class="mt-sub">avec une production relevée</div>
      </div>
    </div>`;

  const lignes = couples.map(c => {
    const r = matisRapproche(c);
    const mesure = c.ecart === null;
    const rap = libelleRapprochementMatis(c, r);
    return `<tr>
      <td class="mt-lign">${escapeAttr(c.codeLigne)} · ${escapeAttr(c.ref)}
        <div class="mt-rap${rap.attention ? " mt-rap-attention" : ""}">${escapeAttr(rap.texte)}</div></td>
      <td class="num">${c.aProduction ? fmt(c.production, 0) : "—"}</td>
      <td class="num">${c.cppTheorique ? fmt(c.cppTheorique, 4) : "—"}</td>
      <td class="num">${c.cppReel ? fmt(c.cppReel, 4) : "—"}</td>
      <td class="num ${c.ecart > 0 ? "mt-ecart-pos" : (c.ecart < 0 ? "mt-ecart-neg" : "")}">${mesure ? "—" : (c.ecart >= 0 ? "+" : "−") + fmt(Math.abs(c.ecart), 4)}</td>
      <td class="mt-raison">${escapeAttr(libelleEcartMatis(c))}</td>
    </tr>`;
  }).join("");

  return `
    <p class="mt-raz"><b>Ce que cet écran mesure.</b> Le budget-outillage de l'outil dit ce que la
      plaquette <i>devrait</i> coûter (prix × arêtes ÷ durées de vie). Le classeur de Matis dit ce
      qu'elle <i>a réellement</i> coûté. L'écart entre les deux mesure la santé du plan outillage :
      un écart stable et connu se budgète, un écart qui grossit se traite. Rien ici n'est une
      erreur de saisie — c'est de l'écart entre un modèle et le terrain.</p>
    <div class="mt-recap">
      <label class="ghost" for="mtFichier" style="cursor:pointer;padding:8px 13px;">📂 Lire le classeur de Matis…</label>
      <input type="file" id="mtFichier" accept=".xlsm,.xlsx" hidden>
      <span class="mt-fichier">${escapeAttr(matisLecture.fichier)} — lu le ${escapeAttr(matisLecture.luLe)} · ${(matisLecture.feuilles || []).length} feuilles « Cout pièce »</span>
    </div>
    ${tuiles}
    ${(() => {
      /* v4.73 (Tour 34, point 3) — l'écran DIT ce qu'il regroupe : les outils
         fusionnés (T513 D1 + T513 D2 → T513, 2 logements) sont annoncés, en
         mots, jamais en silence. reparerOutilsRapport existe pour ça. */
      const fusions = [];
      (matisLecture.feuilles || []).forEach(f => {
        if(!f || !f.outils) return;
        f.outils.forEach(o => { if(o._fusionReparee && (o.nbOutils || 1) > 1) fusions.push(o); });
      });
      if(!fusions.length) return "";
      const phrases = fusions.map(o => `${o.numero} — ${(o.nbOutils)} outils regroupés, ${(o.logements || []).length} logements : ${(o.logements || []).map(l => l.nom).join(", ")}`);
      return `<p class="mt-fusion">🔧 ${phrases.length} porte-outil${phrases.length > 1 ? "s" : ""} regroupé${phrases.length > 1 ? "s" : ""} à la lecture : ${phrases.map(p => `« ${escapeAttr(p)} »`).join(" · ")}</p>`;
    })()}
    <div class="tbl-wrap">
      <table class="mt-tbl">
        <thead><tr><th>Couple</th><th class="num">Prod.</th><th class="num">CPP théo.</th><th class="num">CPP réel</th><th class="num">Écart</th><th>Lecture</th></tr></thead>
        <tbody>${lignes}</tbody>
      </table>
    </div>
    <p class="panel-hint" style="margin-top:12px;">Les couples à production nulle sont des postes
      ouverts ou arrêtés sur la période : ils figurent pour mémoire, ils ne comptent pas dans le bilan.
      Cette lecture est un <b>constat</b> — elle n'écrit rien dans le suivi et n'y changera rien tant
      que la décision 2 version n'aura pas été prise.</p>
    <div class="panel-actions">
      <button class="ghost" id="mtTools">Détail par outil</button>
      <button class="primary" id="mtClose">Fermer</button>
    </div>`;
}

function matisDetailHTML(){
  if(!matisLecture) return "";
  const couples = (matisLecture.couples || []).filter(c => c.aProduction);
  /* 4.58.1 — le rapprochement résumé au niveau du panneau : c'est ICI que vit
     l'invitation (contestation Hermes Tour 11), pas dans un ambre par ligne.
     Le gris discret par ligne dit « à saisir », le compteur dit combien il en reste. */
  let nMatch = 0, nAilleurs = 0, nAbsent = 0, nSans = 0;
  couples.forEach(c => {
    const r = matisRapproche(c);
    c.outils.forEach(o => {
      const st = matisRapprocheMabec(o, r.ligne).statut;
      if(st === "match") nMatch++;
      else if(st === "ailleurs") nAilleurs++;
      else if(st === "absent") nAbsent++;
      else nSans++;
    });
  });
  const parts = [];
  if(nMatch) parts.push(`${nMatch} suivie${nMatch > 1 ? "s" : ""}`);
  if(nAilleurs) parts.push(`${nAilleurs} suivie${nAilleurs > 1 ? "s" : ""} ailleurs`);
  if(nAbsent) parts.push(`<b>${nAbsent} à saisir</b>`);
  if(nSans) parts.push(`${nSans} sans MABEC dans le classeur`);
  const recapRap = parts.length
    ? ` <b>Rapprochement :</b> ${parts.join(" · ")}.` : "";
  const blocs = couples.map(c => {
    const r = matisRapproche(c);
    return `
    <div class="mt-detail" style="margin-bottom:14px;">
      <h4 style="font-family:var(--font-disp);font-size:15px;margin:0 0 6px;">${escapeAttr(c.codeLigne)} · ${escapeAttr(c.ref)}</h4>
      <div class="tbl-wrap">
        <table class="mt-tbl">
          <thead><tr><th>Outil</th><th>OP</th><th>Article</th><th>MABEC</th><th class="num">CPP théo.</th><th class="num">CPP réel</th><th class="num">Qté réelle</th><th>Dans le suivi</th></tr></thead>
          <tbody>${c.outils.map(o => {
            const rap = matisRapprocheMabec(o, r.ligne);
            /* v4.73 (Tour 34) — « T513 — 2 logements » : le nombre de logements
               est lisible sur la ligne, comme partout ailleurs. Un outil fusionné
               (_fusionReparee) l'est avec ses positions ; une ligne plate garde
               son libellé. */
            const nbLog = (o.logements || []).length;
            const numTxt = o.numero + (nbLog > 1 ? ` — ${nbLog} logements` : "");
            return `<tr>
            <td class="mt-lign">${escapeAttr(numTxt)}</td>
            <td class="mt-op">${escapeAttr(o.opCode)}</td>
            <td class="mt-op">${escapeAttr(o.article || (nbLog > 1 ? `${nbLog} articles` : "—"))}</td>
            <td class="mt-op">${escapeAttr(o.mabec || (nbLog > 1 ? `${nbLog} MABEC` : "—"))}</td>
            <td class="num">${o.cppTheorique ? fmt(o.cppTheorique, 5) : "—"}</td>
            <td class="num">${o.cppReel ? fmt(o.cppReel, 5) : "—"}</td>
            <td class="num">${o.qteReelle === null ? "—" : fmt(o.qteReelle, 0)}</td>
            <td class="mt-suivi${rap.statut === "absent" ? " mt-suivi-absent" : ""}">${escapeAttr(rap.texte)}</td>
          </tr>`; }).join("")}</tbody>
        </table>
      </div>
    </div>`;
  }).join("");
  return `<h3>Classeur Matis — détail par outil</h3>
    <p class="panel-hint">Chaque ligne du classeur est une plaquette : le porte-outil et sa
      position (« T517 D2 » = porte-outil T517, position D2), son article, son MABEC. La
      colonne « Dans le suivi » dit si cette plaquette est suivie chez nous : <b>« suivi :
      T517 · D1 (OP10) »</b> = le logement existe ; <b>« suivi ailleurs »</b> = la même
      plaquette sert sur un autre porte-outil, c'est normal ; <i>« pas encore saisi »</i> =
      à compléter dans la fiche outil, champ MABEC du logement.${recapRap}</p>
    ${blocs || `<p class="panel-hint">Aucun couple avec production relevée.</p>`}
    <div class="panel-actions"><button class="primary" id="mtDetailClose">Fermer</button></div>`;
}

function renderMatis(){
  const wrap = document.getElementById("matisPanel");
  if(!wrap) return;
  wrap.innerHTML = matisVueHTML();
  const fermer = document.getElementById("mtClose");
  if(fermer) fermer.addEventListener("click", fermerPanneaux);
  const detail = document.getElementById("mtTools");
  if(detail) detail.addEventListener("click", () => {
    const w2 = document.getElementById("matisDetailPanel");
    if(w2){
      /* v4.73.2 — le panneau est reconstruit ici, donc SES boutons se branchent
         ICI aussi : le Fermer n'avait jamais eu de handler (bug Benjamin, retour
         d'usage n°2 — un écran qui ne sait pas se fermer est un écran bloqué). */
      w2.innerHTML = matisDetailHTML();
      ouvrirPanneau("matisDetailPanel");
      const c = document.getElementById("mtDetailClose");
      if(c) c.addEventListener("click", fermerPanneaux);
    }
  });
  const fichier = document.getElementById("mtFichier");
  if(fichier) fichier.addEventListener("change", async () => {
    const f = fichier.files && fichier.files[0];
    if(!f) return;
    /* l'utilisateur a choisi SON fichier : rien n'est envoyé, rien n'est écrit */
    try {
      matisLecture = await matisLireClasseur(f);
    } catch(err){
      dialogueAlerte("Lecture impossible : " + err.message, "Classeur Matis");
      return;
    }
    renderMatis();
  });
}

function ouvrirMatis(){ renderMatis(); ouvrirPanneau("matisPanel"); }

/* ════════════════════════════════════════════════════════════════════════════
   v4.54.0 — FICHE POSTE (couche 1) : la porte qui manquait entre la carte et le détail

   La carte (4.51.2) dit QUOI : l'état, le gain, ce qui reste. La couche 2 (4.52) dit
   COMMENT : le scénario, les essais, les preuves. Entre les deux, il n'y avait rien —
   on sautait de la tuile au scénario sans jamais répondre à la seule question qui
   compte en atelier : « qu'est-ce qu'il se passe sur CETTE machine ? »

   La fiche répond à cette question, et porte une porte EXPLICITE vers la couche 2
   (« Ouvrir le poste → »). C'est le geste double (R3) : le survol / le premier
   toucher montre la fiche, le bouton entre. Le geste devient découvrable au lieu
   d'être un pari, et l'utilisateur n'est jamais forcé de deviner qu'un second
   toucher entre dans le détail.

   Trois règles tenues ici (constitution v1.1) :
   · D3 — la fiche ne montre AUCUN chiffre que le bandeau du scénario ne montre pas :
     tout vient de gainPoste() (4.51.0), jamais d'un recalcul local ;
   · la raison d'un état est toujours à côté de l'état (règle d'interface §5.2) ;
   · jamais de K ni de P_req : la fiche est présentable telle quelle.
   ────────────────────────────────────────────────────────────────────────── */

/* la prochaine étape du plan, dite en atelier : c'est l'information qui manque le
   plus dans tout l'outil aujourd'hui. Elle se déduit de l'état, jamais d'un statut
   technique stockée — donc elle ne peut pas mentir. */
function prochaineEtapePoste(t){
  const p = t.poste;
  if(t.etat === "gagne"){
    /* un poste acté se maintient : on le revalide, on ne le réinvente pas */
    const r = (p.refs || []).find(x => x.serie);
    return "En production — maintenir et confirmer au prochain rééquilibrage";
  }
  if(t.etat === "encours"){
    const r = (p.refs || []).find(x => x.meilleur && !x.serie);
    if(r && r.meilleur){
      const seuil = r.meilleur.sc.validationThreshold || 5;
      const faits = ((r.meilleur.sc.essais || []).length);
      return faits < seuil
        ? `Terminer le protocole ${seuil}× — ${faits}/${seuil} essais relevés`
        : `Protocole ${seuil}× atteint — passer en production`;
    }
    return "Essai en cours — relevés à finir";
  }
  if(t.etat === "aChiffrer"){
    return "Cible du site posée, aucune mesure : chiffrer la production de ce poste";
  }
  return "Poste déclaré, jamais travaillé — premier essai à faire";
}

/* Les scénarios du poste, regroupés par référence. C'est la lecture « par qui on
   travaille » : sur EMAG 1, OP10 sert la 356x26 et la 304x28 — la fiche le dit. */
function fichePostesReferences(t){
  return (t.poste.refs || []).map(r => {
    const st = r.serie ? "serie" : (r.gain !== null && r.gain > 0 ? "essai" : "essai");
    return { ref: r.ref, serie: r.serie, gain: r.gain, volume: r.volume,
             tBase: r.tBase, gainAnnuel: r.gain, seuil: r.meilleur ? (r.meilleur.sc.validationThreshold || 5) : null,
             nbEssais: r.meilleur ? ((r.meilleur.sc.essais || []).length) : 0,
             scId: r.meilleur ? r.meilleur.sc.id : (r.prodSc ? r.prodSc.id : null),
             statut: st };
  }).filter(x => x.scId);
}

function fichePosteHTML(t){
  const p = t.poste;
  const e = CARTE_ETATS[t.etat] || CARTE_ETATS.opportunite;
  const dom = p.refDominante;
  const nomRef = (dom && ((dom.ref && dom.ref.nom) || dom.nom)) || "";
  const refs = fichePostesReferences(t);
  const etape = prochaineEtapePoste(t);

  /* le pouls, identique à la tuile (D3 : même fonction, même valeur) */
  let pouls = "";
  if(p.gainActe > 0) pouls += `<span class="fp-acte">${p.gainActe >= 0 ? "+" : "−"}${fmtEuroCourt(Math.abs(p.gainActe))}<small>/an acté</small></span>`;
  if(p.gainProjete > 0) pouls += `<span class="fp-projete">${p.gainProjete >= 0 ? "+" : "−"}${fmtEuroCourt(Math.abs(p.gainProjete))}<small>/an projeté</small></span>`;
  if(!pouls) pouls = t.etat === "aChiffrer"
    ? `<span class="fp-invite">cible ${fmt(p.cibleCPP, 3)} €<small>— à chiffrer</small></span>`
    : `<span class="fp-vide">aucun gain chiffré</span>`;

  /* les références du poste : le travail réel, pas le concept */
  const lignesRef = refs.length ? refs.map(x => {
    /* un poste EN PRODUCTION n'a pas de protocole à faire : afficher « 0/5 essais »
       ferait croire à une absence de travail. On n'affiche l'avancement que si un
       protocole est réellement en cours (statut essai). */
    const prog = (!x.serie && x.seuil) ? `<span class="fp-ref-prog">${x.nbEssais}/${x.seuil} essais</span>` : "";
    return `
    <div class="fp-ref">
      <span class="fp-ref-nom">${escapeAttr((x.ref && x.ref.nom) || "référence")}</span>
      <span class="statut-pill ${x.serie ? "serie" : "essai"}">${x.serie ? "en production" : statutLabel("essai")}</span>
      ${x.gainAnnuel ? `<span class="fp-ref-gain">${x.gainAnnuel >= 0 ? "+" : "−"}${fmtEuroCourt(Math.abs(x.gainAnnuel))}/an</span>` : ""}
      ${prog}
    </div>`;}).join("") : `<p class="fp-note">Aucune référence travaille ce poste pour l'instant.</p>`;

  /* la porte vers la couche 2 — visible, explicite, découvrable (R3) */
  const porte = t.etat === "opportunite" ? "" : `
    <div class="fp-actions">
      <button class="primary fp-ouvrir" data-ligne="${escapeAttr(t.ligne.id)}" data-code="${escapeAttr(t.code)}"
        title="Ouvrir le scénario de production de ce poste : composition, essais, preuves">Ouvrir le poste →</button>
    </div>`;

  return `<div class="fp-fiche ${e.classe}" data-ligne="${escapeAttr(t.ligne.id)}" data-code="${escapeAttr(t.code)}" role="dialog" aria-label="Fiche poste ${escapeAttr(t.nomMachine || t.code)}">
    <div class="fp-tete">
      <div class="fp-titre-bloc">
        <p class="fp-eyebrow">${escapeAttr(t.ligne.nom || "")} · ${escapeAttr(t.code)}</p>
        <h4 class="fp-titre">${escapeAttr(t.nomMachine || t.code)}</h4>
      </div>
      <span class="ca-etat">${e.label}</span>
      <button class="ghost fp-fermer" title="Fermer la fiche" aria-label="Fermer la fiche">✕</button>
    </div>
    ${nomRef ? `<p class="fp-ref-dominante">Référence principale : <b>${escapeAttr(nomRef)}</b>${refs.length > 1 ? ` <span class="ca-refs">+${refs.length - 1} réf.</span>` : ""}</p>` : ""}
    <div class="ca-pouls fp-pouls">${pouls}</div>
    ${p.chemin === null ? "" : `
      <div class="fp-chemin">
        <span class="fp-chemin-l">Vers la cible du site</span>
        <div class="ca-track"><div class="ca-fill" style="width:${Math.round(p.chemin)}%"></div></div>
        <span class="ca-pct">${Math.round(p.chemin)} %</span>
      </div>`}
    <div class="fp-refs"><h5>Travail sur ce poste</h5>${lignesRef}</div>
    <p class="fp-etape"><b>Prochaine étape :</b> ${escapeAttr(etape)}</p>
    ${(p.nonChiffres || 0) > 0 ? `<p class="fp-avertir">${p.nonChiffres} opération${p.nonChiffres > 1 ? "s" : ""} non chiffrable${p.nonChiffres > 1 ? "s" : ""} — le gain affiché ne les compte pas.</p>` : ""}
    ${porte}
  </div>`;
}

/* l'état du panneau de fiche : null = fermé, sinon { ligneId, code } */
let fichePosteOuverte = null;

/* La fiche vit DANS la carte (superposée), pas dans un second panneau : c'est la
   couche 1 du même écran, pas une nouvelle fenêtre. Le survol desktop ouvre aussi,
   mais seulement si aucune fiche n'est déjà ouverte (sinon survoler une autre tuile
   pendant la lecture de la fiche sous le doigt). */
function renderFichePoste(tuiles, t){
  const zone = document.getElementById("carteFicheZone");
  if(!zone) return;
  /* on mémorise la fiche ouverte : c'est elle qui empêche le survol d'en remplacer
     une autre sous les yeux du lecteur, et c'est elle que le filtre doit rouvrir. */
  fichePosteOuverte = t ? { ligneId: t.ligne.id, code: t.code } : null;
  if(!t){ zone.innerHTML = ""; zone.hidden = true; return; }
  zone.hidden = false;
  zone.innerHTML = fichePosteHTML(t);
  const fermer = zone.querySelector(".fp-fermer");
  if(fermer) fermer.addEventListener("click", () => { fichePosteOuverte = null; renderFichePoste(tuiles, null); });
  const ouvrir = zone.querySelector(".fp-ouvrir");
  if(ouvrir) ouvrir.addEventListener("click", () => ouvrirPosteDepuisFiche(t));
}

/* la porte de la fiche appelle exactement le même chemin que le bouton de la tuile
   (couche 2, v4.52) : une seule implémentation de « entrer dans ce poste ». */
function ouvrirPosteDepuisFiche(t){
  const ligne = lignes.find(x => x.id === t.ligne.id);
  const bloc = scenariosPostes(ligne, t.code)[0];
  if(!bloc) return;
  const prodSc = (bloc.scs || []).find(x => x.baseline)
              || (bloc.scs || []).find(x => /base excel/i.test(x.name || ""))
              || (bloc.scs || [])[0];
  if(!prodSc) return;
  activeLigneId = ligne.id;
  activeReferenceId = bloc.ref.id;
  activeOpId = bloc.op.id;
  activeId = prodSc.id;
  fermerPanneaux();
  render();
}

/* ════════════════════════════════════════════════════════════════════════════
   v4.51.2 — CARTE ATELIER (couche 0, lecture seule)

   L'écran d'entrée spatial de l'outil : des tuiles = les postes (ligne x opCode)
   DÉCLARÉS dans LIGNES_SEPT_FONS. On lit la carte en un coup d'œil — où en est
   l'usine, qu'a-t-on gagné, qu'est-ce qui reste — puis on descend couche par couche.

   Trois règles non négociables, tenues ici :
   · D3 — la tuile ne montre AUCUN chiffre que le bandeau du scénario ne montre pas :
     tout passe par gainPoste() (4.51.0) → bilanAnnuel() → perimetreCompare() (v4.45) ;
   · le coût machine exige la ligne du poste — c'est pour ça que gainPoste() passe
     la ligne à coutsDetail(), alors que pieceCPPComplet() (v4.49) s'appuie sur le
     repli getActiveLigne() et n'a donc de sens qu'en contexte d'une référence
     ouverte. La carte et l'A4 Mission consomment gainPoste(), jamais pieceCPPComplet ;
   · jamais de K ni de P_req : la carte est présentable telle quelle en réunion.
   ────────────────────────────────────────────────────────────────────────── */

/* Le filtre de la carte : le projet actif par défaut (H1-b), « toute l'usine » à un clic.
   null = toute l'usine. Mémorisé comme le filtre du tableau de bord, mais indépendant :
   chaque écran a SON filtre, sinon les deux se marchent dessus. */
let carteFiltreProjetId = null;
let carteProjetChoisi = false;   // false = suit le projet actif tant qu'on n'a pas choisi

/* Les postes visibles sur la carte. Une tuile = (ligne déclarée x machine déclarée).
   La ligne doit exister dans les données (sinon on dessine une ligne sans suivi) ; la
   machine vient de la déclaration, jamais des scénarios rencontrés. */
function cartePostes(){
  const out = [];
  lignes.forEach(ligne => {
    postesLigne(ligne, LIGNES_SEPT_FONS).forEach(m => {
      const poste = gainPoste(ligne, m.code, LIGNES_SEPT_FONS);
      out.push({ ligne, code: m.code, nomMachine: m.nom, poste,
                 blocs: scenariosPostes(ligne, m.code),
                 etat: etatTuile(poste), refs: poste.refs || [] });
    });
  });
  return out;
}

/* Le filtre projet : « mon projet » garde les postes qui portent au moins un scénario
   étiqueté dans le projet. On ne filtre pas sur le gain mais sur la présence — sinon un
   poste « à chiffrer » (encore vide) disparaît justement quand on cherche à le remplir.
   ⚠ les étiquettes de projet sont des QUADRUPLETS exacts (ligne + référence + OP +
   scénario, cf. projetContientScenario et resoudreTag) : passer opId à null ne
   matcherait jamais. On récapitule donc les scénarios par bloc, avec l'OP d'origine. */
function carteVisiblePostes(tous, pjId){
  if(!pjId) return tous;
  const pj = projets.find(p => p.id === pjId);
  if(!pj) return tous;
  return tous.filter(t => t.blocs.some(b =>
    (b.scs || []).some(sc => projetContientScenario(pj, t.ligne.id, b.ref.id, b.op.id, sc.id))));
}

/* Le décompte de recette A2 : quelle part des tuiles porte une information
   ACTIONNABLE (un gain, une cible, un essai ouvert) ? C'est le seuil qui dira si la
   carte est utile ou décorative — mesuré, pas ressenti. */
function carteRecetteA2(tuiles){
  if(!tuiles.length) return { total: 0, actionnables: 0, ratio: 0 };
  const actionnables = tuiles.filter(t => t.etat === "gagne" || t.etat === "encours" || t.etat === "aChiffrer").length;
  return { total: tuiles.length, actionnables, ratio: actionnables / tuiles.length };
}

/* ── Le rendu ─────────────────────────────────────────────────────────────── */
const CARTE_ETATS = {
  gagne:      { label: "Gagné",       classe: "gagne" },
  encours:    { label: "En cours",    classe: "encours" },
  aChiffrer:  { label: "À chiffrer",  classe: "achiffrer" },
  opportunite:{ label: "Opportunité", classe: "opportunite" }
};

function carteTuileHTML(t, pjId){
  const p = t.poste;
  const e = CARTE_ETATS[t.etat] || CARTE_ETATS.opportunite;
  const dom = p.refDominante;
  const autres = Math.max(0, (p.refs || []).length - 1);

  /* le pouls : deux chiffres, jamais plus (D2). Acté en gros s'il existe, projeté en
     dessous. Un poste sans gain n'affiche PAS de 0 € — il affiche son invitation
     (« à chiffrer ») ou son silence (opportunité). */
  let pouls = "";
  if(p.gainActe > 0){
    pouls = `<span class="ca-acte">${p.gainActe >= 0 ? "+" : "−"}${fmtEuroCourt(Math.abs(p.gainActe))}<small>/an acté</small></span>`;
  }
  if(p.gainProjete > 0){
    pouls += `<span class="ca-projete">${p.gainProjete >= 0 ? "+" : "−"}${fmtEuroCourt(Math.abs(p.gainProjete))}<small>/an projeté</small></span>`;
  }
  if(!pouls){
    pouls = t.etat === "aChiffrer"
      ? `<span class="ca-invite">cible ${fmt(p.cibleCPP, 3)} €<small>— à chiffrer</small></span>`
      : `<span class="ca-vide">—</span>`;
  }

  /* le chemin prod → cible : la barre que la hiérarchie regarde. */
  const chemin = p.chemin === null ? "" :
    `<div class="ca-chemin" title="Part du chemin vers la cible du site déjà parcourue sur ce poste">
       <div class="ca-track"><div class="ca-fill" style="width:${Math.round(p.chemin)}%"></div></div>
       <span class="ca-pct">${Math.round(p.chemin)} %</span>
     </div>`;

  /* le libellé du poste : le nom de la machine s'il est déclaré, le code d'OP sinon.
     Jamais l'inverse — « OP10 » ne dit rien, « Ébauche piste » si. */
  const titre = escapeAttr(t.nomMachine || t.code);
  /* refDominante est l'ENTRÉE { ref, volume, ... } du tableau refs (le premier du
     poste trié par volume), pas l'objet référence : d'où ref.nom, pas ref.ref.nom. */
  const sousTitre = escapeAttr((dom && dom.ref && dom.ref.nom) || (dom && dom.nom) || "aucune référence");
  const nbRef = autres > 0 ? `<span class="ca-refs" title="${autres} autre(s) référence(s) sur ce poste">+${autres} réf.</span>` : "";

  /* le multi-geste (R3) : la tuile elle-même EST la fiche couche 1 (survol = titre
     déjà visible, tap = la même fiche ouverte), et le bouton « Ouvrir le poste → »
     qu'elle porte est la porte explicite vers la couche 2. Un seul survol, pas
     deux couches de survol qui se marchent dessus. */
  return `<div class="ca-tuile ${e.classe}" data-ligne="${escapeAttr(t.ligne.id)}" data-code="${escapeAttr(t.code)}" tabindex="0" role="button">
    <div class="ca-tete">
      <span class="ca-titre">${titre}</span>
      <span class="ca-etat">${e.label}</span>
    </div>
    <div class="ca-ref-ligne">${sousTitre} ${nbRef}</div>
    <div class="ca-pouls">${pouls}</div>
    ${chemin}
    ${t.etat === "opportunite" ? `<div class="ca-tentant">déclaré, jamais travaillé</div>` : ""}
    ${(p.nonChiffres || 0) > 0 ? `<div class="ca-avertir" title="Une opération de ce poste n'est pas chiffrable : le gain affiché ne la compte pas.">${p.nonChiffres} opération${p.nonChiffres > 1 ? "s" : ""} à chiffrer</div>` : ""}
    ${t.etat !== "opportunite" ? `<div class="ca-actions"><button class="primary small ca-ouvrir" data-ligne="${escapeAttr(t.ligne.id)}" data-code="${escapeAttr(t.code)}" title="Naviguer vers ce poste : scénarios, essais, preuves (couche 2)">Ouvrir le poste →</button></div>` : ""}
  </div>`;
}

function renderCarte(){
  const wrap = document.getElementById("cartePanel");
  if(!wrap) return;

  /* H1-b : la carte s'ouvre sur le projet actif tant que l'utilisateur n'a pas choisi
     explicitement un filtre sur la carte elle-même. */
  if(!carteProjetChoisi) carteFiltreProjetId = activeProjetId || null;
  const pj = carteFiltreProjetId ? projets.find(p => p.id === carteFiltreProjetId) : null;

  const tous = cartePostes();
  const visibles = carteVisiblePostes(tous, carteFiltreProjetId);
  const recette = carteRecetteA2(visibles);

  /* le décompte d/usine : la carte doit raconter l'usine entière même filtrée. */
  const parLigne = {};
  tous.forEach(t => { (parLigne[t.ligne.nom || "?"] = parLigne[t.ligne.nom || "?"] || []).push(t); });

  const sections = lignes.map(ligne => {
    const tuilesL = visibles.filter(t => t.ligne.id === ligne.id);
    if(!tuilesL.length) return "";
    const nom = ligne.nom || "Ligne sans nom";
    const gainL = tuilesL.reduce((a, t) => a + (t.poste.gainActe || 0), 0);
    const infos = [];
    if(ligne.coutHoraire !== "" && !isNaN(parseFloat(ligne.coutHoraire))) infos.push(fmt(parseFloat(ligne.coutHoraire), 2) + " €/h");
    infos.push(`${tuilesL.filter(t => t.etat === "gagne").length} gagné${tuilesL.filter(t => t.etat === "gagne").length > 1 ? "s" : ""}`);
    return `<section class="ca-ligne" data-ligne-id="${escapeAttr(ligne.id)}">
      <h3 class="ca-ligne-titre">${escapeAttr(nom)}
        <span class="ca-ligne-info">${escapeAttr(infos.join(" · "))}</span>
        ${gainL > 0 ? `<span class="ca-ligne-gain">+${fmtEuroCourt(gainL)}/an acté</span>` : ""}
      </h3>
      <div class="ca-grille">${tuilesL.map(t => carteTuileHTML(t, carteFiltreProjetId)).join("")}</div>
    </section>`;
  }).join("");

  const filtreHTML = projets.length ? `
    <div class="ca-filtre">
      <label for="caFiltreProjet">Vue</label>
      <select id="caFiltreProjet">
        <option value="">Toute l'usine</option>
        ${projets.map(x => `<option value="${x.id}" ${x.id === carteFiltreProjetId ? "selected" : ""}>Projet « ${escapeAttr(x.nom)} »</option>`).join("")}
      </select>
      <span class="ca-filtre-note">${pj
        ? `Postes étiquetés dans « ${escapeAttr(pj.nom)} ».`
        : "Toutes les machines déclarées de l'usine."}</span>
    </div>` : `<p class="panel-hint">Aucun projet défini : la carte montre toute l'usine. Créez un projet pour la filtrer.</p>`;

  wrap.innerHTML = `
    <h3>Carte atelier</h3>
    ${filtreHTML}
    <p class="panel-hint">Une tuile = une machine, lisible en un coup d'œil. Un poste marqué <b>À chiffrer</b> porte une cible du site mais n'a pas encore de mesure : c'est une invitation, pas un poste raté. Touchez une tuile pour sa fiche, puis « Ouvrir le poste » pour entrer dans le détail.</p>
    <div class="ca-recette" title="Part des tuiles portant une information actionnable (gain, cible ou essai ouvert)">
      <b>${recette.actionnables}</b> tuiles actionnables sur ${recette.total} — ${Math.round(recette.ratio * 100)} %
      ${recette.ratio >= 1/3 ? `<span class="ca-ok">carte utile</span>` : `<span class="ca-faible">carte creuse — filtrer par projet</span>`}
    </div>
    <div class="carte-fiche-zone" id="carteFicheZone" hidden></div>
    ${sections || `<p class="panel-hint">Aucun poste à afficher${pj ? " dans ce projet" : ""}. Les machines déclarées par l'atelier dessinent la carte ; un poste sans donnée reste visible en « Opportunité ».</p>`}
    ${livraisonsSectionHTML()}
    <div class="panel-actions"><button class="ghost" id="missionA4Btn">🖨 A4 Mission</button><button class="primary" id="carteClose">Fermer</button></div>
  `;

  const btn = document.getElementById("carteClose");
  if(btn) btn.addEventListener("click", fermerPanneaux);
  /* v4.52 — couche 2 : « Ouvrir le poste → » positionne la navigation experte sur la
     prod du poste (★ puis excel) et referme la carte ; le retour « ⇠ Carte atelier »
     vit dans la zone Traçabilité (A1). */
  wrap.querySelectorAll(".ca-ouvrir").forEach(b => {
    b.addEventListener("click", () => {
      const ligne = lignes.find(x => x.id === b.getAttribute("data-ligne"));
      const code = b.getAttribute("data-code");
      if(!ligne) return;
      const bloc = scenariosPostes(ligne, code)[0];
      if(!bloc) return;
      const prodSc = (bloc.scs || []).find(x => x.baseline)
                  || (bloc.scs || []).find(x => /base excel/i.test(x.name || ""))
                  || (bloc.scs || [])[0];
      if(!prodSc) return;
      activeLigneId = ligne.id;
      activeReferenceId = bloc.ref.id;
      activeOpId = bloc.op.id;
      activeId = prodSc.id;
      fermerPanneaux();
      render();
    });
  });
  /* v4.54.0 — couche 1 : la fiche poste. Le geste double (R3) : le survol (desktop)
     ou le PREMIER toucher (tablette) ouvre la fiche, qui porte la porte explicite
     « Ouvrir le poste → ». On ne force personne à deviner qu'un second geste entre.
     Sur desktop, le survol n'ouvre QUE si aucune fiche n'est déjà ouverte : sinon on
     substituerait la fiche sous les yeux de qui est en train de la lire. */
  const touche = () => window.matchMedia && window.matchMedia("(pointer: coarse)").matches;
  const trouver = (ligneId, code) => visibles.find(t => t.ligne.id === ligneId && t.code === code);
  wrap.querySelectorAll(".ca-tuile").forEach(tuile => {
    const ligneId = tuile.getAttribute("data-ligne"), code = tuile.getAttribute("data-code");
    const ouvrirFiche = () => { const t = trouver(ligneId, code); if(t) renderFichePoste(visibles, t); };
    tuile.addEventListener("mouseenter", () => { if(!touche() && !fichePosteOuverte) ouvrirFiche(); });
    /* premier toucher : la fiche. Si elle est déjà ouverte sur CETTE tuile, on ne
       referme pas (le second appui sert à suivre le bouton, pas à refermer). */
    tuile.addEventListener("click", (ev) => {
      if(ev.target && ev.target.closest && ev.target.closest(".ca-ouvrir")) return; // le bouton fait son office
      if(touche() || !fichePosteOuverte) ouvrirFiche();
    });
    tuile.addEventListener("keydown", (ev) => { if(ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); ouvrirFiche(); } });
  });

  /* v4.52 — A4 Mission : impression dédiée (le conteneur est appendé au body pour que
     la CSS d'impression n'affiche que lui). */
  /* v4.53 — livraisons : créer, imprimer, supprimer */
  const creer = document.getElementById("lvCreer");
  if(creer) creer.addEventListener("click", () => {
    const defaut = "Livraison 2026/2027 — " + new Date().toLocaleDateString("fr-FR");
    dialogueDemander("Nom de la livraison (elle fige les gains du jour et ne se recalcule plus) :", defaut, { titre: "Nouvelle livraison" }).then(nom => {
      if(nom === null) return;
      livraisons = (livraisons || []).concat([creerLivraison(String(nom).trim() || defaut)]);
      saveData(); renderCarte();
    });
  });
  wrap.querySelectorAll(".lv-print").forEach(b => b.addEventListener("click", () => {
    const l = (livraisons || []).find(x => x.id === b.getAttribute("data-lv"));
    if(!l) return;
    const el = document.getElementById("livraisonImpression") || document.body.appendChild(Object.assign(document.createElement("div"), { id: "livraisonImpression", hidden: true }));
    el.innerHTML = livraisonImpressionHTML(l);
    document.body.classList.add("print-livraison");
    const nettoie = () => { document.body.classList.remove("print-livraison"); window.removeEventListener("afterprint", nettoie); };
    window.addEventListener("afterprint", nettoie);
    window.print();
    setTimeout(nettoie, 2000);
  }));
  wrap.querySelectorAll(".lv-del").forEach(b => b.addEventListener("click", () => {
    const l = (livraisons || []).find(x => x.id === b.getAttribute("data-lv"));
    if(!l) return;
    dialogueConfirmer("Supprimer la livraison « " + (l.nom || "") + " » ?\n\nLes données des scénarios, essais et cibles ne sont pas touchées — seule la copie figée disparaît.",
      { titre: "Supprimer la livraison ?", okLabel: "Supprimer" }).then(ok => {
      if(!ok) return;
      livraisons = (livraisons || []).filter(x => x.id !== l.id);
      saveData(); renderCarte();
    });
  }));

  const mBtn = document.getElementById("missionA4Btn");
  if(mBtn) mBtn.addEventListener("click", () => {
    const el = document.getElementById("missionA4") || document.body.appendChild(Object.assign(document.createElement("div"), { id: "missionA4", hidden: true }));
    el.innerHTML = missionA4HTML();
    document.body.classList.add("print-mission");
    const nettoie = () => { document.body.classList.remove("print-mission"); window.removeEventListener("afterprint", nettoie); };
    window.addEventListener("afterprint", nettoie);
    window.print();
    setTimeout(nettoie, 2000);
  });
  const sel = document.getElementById("caFiltreProjet");
  if(sel) sel.addEventListener("change", () => {
    carteFiltreProjetId = sel.value || null; carteProjetChoisi = true;
    renderCarte();
    /* v4.54.0 — la fiche ouverte survit au changement de filtre SI le poste est encore
       visible ; sinon elle se referme proprement. Sans ça, changer de filtre laisserait
       une fiche orpheline affichée pour un poste qui n'est plus à l'écran. */
    if(fichePosteOuverte){
      const encore = visibles.find(t => t.ligne.id === fichePosteOuverte.ligneId && t.code === fichePosteOuverte.code);
      renderFichePoste(visibles, encore || null);
    }
  });
}

/* l'entrée : le bouton de la barre d'outils ouvre la carte (v4.51.2) */
function ouvrirCarte(ligneId){
  renderCarte();
  ouvrirPanneau("cartePanel");
  /* v4.75 — depuis l'accueil : la tuile cliquée mène À SA LIGNE, pas au début
     de la carte. La section est mise en évidence deux secondes. */
  if(ligneId){
    const sec = document.querySelector('#cartePanel .ca-ligne[data-ligne-id="' + ligneId + '"]');
    if(sec){
      /* le panneau est le conteneur scrollable : on y deplace la section */
      const panneau = document.getElementById("cartePanel");
      panneau.scrollTop = sec.offsetTop - panneau.offsetTop - 8;
      sec.classList.add("ca-ligne-ciblee");
      setTimeout(() => sec.classList.remove("ca-ligne-ciblee"), 2000);
    }
  }
}

/* ════════════════════════════════════════════════════════════════════════════
   v4.60.0 — L'ÉCRAN D'ACCUEIL : la carte en tuiles de LIGNES (le « premier écran »)

   Une tuile = une ligne entière (EMAG 1 avec ses postes et ses références), pas
   une machine — la machine, c'est la carte atelier (couche 0, 4.51.2). La tuile
   lit TOUT dans gainLigne() (4.59) : elle ne recalcule rien (D3, un niveau
   au-dessus). La porte de sortie : « Voir l'atelier → » ouvre la carte atelier —
   la descente naturelle ligne → machines → fiche → poste, jamais de porte morte.

   Trois décisions tracées :
   · la PASTILLE de la ligne se déduit des comptages, PRIORITÉ À L'ATTENTION :
     à chiffrer (la cible est posée, la mesure manque — l'invitation ouverte
     H1-a) > essais en cours > gagné > jamais travaillé. La maquette hésitait
     (EMAG 1 vert avec des essais en cours) ; cette règle est la seule qui soit
     cohérente avec prochaineEtapePoste() : la pastille dit l'action la plus
     urgente, le gain parle en dessous. MOT + couleur, jamais la couleur seule ;
   · le COÛT est étiqueté par la référence dominante (Q6-B, Benjamin) :
     « 356x26 : 0,63 €/pce · +1 réf. » — jamais un coût multi-références nu ;
   · sans VOLUME ANNUEL : « — » + « volume annuel à saisir » (Q10, Benjamin).
     C'est le piège signalé par Hermes au Tour 13 : sans volume, la dominante
     serait un choix arbitraire silencieux — l'écran le dit au lieu de le cacher.
   La RECETTE A2 vit sur l'écran : tuiles actionnables / total, alerte creuse
   sous 1/3 — un écran qui ne sert pas doit le dire (leçon 4.51.2). */

/* la pastille de la ligne : un état ET son libellé, déduits des comptages */
function etatLigne(gl){
  const n = gl.etats;
  if(n.aChiffrer > 0) return { etat: "aChiffrer", label: `${n.aChiffrer} poste${n.aChiffrer > 1 ? "s" : ""} à chiffrer` };
  if(n.encours > 0)   return { etat: "encours",   label: `Essais en cours` };
  if(n.gagne > 0)     return { etat: "gagne",     label: `${n.gagne} poste${n.gagne > 1 ? "s" : ""} gagné${n.gagne > 1 ? "s" : ""} — en production` };
  /* une ligne déclarée SANS machines (cas réel : Weisser/PCI hors périmètre) ne
     dit pas « 0 poste ouvert » — elle dit ce qui manque : les machines */
  if((gl.postes || []).length === 0) return { etat: "opportunite", label: `machines à déclarer` };
  return { etat: "opportunite", label: `${n.opportunite} poste${n.opportunite > 1 ? "s" : ""} ouvert${n.opportunite > 1 ? "s" : ""}` };
}

function accueilTuileHTML(gl){
  const e = CARTE_ETATS[etatLigne(gl).etat];
  const badge = etatLigne(gl).label;
  const l = gl.ligne;

  /* le sous-titre : les références de la ligne (3 max, +n au-delà), puis les OP
     déclarées — la ligne se présente comme Matis la pense. */
  const refsNoms = (l.references || []).map(r => r.nom).filter(Boolean);
  const refsTxt = refsNoms.length
    ? refsNoms.slice(0, 3).join(" · ") + (refsNoms.length > 3 ? ` +${refsNoms.length - 3} réf.` : "")
    : "aucune référence déclarée";

  /* le pouls : deux chiffres, jamais plus (D2). Deux blocs DISTINCTS et
     étiquetés — acté et en cours ne se mélangent pas (§3.4). Un gain nul ne
     s'affiche pas : « 0 € » voudrait dire « rien à gagner » (§3.5). */
  let pouls = "";
  if(gl.gainActe > 0) pouls += `<span class="ca-acte">+${fmtEuroCourt(gl.gainActe)}<small>/an acté</small></span>`;
  if(gl.gainProjete > 0) pouls += `<span class="ca-projete">+${fmtEuroCourt(gl.gainProjete)}<small>/an en cours</small></span>`;

  /* le coût étiqueté dominante (Q6-B) — ou son absence DITE (Q10).
     4.60.1, revue sur données réelles : deux corrections de conformité —
     · une ligne SANS références ne dit pas « volume annuel à saisir » : sa
       pastille dit déjà « machines à déclarer », la seconde invitation se
       contredirait (sur l'écran réel, 6 tuiles_WEISSER/PCI portaient le double
       message) ;
     · un coût PARTIEL se déclare (§3.2 : un poste non chiffrable se déclare, il
       ne devient pas un coût complet en silence) : « 0,763 €/pce » sur EMAG 1
       ne couvrait pas les OP non chiffrées sans le dire. */
  let cout = "";
  const nbNonChiffrees = gl.coutPiece ? (gl.coutPiece.nonChiffrees || []).length : 0;
  if(!(l.references || []).length){
    cout = "";
  } else if(!gl.volumeDominante){
    cout = `<div class="al-cout al-manque">— <span>volume annuel à saisir</span></div>`;
  } else if(!gl.coutPiece){
    cout = `<div class="al-cout al-manque">— <span>aucune opération chiffrée</span></div>`;
  } else {
    const autres = Math.max(0, (l.references || []).length - 1);
    cout = `<div class="al-cout">${escapeAttr(gl.refDominante.nom)} : <b>${fmt(gl.coutPiece.prod, 3)} €/pce</b>`
         + (autres > 0 ? ` <span class="ca-refs" title="${autres} autre(s) référence(s) sur cette ligne">+${autres} réf.</span>` : "")
         + `</div>`;
    if(nbNonChiffrees > 0){
      cout += `<div class="al-manque" style="margin-top:1px;">hors ${nbNonChiffrees} opération${nbNonChiffrees > 1 ? "s" : ""} non chiffrée${nbNonChiffrees > 1 ? "s" : ""}</div>`;
    }
    if(gl.coutPiece.chemin !== null){
      cout += `<div class="ca-chemin" title="Part du chemin vers la cible du site déjà parcourue sur la référence dominante">
        <div class="ca-track"><div class="ca-fill" style="width:${Math.round(gl.coutPiece.chemin)}%"></div></div>
        <span class="ca-pct">${Math.round(gl.coutPiece.chemin)} % · cible ${fmt(gl.coutPiece.cible, 3)} €</span></div>`;
    }
  }

  /* le à-faire : les étapes des postes NON gagnés, deux max en clair — la
     suite de prochaineEtapePoste() (4.54), déduite, jamais stockée. */
  const aFaire = gl.etapes.filter(x => x.etat !== "gagne" && x.etat !== "opportunite");
  const afTxt = aFaire.length
    ? `<div class="al-afaire"><span class="al-afaire-l">À faire</span>${aFaire.slice(0, 2).map(x =>
        `<span>${escapeAttr(x.opCode)} — ${escapeAttr(x.texte)}</span>`).join("")}`
      + (aFaire.length > 2 ? `<span class="al-afaire-plus">+${aFaire.length - 2} autre${aFaire.length > 3 ? "s" : ""}</span>` : "")
      + `</div>`
    : "";

  /* v4.65.1 (C5′ bloc 2) — le taux horaire SOURCÉ de la ligne, à côté du nom ;
     absent, il ne s'affiche pas (§5.6 : pas de « — » décoratif sur un détail). */
  const th = parseFloat(l.coutHoraire);
  const thTxt = !isNaN(th) && th > 0 ? ` <span class="al-taux" title="Coût horaire machine de la ligne">${fmt(th, 0)} €/h</span>` : "";

  /* le contexte en italique : LE fait le plus important, VÉRIFIABLE — la
     première étape en attente ; si tout est gagné, le maintien à revalider.
     Jamais une phrase d'ambiance (spec C5 §1.4). */
  const contexte = aFaire.length
    ? `${aFaire[0].opCode} — ${aFaire[0].texte}`
    : (gl.etats.gagne > 0 ? `${gl.etats.gagne} poste${gl.etats.gagne > 1 ? "s" : ""} en production — à revalider au prochain rééquilibrage` : "");

  /* gain unitaire + gain annuel CÔTE À CÔTE (spec C5 §1.4) : le Δ de CPP de la
     dominante (prod − enCours — sourcé pieceCPPComplet) à côté du gain annuel.
     Sans Δ mesurable : rien, pas un 0 (§5.6). */
  let delta = null;
  if(gl.coutPiece && gl.coutPiece.enCours !== undefined && gl.coutPiece.enCours < gl.coutPiece.prod){
    delta = gl.coutPiece.prod - gl.coutPiece.enCours;
  }
  const deltaTxt = delta !== null
    ? `<span class="al-delta" title="Écart de coût pièce déjà réalisé sur la référence dominante">Δ ${fmt(delta, 4)} €/pce</span>` : "";

  /* l'emplacement photo : PRÉVU, VIDE — pas de photo fictive (spec C5 §1.4,
     on attend Matis). Un cadre discret qui dit ce qu'il attend. */
  const photo = `<div class="al-photo" title="Emplacement prévu pour la photo de la machine — aucune photo fictive">photo machine à fournir</div>`;

  return `<div class="ca-tuile ${e.classe} al-tuile" data-ligne="${escapeAttr(l.id)}" tabindex="0" role="button" title="Voir cette ligne sur la carte atelier">
    <div class="ca-tete"><span class="ca-titre">${escapeAttr(l.nom || "Ligne sans nom")}${thTxt}</span><span class="ca-etat">${escapeAttr(badge)}</span></div>
    <div class="al-corps">
      ${photo}
      <div class="al-flux">
        <div class="ca-ref-ligne">${escapeAttr(refsTxt)}</div>
        <div class="ca-pouls">${pouls || '<span class="ca-vide">—</span>'}${deltaTxt}</div>
        ${cout}
      </div>
    </div>
    ${gl.etats.opportunite === (gl.postes || []).length && (gl.postes || []).length > 0 ? `<div class="ca-tentant">déclarée, jamais travaillée</div>` : ""}
    ${contexte ? `<div class="al-contexte">${escapeAttr(contexte)}</div>` : ""}
    ${afTxt}
    <div class="ca-actions"><button class="primary small al-ouvrir" data-ligne="${escapeAttr(l.id)}">Voir l'atelier →</button></div>
  </div>`;
}

/* ═══ v4.65.2 — C5′ bloc 3 : la MATRICE des opérations et le PIED ═══════════════
   (spec C5 §1.5 + §1.6). L'écran que la hiérarchie regarde : une seule table,
   toutes les lignes, tous les statuts — un flatMap sur les postes déclarés,
   chaque chiffre sourcé gainPoste(). §3.5 : un poste non impacté reste affiché
   avec ±0,000 € ; §3.4 : le gain de l'OP, jamais un cumul de projetés ; les
   statuts sont des mots ; tri stable par ligne puis par OP. */
function accueilMatriceHTML(gls){
  const MOTS = { gagne: "gagné", encours: "essais en cours", aChiffrer: "à chiffrer", opportunite: "jamais travaillé" };
  const vivantes = gls.filter(gl => !ligneHorsPerimetre(gl));
  const lignes_rows = vivantes.flatMap(gl =>
    gl.postes.map(t => {
      const p = t.poste;
      /* le gain unitaire SOURCÉ du poste : coutProd − coutEnCours (les deux
         rendus par gainPoste, €/pce). Nul ou non chiffré : ±0,000 € ÉCRIT,
         le poste ne disparaît pas (§3.5). */
      let delta = null;
      if(p.coutProd > 0 && p.coutEnCours !== undefined && p.coutEnCours < p.coutProd) delta = p.coutProd - p.coutEnCours;
      /* le gain annuel : acté OU projeté, ÉTIQUETÉ — jamais sommés (§3.4) */
      let annuel = "";
      if(p.gainActe > 0) annuel = `+${fmtEuroCourt(Math.round(p.gainActe))} /an <span class="mx-etq">acté</span>`;
      else if(p.gainProjete > 0) annuel = `+${fmtEuroCourt(Math.round(p.gainProjete))} /an <span class="mx-etq">projeté</span>`;
      else annuel = `<span class="mx-zero">±0,000 €</span>`;
      const ref = p.refDominante ? p.refDominante.nom : "—";
      const nomMachine = t.poste.nom ? ` · ${t.poste.nom}` : "";
      return `<tr class="mx-${t.etat}">
        <td class="mx-ligne">${escapeAttr(gl.ligne.nom)}</td>
        <td class="mx-op">${escapeAttr(p.opCode)}${nomMachine ? `<span class="mx-nom">${escapeAttr(t.poste.nom)}</span>` : ""}</td>
        <td class="mx-ref">${escapeAttr(ref)}</td>
        <td class="num">${delta !== null ? fmt(delta, 4) + " €/pce" : `<span class="mx-zero">±0,000 €/pce</span>`}</td>
        <td class="num">${annuel}</td>
        <td class="mx-statut">${MOTS[t.etat] || t.etat}</td>
        <td class="mx-porte">${t.etat !== "opportunite" ? `<button class="ghost small mx-ouvrir" data-ligne="${escapeAttr(gl.ligne.id)}" data-code="${escapeAttr(p.opCode)}">Ouvrir →</button>` : `<span class="mx-zero">—</span>`}</td>
      </tr>`;
    }));
  if(!lignes_rows.length) return "";
  return `<h4 class="mx-titre">Toutes les opérations — la table que la hiérarchie lit</h4>
    <div class="tbl-wrap"><table class="mt-tbl mx-tbl">
      <thead><tr><th>Ligne</th><th>Opération</th><th>Référence</th><th class="num">Gain unitaire</th><th class="num">Gain annuel</th><th>Statut</th><th></th></tr></thead>
      <tbody>${lignes_rows.join("")}</tbody>
    </table></div>
    <p class="panel-hint" style="margin-top:6px;">Un poste non impacté reste affiché à ±0,000 € (§3.5) ; les gains actés et projetés
      ne se mélangent jamais (§3.4) ; le gain unitaire est l'écart de coût pièce du poste, sourcé.</p>`;
}

/* le pied : les PERSONNES qui portent le suivi (responsables réels, sans rôle
   inventé — le modèle n'en a pas), et les trois actions EXISTANTES exposées :
   on ne crée rien, on montre (spec C5 §1.6). */
/* ═══ v4.78.0 — LA VUE CPP (Tour 49 : « à Z Code de construire, à Hermes de relire ») ═══
   La direction de Benjamin (constitution §1, v1.9) : « opération par opération,
   outil par outil, logement par logement ». La règle 2 quater (v1.10) :
   JAMAIS le total de l'outil comparé au CPP du classeur — le total inclut la
   machine, le classeur l'ignore. Comparaison AXE PAR AXE :
   · OUTILLAGE = prix ÷ (arêtes × DDV) — LA mesure de Matis (colonne I) ;
   · TEMPS = (taux ÷ 3600) × cycle — affiché À CÔTÉ, jamais mêlé, seulement
     quand les données existent ; sinon la base reste l'outillage seul.
   À chaque niveau : le CPP obtenu, la référence Matis (cibleCPP, colonne I
   sommée par référence — 06d831f), la cible, et l'écart EN TOUTES LETTRES.
   CONST AT PUR : lecture seule, rien n'écrit (compatible gel d'audit). */

/* les données de la vue, pures et testables : l'arbre entier en une passe */
function vueCppData(){
  const out = [];
  lignes.forEach(l => {
    if((l.references || []).length === 0) return; /* hors périmètre : pas dans la vue */
    (l.references || []).forEach(ref => {
      /* l'axe OUTILLAGE de chaque OP : le scénario de prod (★ puis excel),
         plaquettes seules — coutsDetail().plaquettes, jamais le total */
      const ops = [];
      let cppObtenu = 0, nonChiffrees = 0, machine = null;
      (ref.ops || []).forEach(op => {
        const excel = (op.scenarios || []).find(x => /base excel/i.test(x.name || ""));
        const star = (op.scenarios || []).find(x => x.baseline);
        const prodSc = star || excel || null;
        if(!prodSc){ nonChiffrees++; return; }
        const det = coutsDetail(prodSc, undefined, l);
        const outillage = det.plaquettes;
        if(outillage === null || outillage === undefined){ nonChiffrees++; return; }
        cppObtenu += outillage;
        /* le meilleur scénario chiffrable, même axe */
        let meilleur = null;
        (op.scenarios || []).forEach(sc => {
          if(prodSc.id === sc.id) return;
          const d2 = coutsDetail(sc, undefined, l);
          if(d2.plaquettes === null || d2.plaquettes === undefined) return;
          if(!meilleur || d2.plaquettes < meilleur.cout) meilleur = { sc, cout: d2.plaquettes };
        });
        ops.push({ op, outillage, meilleur,
          outils: (prodSc.outils || []).map(o => ({
            numero: o.numero, correcteur: o.correcteur || "",
            cout: (o.logements || []).reduce((a, lg) => a + (posCost(lg) || 0), 0),
            logements: (o.logements || []).map(lg => ({
              nom: lg.nom, mabec: lg.mabec || lg.codeArticle || "", ref: lg.ref || "",
              prix: lg.prix, aretes: lg.aretes, ddv: lg.charniere,
              cout: posCost(lg)
            }))
          })) });
        /* l'axe TEMPS : seulement si les données existent, jamais mêlé */
        const cm = det.machine;
        if(cm !== null && cm !== undefined) machine = (machine || 0) + cm;
      });
      const cible = cibleCPPDe(ref);
      out.push({ ligne: l, ref, ops, cppObtenu, nonChiffrees, machine,
                 referenceMatis: cible, cible });
    });
  });
  return out;
}

/* l'écart, dit en atelier — jamais un chiffre nu (§3.5) */
function libelleEcartCpp(obtenu, reference){
  if(reference === null) return { texte: "aucune référence Matis sur cette pièce — colonne I vide dans le classeur", attention: false };
  const e = obtenu - reference;
  if(Math.abs(e) < 0.0005) return { texte: "conforme à la référence Matis", attention: false };
  if(e < 0) return { texte: `${fmt(Math.abs(e), 4)} € SOUS la référence Matis`, attention: false };
  return { texte: `${fmt(e, 4)} € AU-DESSUS de la référence Matis`, attention: true };
}

function vueCppHTML(){
  const data = vueCppData();
  if(!data.length) return `<p class="panel-hint">Aucune ligne vivante : la vue CPP lit l'arbre
    des références déclarées.</p>`;
  const lignesVue = data.map(d => {
    const ecart = libelleEcartCpp(d.cppObtenu, d.referenceMatis);
    const opsTxt = d.ops.map(o => {
      const part = d.cppObtenu > 0 ? (o.outillage / d.cppObtenu) * 100 : 0;
      const meilleurTxt = o.meilleur
        ? `<span class="cpp-meilleur">meilleur essai : ${fmt(o.meilleur.cout, 4)} € <small>(−${fmt(Math.max(0, o.outillage - o.meilleur.cout), 4)} si passé en série)</small></span>` : "";
      const outilsTxt = (o.outils || []).map(u => {
        const logs = (u.logements || []).map(lg =>
          `<span class="cpp-log">${escapeAttr(lg.nom || "logement")} · ${lg.mabec ? escapeAttr(lg.mabec) : "MABEC à saisir"} · ${lg.cout !== null && lg.cout !== undefined ? fmt(lg.cout, 4) + " €" : "— DDV à saisir"}</span>`).join("");
        return `<div class="cpp-outil"><b>${escapeAttr(u.numero || "outil")}</b>${u.correcteur ? ` <span class="cpp-corr">${escapeAttr(u.correcteur)}</span>` : ""}
          <span class="cpp-outil-cout">${u.cout ? fmt(u.cout, 4) + " €" : "—"}</span>
          <div class="cpp-logs">${logs}</div></div>`;
      }).join("");
      return `<details class="cpp-op"><summary>
        <span class="cpp-op-nom">${escapeAttr(o.op.nom)}</span>
        <span class="cpp-op-cout">${fmt(o.outillage, 4)} €</span>
        <span class="cpp-op-part">${fmt(part, 0)} % de la pièce</span>
        ${meilleurTxt}
      </summary><div class="cpp-op-corps">${outilsTxt}</div></details>`;
    }).join("");
    return `<details class="cpp-ref" open><summary>
      <span class="cpp-ref-nom">${escapeAttr(d.ligne.nom)} · ${escapeAttr(d.ref.nom)}</span>
      <span class="cpp-ref-cout">${fmt(d.cppObtenu, 4)} €</span>
      <span class="cpp-ref-ref">${d.referenceMatis !== null ? "réf. Matis " + fmt(d.referenceMatis, 4) + " €" : "réf. Matis : —"}</span>
      <span class="cpp-ecart${ecart.attention ? " cpp-ecart-att" : ""}">${escapeAttr(ecart.texte)}</span>
    </summary>
    <div class="cpp-ref-corps">
      ${d.machine !== null ? `<div class="cpp-machine">⏱ temps valorisé (taux ${escapeAttr(d.ligne.nom)}) : ${fmt(d.machine, 4)} €/pièce — <i>non comparable au classeur, il l'ignore</i></div>` : ""}
      ${opsTxt}
      ${d.nonChiffrees ? `<div class="cpp-nonchiffree">⚠ ${d.nonChiffrees} OP non chiffrable${d.nonChiffrees > 1 ? "s" : ""} — hors du CPP affiché, l'écart doit se voir (§3.2)</div>` : ""}
      ${d.referenceMatis === null ? `<div class="cpp-nonchiffree">référence Matis absente : colonne I vide dans le classeur pour cette pièce (question posée à Matis)</div>` : ""}
    </div></details>`;
  }).join("");
  return `<p class="mt-raz"><b>Ce que cette vue mesure.</b> Le CPP outillage de chaque pièce —
    la même mesure que le classeur de Matis (prix ÷ arêtes ÷ DDV) — décomposé opération par
    opération, outil par outil, logement par logement. La référence Matis en face, l'écart en
    toutes lettres. Le temps machine, quand il est chiffré, s'affiche à part : le classeur
    l'ignore, on ne le compare jamais (constitution 2 quater).</p>
    ${lignesVue}
    <p class="panel-hint" style="margin-top:10px;">Lecture seule : cette vue n'écrit rien. Dépliez une pièce pour ses OP, une OP pour ses outils.</p>`;
}

/* ═══ v4.83 — LE SIMULATEUR DE BAISSE DE PRIX PLAQUETTES ═══════════════════
   La demande de Benjamin (13/10) : « comparer des références de plaquettes
   similaires à plusieurs productions en envisageant une baisse de prix
   générale et le calcul d'économies annuelles en % global, par rapport aux
   scénarios en production ». C'est l'argument fournisseur : que vaut -10 %
   sur une plaquette qui équipe TOUTE l'usine ?

   Règles constitutionnelles : axe OUTILLAGE seul (2 quater — le temps machine
   n'entre pas) ; seuls les scénarios EN PRODUCTION (baseline) comptent ; une
   référence sans volume annuel est exclue du calcul mais NOMMÉE (§3.5) ;
   SIMULATION affiché en toutes lettres — rien n'écrit dans les données. */
function plaquettesCommunes(){
  const groupes = {};
  const parRef = {};   /* v4.83.1 — cle = l'ID de la ref : « 268x12 » existe sur PCI 4 ET PCI 5, le nom ne suffit pas */
  let totalAnnuel = 0, refsSansVolume = 0;
  const sansVolume = new Set();
  lignes.forEach(l => (l.references || []).forEach(r => {
    const prod = parseFloat(r.productionAnnuelle);
    const aVolume = !isNaN(prod) && prod > 0;
    if(!aVolume){ refsSansVolume++; sansVolume.add((l.nom || "?") + " · " + (r.nom || "?")); }
    const PR = parRef[r.id] = parRef[r.id] || { ligne: l.nom, ref: r.nom, prod: aVolume ? prod : 0, coutAnnuel: 0 };
    (r.ops || []).forEach(o => (o.scenarios || []).forEach(sc => {
      if(!sc.baseline) return;
      (sc.outils || []).forEach(ou => (ou.logements || []).forEach(g => {
        const mabec = String(g.codeArticle || g.mabec || "").trim().toUpperCase();
        const prix = parseFloat(g.prix), aretes = parseFloat(g.aretes), ddv = parseFloat(g.charniere);
        if(!mabec || isNaN(prix) || prix <= 0 || !isFinite(aretes) || aretes <= 0 || !isFinite(ddv) || ddv <= 0) return;
        const coutPiece = prix / (aretes * ddv);
        const coutAnnuel = aVolume ? coutPiece * prod : 0;
        totalAnnuel += coutAnnuel;
        PR.coutAnnuel += coutAnnuel;
        const G = groupes[mabec] = groupes[mabec] || { mabec, usages: [], isos: new Set(), coutAnnuel: 0 };
        const iso = String(g.ref || "").trim();
        if(iso) G.isos.add(iso);
        G.usages.push({ ligne: l.nom, ref: r.nom, op: o.opCode || o.nom || "?", outil: ou.numero || "?",
                        iso, prix, aretes, ddv, coutPiece, coutAnnuel, aVolume });
        G.coutAnnuel += coutAnnuel;
      }));
    }));
  }));
  return { groupes: Object.values(groupes).sort((a, b) => b.coutAnnuel - a.coutAnnuel),
           parReference: Object.values(parRef).filter(x => x.coutAnnuel > 0).sort((a, b) => b.coutAnnuel - a.coutAnnuel),
           totalAnnuel, refsSansVolume, sansVolume: Array.from(sansVolume) };
}

/* v4.83/4.84 — l'export : CSV-FR (BOM + sep=; + decimales a virgule) — Excel
   francais l'ouvre sans avertissement, et la regle maison tient : zero SDK.
   PURE : la donnee, le taux et les articles inclus passent en argument —
   testable hors DOM. La chaine commence par le BOM ; la ligne sep=; force le
   separateur quelle que soit la configuration d'Excel. */
function simulCSV(d, tauxPct, inclus){
  const num = v => String(Math.round(v * 10000) / 10000).replace(".", ",");
  const cell = v => /[";\r\n]/.test(String(v)) ? '"' + String(v).replace(/"/g, '""') + '"' : String(v);
  const plagePrix = g => {
    const mn = Math.min(...g.usages.map(u => u.prix)), mx = Math.max(...g.usages.map(u => u.prix));
    return mn === mx ? num(mn) : num(mn) + " a " + num(mx);
  };
  const L = [];
  L.push("sep=;");
  L.push("Simulation prix plaquettes - " + new Date().toLocaleDateString("fr-FR"));
  L.push("Taux de baisse applique;" + String(tauxPct).replace(".", ",") + " %");
  L.push("");
  L.push("Article (MABEC);Libelles ISO;Usages;Lignes;Prix constates (EUR);Cout annuel (EUR);Economie annuelle (EUR)");
  let inclu = 0;
  d.groupes.forEach(g => {
    const actif = !inclus.size || inclus.has(g.mabec);
    const ec = actif ? g.coutAnnuel * tauxPct / 100 : 0;
    inclu += ec;
    L.push([g.mabec, [...g.isos].join(" | "), g.usages.length,
            [...new Set(g.usages.map(u => u.ligne))].join(" | "),
            plagePrix(g), num(g.coutAnnuel), num(ec)].map(cell).join(";"));
  });
  L.push(["TOTAL", "", "", "", "", num(d.totalAnnuel), num(inclu)].map(cell).join(";"));
  L.push("");
  L.push("Budget outillage annuel par reference");
  L.push("Ligne;Reference;Volume annuel;Cout annuel (EUR);% du budget");
  d.parReference.forEach(x => L.push([x.ligne, x.ref, num(x.prod), num(x.coutAnnuel),
    num(d.totalAnnuel ? x.coutAnnuel / d.totalAnnuel * 100 : 0)].map(cell).join(";")));
  return "\uFEFF" + L.join("\r\n");
}

function simulExporter(){
  const d = plaquettesCommunes();
  const taux = parseFloat(document.getElementById("simulTaux")?.value) || 0;
  const inclus = new Set(Array.from(document.querySelectorAll(".simul-inc"))
    .filter(cb => cb.checked).map(cb => cb.getAttribute("data-mabec")));
  const csv = simulCSV(d, taux, inclus);
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  const t = new Date();
  const stamp = t.getFullYear() + String(t.getMonth() + 1).padStart(2, "0") + String(t.getDate()).padStart(2, "0")
              + "-" + String(t.getHours()).padStart(2, "0") + String(t.getMinutes()).padStart(2, "0");
  a.href = url;
  a.download = "Simulation_prix_plaquettes_" + stamp + ".csv";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

/* v4.84 — plein ecran : le panneau passe par-dessus tout (CSS maxi), et le
   mode natif est tente par-dessus (reunion projetee). ESC rend la main. */
/* v4.87 — bascule plein écran GÉNÉRIQUE : tout grand panneau passe maxi (CSS)
   et le mode natif est tenté par-dessus (projection). Échap rend la main. */
function basculerMaxi(idPanel, btn){
  const p = document.getElementById(idPanel);
  if(!p) return;
  const on = !p.classList.contains("simul-maxi");
  p.classList.toggle("simul-maxi", on);
  try{
    if(on && p.requestFullscreen) p.requestFullscreen().catch(() => {});
    else if(!on && document.fullscreenElement && document.exitFullscreen) document.exitFullscreen().catch(() => {});
  }catch(e){}
  if(btn) btn.textContent = on ? "⤢ Quitter le plein écran" : "⛶ Plein écran";
}

function simulMaxi(){
  basculerMaxi("simulPanel", document.getElementById("simulMaxiBtn"));
}

function simulMaxi_legacy(){
  const p = document.getElementById("simulPanel");
  if(!p) return;
  const on = !p.classList.contains("simul-maxi");
  p.classList.toggle("simul-maxi", on);
  try{
    if(on && p.requestFullscreen) p.requestFullscreen().catch(() => {});
    else if(!on && document.fullscreenElement && document.exitFullscreen) document.exitFullscreen().catch(() => {});
  }catch(e){}
  const b = document.getElementById("simulMaxiBtn");
  if(b) b.textContent = on ? "\u2922 Quitter le plein ecran" : "\u26f6 Plein ecran";
}

function simulHTML(){
  const d = plaquettesCommunes();
  if(!d.groupes.length) return `<p class="panel-hint">Aucun logement de production avec prix, arêtes et durée de vie chiffrés. Le simulateur se nourrit des scénarios en production (★) des références à volume annuel.</p>`;
  return `
    <div class="simul-actions">
      <button class="ghost small" id="simulExporterBtn" title="Télécharge les deux tableaux en CSV — s'ouvre dans Excel">⤵ Exporter Excel (CSV)</button>
      <button class="ghost small" id="simulMaxiBtn" title="Projection en réunion">⛶ Plein écran</button>
    </div>
    <div class="simul-note">SIMULATION — rien n'écrit dans le suivi. Source : les scénarios en production (★), axe outillage seul, prix ÷ (arêtes × durée de vie) × volume annuel.</div>
    <div class="simul-controles">
      <label>Baisse de prix générale <input type="number" id="simulTaux" min="0" max="90" step="0.5" value="10"> %</label>
      <span>sur les articles cochés</span>
    </div>
    <table class="simul-table">
      <thead><tr><th></th><th>Article (MABEC)</th><th>Usages</th><th>Prix constatés</th><th>Coût / an</th><th>Économie / an</th></tr></thead>
      <tbody>
      ${d.groupes.map(g => {
        const prixMin = Math.min(...g.usages.map(u => u.prix)), prixMax = Math.max(...g.usages.map(u => u.prix));
        const ec = g.coutAnnuel * (parseFloat(document.getElementById("simulTaux")?.value) || 0) / 100;
        return `<tr>
          <td><input type="checkbox" class="simul-inc" data-mabec="${escapeAttr(g.mabec)}" checked></td>
          <td class="mono">${escapeAttr(g.mabec)}${g.isos.size ? `<br><span style="font-size:11.5px; color:#888;">${[...g.isos].map(x => escapeAttr(x)).join("<br>")}</span>` : ""}</td>
          <td>${g.usages.length} · ${escapeAttr([...new Set(g.usages.map(u => u.ligne))].join(", "))}</td>
          <td class="mono">${fmt(prixMin, 2)}${prixMin !== prixMax ? " – " + fmt(prixMax, 2) : ""} €</td>
          <td class="mono">${fmtEuroCourt(Math.round(g.coutAnnuel))}</td>
          <td class="mono simul-ec" data-cout="${g.coutAnnuel}">—</td>
        </tr>`;
      }).join("")}
      </tbody>
      <tfoot><tr><td colspan="4">Total outillage annuel en production</td><td class="mono">${fmtEuroCourt(Math.round(d.totalAnnuel))}</td><td class="mono" id="simulTotal">—</td></tr></tfoot>
    </table>
    ${d.refsWithoutVolumeNote || ""}
    ${d.parReference.length ? `
    <h4 style="margin:22px 0 8px; font-size:14px;">Budget outillage annuel par référence</h4>
    <table class="simul-table">
      <thead><tr><th>Ligne</th><th>Référence</th><th>Volume annuel</th><th>Coût / an</th><th>% du budget</th></tr></thead>
      <tbody>${d.parReference.map(x => `<tr>
        <td>${escapeAttr(x.ligne)}</td>
        <td>${escapeAttr(x.ref)}</td>
        <td class="mono">${fmt(x.prod, 0)}</td>
        <td class="mono">${fmtEuroCourt(Math.round(x.coutAnnuel))}</td>
        <td class="mono">${d.totalAnnuel ? fmt(x.coutAnnuel / d.totalAnnuel * 100, 1) : "—"} %</td>
      </tr>`).join("")}</tbody>
    </table>` : ""}
    ${d.refsSansVolume ? `<p class="panel-hint">⚠ ${d.refsSansVolume} référence(s) sans volume annuel — hors calcul : ${d.sansVolume.map(x => escapeAttr(x)).join(" · ")}</p>` : ""}
    <div class="simul-resultat" id="simulResultat"></div>`;
}

function simulRecalcul(){
  const taux = (parseFloat(document.getElementById("simulTaux")?.value) || 0) / 100;
  const d = plaquettesCommunes();
  let inclu = 0;
  const cbs = Array.from(document.querySelectorAll(".simul-inc"));
  const tds = Array.from(document.querySelectorAll(".simul-ec"));
  d.groupes.forEach((g, i) => {
    const actif = cbs[i] && cbs[i].checked;
    const ec = actif ? g.coutAnnuel * taux : 0;
    inclu += ec;
    if(tds[i]) tds[i].textContent = ec ? "− " + fmtEuroCourt(Math.round(ec)) : "—";
  });
  const total = document.getElementById("simulTotal");
  if(total) total.textContent = inclu ? "− " + fmtEuroCourt(Math.round(inclu)) : "—";
  const res = document.getElementById("simulResultat");
  if(res){
    const pct = d.totalAnnuel ? (inclu / d.totalAnnuel) * 100 : 0;
    res.innerHTML = inclu
      ? `Économie annuelle simulée : <b>${fmtEuroCourt(Math.round(inclu))} / an</b> — <b>${fmt(pct, 1)} %</b> du budget outillage en production (${fmtEuroCourt(Math.round(d.totalAnnuel))}).`
      : `Cochez des articles et choisissez un taux : l'économie se calcule sur le budget outillage des scénarios en production.`;
  }
}

/* ═══ v4.85 — LE CATALOGUE PLAQUETTES : socle, seed, propagation, CSV ═══════
   La vérité prix/article : une ligne = UN MABEC = UN prix (décision Benjamin —
   Matis vérifie le fichier ; 209 560 = 38 €). Le fichier d'échange est un CSV
   standalone édité dans Excel. La propagation aux logements se fait AVEC
   rapport et consentement — jamais en silence (§3.2). */

function catalogueSeed(){
  /* regroupe TOUS les logements de l'outil par MABEC : le prix retenu est le
     plus FRÉQUENT (à égalité, le plus élevé — décision Benjamin pour 209 560),
     et chaque divergence est signalée, pas aplatie. Les ISO vus se cumulent. */
  const parMabec = {};
  lignes.forEach(l => (l.references || []).forEach(r => (r.ops || []).forEach(o =>
    (o.scenarios || []).forEach(sc => (sc.outils || []).forEach(ou => (ou.logements || []).forEach(g => {
      const mabec = String(g.codeArticle || g.mabec || "").trim().toUpperCase();
      const prix = parseFloat(g.prix);
      if(!mabec || isNaN(prix) || prix <= 0) return;
      const e = parMabec[mabec] = parMabec[mabec] || { mabec, iso: new Set(), prixVus: {} };
      if(String(g.ref || "").trim()) e.iso.add(String(g.ref).trim());
      e.prixVus[prix] = (e.prixVus[prix] || 0) + 1;
    }))))));
  return Object.values(parMabec).map(e => {
    const entrees = Object.entries(e.prixVus);
    entrees.sort((a, b) => (b[1] - a[1]) || (b[0] - a[0]));
    const prix = Number(entrees[0][0]);
    const divergent = entrees.length > 1;
    return normalizeArticleCat({ mabec: e.mabec, iso: [...e.iso].join(" | "),
      prix, aretes: "", ddv: "", divergent,
      prixVus: entrees.map(e2 => Number(e2[0])) });
  }).sort((a, b) => a.mabec.localeCompare(b.mabec));
}

function catalogueAppliquer(cat){
  /* propage les prix du catalogue dans TOUS les logements correspondants.
     Rend le rapport : MABEC changés, logements touchés, avant/après. */
  const parMabec = {};
  (cat || catalogue).forEach(a => { if(a.prix !== "" && a.prix > 0) parMabec[a.mabec] = a.prix; });
  const rapport = { logementsTouches: 0, mabecs: [] };
  lignes.forEach(l => (l.references || []).forEach(r => (r.ops || []).forEach(o =>
    (o.scenarios || []).forEach(sc => (sc.outils || []).forEach(ou => (ou.logements || []).forEach(g => {
      const mabec = String(g.codeArticle || g.mabec || "").trim().toUpperCase();
      const nouveau = parMabec[mabec];
      if(nouveau === undefined) return;
      const avant = parseFloat(g.prix);
      if(!isNaN(avant) && Math.abs(avant - nouveau) < 1e-9) return;
      g.prix = nouveau;
      rapport.logementsTouches++;
      const deja = rapport.mabecs.find(x => x.mabec === mabec);
      if(deja) deja.n++;
      else rapport.mabecs.push({ mabec, avant, apres: nouveau, n: 1 });
    }))))));
  return rapport;
}

function catalogueCSV(cat){
  const num = v => String(v === "" || v == null ? "" : v).replace(".", ",");
  const cell = v => /[";\r\n]/.test(String(v)) ? '"' + String(v).replace(/"/g, '""') + '"' : String(v);
  const L = ["sep=;", "Catalogue plaquettes - " + new Date().toLocaleDateString("fr-FR"), "",
    "MABEC;Libelle ISO;Prix EUR;Aretes;DDV (pieces)"];
  (cat || catalogue).forEach(a => L.push([a.mabec, a.iso, num(a.prix), num(a.aretes), num(a.ddv)].map(cell).join(";")));
  return "\uFEFF" + L.join("\r\n");
}

function catalogueDepuisCSV(texte){
  /* tolérant : BOM, ligne sep=; optionnelle, ; ou , en séparateur, décimales
     point ou virgule, en-têtes reconnus par mot-clé. Rend { cat, erreurs }. */
  const brut = String(texte || "").replace(/^\uFEFF/, "").replace(/^sep=;\r?\n/i, "").replace(/^sep=,\r?\n/i, "");
  const lignesTxt = brut.split(/\r?\n/).filter(x => x.trim());
  if(!lignesTxt.length) return { cat: [], erreurs: ["Fichier vide."] };
  /* v4.85.1 — le CSV exporté porte un titre et une ligne sep=; : la ligne
     d'en-têtes se CHERCHE (celle qui contient MABEC), elle n'est pas supposée
     première. Sans ça, l'export de l'outil ne se ré-importait pas lui-même. */
  const iEntete = lignesTxt.findIndex(x => /mabec/i.test(x));
  if(iEntete === -1) return { cat: [], erreurs: ["Ligne d'en-têtes introuvable (il faut une colonne MABEC)."] };
  const sep = (lignesTxt[iEntete].split(";").length >= lignesTxt[iEntete].split(",").length) ? ";" : ",";
  const entetes = lignesTxt[iEntete].split(sep).map(x => x.trim().toLowerCase());
  const col = cles => entetes.findIndex(h => cles.some(k => h.includes(k)));
  const iM = col(["mabec", "article"]), iI = col(["iso", "libell"]), iP = col(["prix"]),
        iA = col(["arête", "arete"]), iD = col(["ddv", "charniè", "durée", "duree"]);
  if(iM === -1 || iP === -1) return { cat: [], erreurs: ["Colonnes MABEC et Prix introuvables. En-têtes attendus : MABEC ; Libelle ISO ; Prix EUR ; Aretes ; DDV (pieces)."] };
  const cat = [], erreurs = [];
  /* v4.85.1 — le d\u00e9coupeur respecte les guillemets : une virgule d\u00e9cimale
     dans un champ quot\u00e9 (\u00ab "7,96" \u00bb, la mani\u00e8re d'Excel FR) n'est pas un
     s\u00e9parateur. Un split na\u00effe coupait le prix en deux. */
  const couper = (ligne) => {
    const out = []; let cur = "", enQuote = false;
    for(const ch of ligne){
      if(ch === '"'){ enQuote = !enQuote; continue; }
      if(ch === sep && !enQuote){ out.push(cur.trim()); cur = ""; continue; }
      cur += ch;
    }
    out.push(cur.trim());
    return out.map(x => x.replace(/""/g, '"'));
  };
  lignesTxt.slice(iEntete + 1).forEach((ligne, idx) => {
    const c = couper(ligne);
    const mabec = (c[iM] || "").toUpperCase().replace(/\s+/g, " ").trim();
    const prix = parseFloat(String(c[iP] || "").replace(",", "."));
    if(!mabec) return;
    if(isNaN(prix) || prix <= 0){ erreurs.push("Ligne " + (idx + 2) + " : prix illisible (" + (c[iP] || "vide") + ")"); return; }
    const n = v => { const f = parseFloat(String(v || "").replace(",", ".")); return isNaN(f) ? "" : f; };
    cat.push(normalizeArticleCat({ mabec, iso: iI > -1 ? (c[iI] || "") : "", prix,
      aretes: iA > -1 ? n(c[iA]) : "", ddv: iD > -1 ? n(c[iD]) : "" }));
  });
  if(!cat.length && !erreurs.length) erreurs.push("Aucune ligne exploitable.");
  return { cat, erreurs };
}

/* v4.89 — LES SUGGESTIONS À LA SAISIE : l'autocomplete du catalogue.
   Taper un MABEC ou un ISO dans un logement propose les articles connus
   (datalist natif — zéro framework) et remplit d'un changement : le MABEC,
   le prix (toujours — un MABEC = un prix), l'ISO, les arêtes et la durée de
   vie SI VIDES. Ce qui est saisi à la main n'est jamais écrasé. */
function catalogueSuggestion(mabec){
  const n = String(mabec || "").trim().toUpperCase().replace(/\s+/g, " ");
  if(!n) return null;
  return catalogue.find(a => a.mabec === n) || null;
}

function catalogueParIso(iso){
  const n = String(iso || "").trim().toUpperCase().replace(/\s+/g, " ");
  if(!n) return null;
  return catalogue.find(a => String(a.iso || "").toUpperCase().replace(/\s+/g, " ").split(" | ").some(x => x === n)) || null;
}

function appliquerSuggestionCatalogue(l, entry){
  if(!l || !entry) return [];
  const mods = [];
  const vide = v => v === "" || v == null;
  const isoUnique = (entry.iso && entry.iso.indexOf(" | ") === -1) ? entry.iso : "";
  const poser = (champ, valeur, toujours) => {
    if(valeur === "" || valeur == null) return;
    if(!toujours && vide(l[champ]) === false) return;
    if(String(l[champ]) === String(valeur)) return;
    l[champ] = valeur;
    mods.push(champ);
  };
  poser("codeArticle", entry.mabec, true);
  poser("prix", entry.prix, true);
  poser("ref", isoUnique, false);
  poser("aretes", entry.aretes, false);
  poser("charniere", entry.ddv, false);
  return mods;
}

function renderCatalogueDatlists(){
  const mabec = document.getElementById("catMabec");
  const iso = document.getElementById("catIso");
  if(!mabec || !iso) return;
  mabec.innerHTML = catalogue.map(a => `<option value="${escapeAttr(a.mabec)}">${escapeAttr(a.iso || "")}</option>`).join("");
  const isos = new Set();
  catalogue.forEach(a => String(a.iso || "").split(" | ").forEach(x => { if(x.trim()) isos.add(x.trim()); }));
  iso.innerHTML = [...isos].map(x => `<option value="${escapeAttr(x)}">`).join("");
}

function catalogueRendu(){
  if(!catalogue.length) return `<p class="panel-hint">Le catalogue est vide. Trois façons de le remplir : le <b>générer depuis l'outil</b> (un MABEC = un prix, le plus fréquent, divergences signalées), l'<b>importer d'un CSV</b> édité dans Excel, ou les deux — générer, exporter, faire corriger par Matis, réimporter.</p>
    <div class="simul-actions">
      <button class="ghost small" id="catSeed">🌱 Générer depuis l'outil</button>
      <label class="ghost small" for="catFichier" style="cursor:pointer;">⤴ Importer un CSV…</label>
      <input type="file" id="catFichier" accept=".csv,.txt" hidden>
    </div>`;
  return `
    <div class="simul-actions">
      <button class="primary small" id="catAppliquer" title="Propage les prix du catalogue dans tous les logements correspondants — avec rapport">✅ Appliquer les prix aux logements</button>
      <button class="ghost small" id="catExporter">⤵ Exporter le CSV</button>
      <label class="ghost small" for="catFichier" style="cursor:pointer;">⤴ Importer un CSV…</label>
      <input type="file" id="catFichier" accept=".csv,.txt" hidden>
      <button class="ghost small" id="catSeed">🌱 Regénérer depuis l'outil</button>
    </div>
    <p class="panel-hint">${catalogue.length} article(s). Un MABEC = un prix — la propagation remplace les prix des logements correspondants, avec rapport. <b>SIMULATION jusqu'à « Appliquer ».</b></p>
    <table class="simul-table">
      <thead><tr><th>Article (MABEC)</th><th>Libellés ISO vus</th><th>Prix</th></tr></thead>
      <tbody>${catalogue.map(a => `<tr>
        <td class="mono">${escapeAttr(a.mabec)}</td>
        <td style="font-size:12px; color:#888;">${escapeAttr(a.iso || "—")}</td>
        <td class="mono">${a.prix !== "" ? fmt(a.prix, 2) + " €" : "—"}${a.divergent ? ' <span style="color:#b45309;">(prix divergents dans l\'outil — Matis vérifie)</span>' : ""}</td>
      </tr>`).join("")}</tbody>
    </table>`;
}

function renderCatalogue(){ renderCatalogueDatlists();
  const wrap = document.getElementById("cataloguePanel");
  if(!wrap) return;
  wrap.innerHTML = `<h3>📚 Catalogue plaquettes — la vérité prix/article</h3>` + catalogueRendu();
  const seed = document.getElementById("catSeed");
  if(seed) seed.addEventListener("click", () => {
    backupSnapshot("Catalogue : génération depuis l'outil");
    catalogue = catalogueSeed();
    saveData(); renderCatalogue();
  });
  const fich = document.getElementById("catFichier");
  if(fich) fich.addEventListener("change", () => {
    const f = fich.files[0];
    if(!f) return;
    const reader = new FileReader();
    reader.onload = () => {
      const { cat, erreurs } = catalogueDepuisCSV(reader.result);
      if(erreurs.length){ dialogueAlerte(erreurs.join("<br>"), "Import catalogue"); return; }
      backupSnapshot("Catalogue : import CSV");
      const parMabec = {};
      catalogue.forEach(a => { parMabec[a.mabec] = a; });
      cat.forEach(a => { parMabec[a.mabec] = a; });
      catalogue = Object.values(parMabec).map(normalizeArticleCat);
      saveData(); renderCatalogue();
    };
    reader.readAsText(f, "utf-8");
  });
  const exp = document.getElementById("catExporter");
  if(exp) exp.addEventListener("click", () => {
    const blob = new Blob([catalogueCSV()], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = "Catalogue_plaquettes.csv";
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  });
  const appl = document.getElementById("catAppliquer");
  if(appl) appl.addEventListener("click", () => {
    const avant = JSON.stringify(catalogue);
    const rapport = catalogueAppliquer();
    if(!rapport.logementsTouches){ dialogueAlerte("Tous les logements correspondants portent déjà le prix du catalogue.", "Rien à mettre à jour"); return; }
    backupSnapshot("Catalogue : propagation des prix");
    saveData(); render();
    dialogueAlerte(`<b>${rapport.logementsTouches} logement(s) mis(s) à jour.</b><br>` +
      rapport.mabecs.slice(0, 12).map(x => `${escapeAttr(x.mabec)} : ${escapeAttr(String(x.avant))} → ${escapeAttr(String(x.apres))} € (${x.n})`).join("<br>") +
      (rapport.mabecs.length > 12 ? "<br>…" : ""), "Prix propagés");
  });
}
function ouvrirCatalogue(){
  fermerPanneaux();
  ouvrirPanneau("cataloguePanel");
  renderCatalogue();
}

/* ═══ v4.86 — LE PLAN DE CONVERSION : la vitrine commerciale ════════════════
   La demande de Benjamin : montrer a Matis, article par article, ce que vaut
   le passage sur les plaquettes SPK — progressivement, ligne par ligne, au
   bon moment. Regles : la consommation est celle des scenarios EN PRODUCTION
   (le meme calcul que partout) ; la cible est EDITABLE (auto-suggeree pour
   les KY3500 : meme geometrie en LKT640 a 5 EUR, decision Benjamin) ; l'etat
   de chaque ligne appartient a Benjamin (a proposer / proposee / en essai /
   gagnee) ; le TOTAL de la promesse ne compte que les lignes ou l'etat est
   pose. Les DDV d'essai n'entrent qu'apres validation operateur (decisions
   du 13/10). Aucun K, aucun P dans cet ecran. */
/* ═══ v4.88 — LE BASCULEUR DE CONSOMMATION : theorique vs REELLE ════════════
   Benjamin, en voyant les quantites du Plan : « j'ai de tres gros doutes sur
   tes quantites de plaquettes annuelles » — il a raison : elles sont
   THEORIQUES (production / (aretes x DDV classeur)), et l'historique de ses
   propres classeurs dit un reel ~7,5 fois plus gros. Le basculeur permet de
   calculer les gains sur la consommation REELLE : les feuilles « Pareto
   conso » des classeurs donnent une semaine de consommation reelle par
   article, extrapolee x 52 — avec l'avertissement affiche (regime suppose
   constant). Lecture LOCALE uniquement (constitution 4.2) ; etat de session,
   comme la lecture Classeur Matis : jamais ecrit dans le suivi. */
let consoReelle = null;   /* { lueLe, fichiers: [], parArticle: { ART: { qtySemaine, lignes: [] } } } */
let planSource = "theo";  /* "theo" | "reel" */

function consoDepuisFeuille(nomFeuille, cells){
  /* parse une feuille « Pareto conso » : sections EMAG n / PCI n / HESSAPP,
     articles en dessous, quantites en colonne B. Rend { article: { qtySemaine,
     lignes:Set } } ou null si la feuille n'est pas une conso quantifiee. */
  if(!/pareto/i.test(nomFeuille || "") || !/conso/i.test(nomFeuille || "")) return null;
  const lignesNum = [...new Set(Object.keys(cells).map(r => parseInt(r.replace(/\D/g, ""), 10)))].sort((a, b) => a - b);
  let enteteQte = false;
  for(const rn of lignesNum.slice(0, 4)){
    const hA = cells["A" + rn], hB = cells["B" + rn];
    if((typeof hA === "string" && /somme de qt/i.test(hA)) ||
       (typeof hB === "string" && /somme de qt/i.test(hB))) enteteQte = true;
  }
  if(!enteteQte) return null;   /* un pareto de COUT ne doit jamais passer pour des quantites */
  let section = null;
  const out = {};
  for(const rn of lignesNum){
    const a = cells["A" + rn], b = cells["B" + rn];
    if(typeof a !== "string") continue;
    const label = a.trim();
    if(/^total g/i.test(label)){ section = null; continue; }
    if(/(somme de qt|etiquettes de lignes|\u00e9tiquettes de lignes)/i.test(label)) continue;
    const m = label.match(/^(EMAG\s*\d|PCI\s*\d|HESSAP\w*)$/i);
    if(m && typeof b === "number"){ section = m[1].toUpperCase().replace(/\s+/g, " "); continue; }
    if(section && typeof b === "number" && b > 0){
      const art = label.toUpperCase().replace(/\s+/g, " ");
      out[art] = out[art] || { qtySemaine: 0, lignes: new Set() };
      out[art].qtySemaine += b;
      out[art].lignes.add(section);
    }
  }
  return Object.keys(out).length ? out : null;
}

/* lit UN classeur : toutes les feuilles, fusionne les sections Pareto conso */
async function consoLireClasseur(file){
  const entries = await _zipOpen(file);
  const shared = await _xlSharedStrings(entries);
  const map = await _xlSheetMap(entries);
  const parArticle = {};
  const feuillesLues = [];
  for(const nom of Object.keys(map)){
    if(!entries[map[nom]]) continue;
    const xml = new TextDecoder("utf-8").decode(await _zipRead(entries[map[nom]]));
    const lu = consoDepuisFeuille(nom, _xlCells(xml, shared));
    if(!lu) continue;
    feuillesLues.push(nom);
    for(const [art, v] of Object.entries(lu)){
      const e = parArticle[art] = parArticle[art] || { qtySemaine: 0, lignes: new Set() };
      e.qtySemaine += v.qtySemaine;
      v.lignes.forEach(x => e.lignes.add(x));
    }
  }
  return { fichier: file.name, feuilles: feuillesLues, parArticle };
}

const PLAN_ETATS = ["à proposer", "proposée", "en essai", "gagnée"];

function planLignes(){
  const d = plaquettesCommunes();
  const parMabec = {};
  plan.forEach(p => { parMabec[p.mabec] = p; });
  const reel = (planSource === "reel") && consoReelle && consoReelle.parArticle;
  return d.groupes.map(g => {
    const art = catalogue.find(a => a.mabec === g.mabec && a.prix !== "" && a.prix > 0);
    const prixA = art ? art.prix : (g.usages[0] ? g.usages[0].prix : 0);
    const piecesAnTheo = prixA > 0 ? g.coutAnnuel / prixA : 0;
    /* v4.88 — le basculeur : en mode REEL, la consommation vient des feuilles
       Pareto conso des classeurs (qty semaine x 52). Un article sans donnee
       reelle n'est pas complete en silence : il perd son gain (null). */
    const conso = reel ? consoReelle.parArticle[g.mabec] : null;
    const sourceConso = reel ? (conso ? "reelle" : "sans") : "theo";
    const piecesAn = reel ? (conso ? conso.qtySemaine * 52 : 0) : piecesAnTheo;
    const isoKY = g.usages.map(u => u.iso).find(i => /KY3500/i.test(i || ""));
    const sugg = isoKY ? { iso: String(isoKY).replace(/KY3500/gi, "LKT640"), prix: 5 } : null;
    const p = parMabec[g.mabec] || {};
    const ciblePrix = (p.prixCible !== "" && p.prixCible != null) ? Number(p.prixCible)
                      : (sugg ? sugg.prix : "");
    const cibleIso = p.isoCible || (sugg ? sugg.iso : "");
    const actif = !!p.etat;
    const gain = (actif && ciblePrix !== "" && ciblePrix !== null && prixA > 0 && sourceConso !== "sans")
      ? piecesAn * (prixA - Number(ciblePrix)) : null;
    return { mabec: g.mabec, isos: [...g.isos], prixA, coutAnnuel: g.coutAnnuel,
             piecesAn, piecesAnTheo, sourceConso, cibleIso, ciblePrix, etat: p.etat || "", actif, gain, auto: !!sugg };
  });
}

function planHTML(){
  const lignes = planLignes();
  if(!lignes.length) return `<p class="panel-hint">Aucun article de production chiffré : le plan se nourrit des mêmes données que le simulateur (scénarios en production, prix + volume).</p>`;
  const total = lignes.reduce((a, l) => a + (l.actif && l.gain ? l.gain : 0), 0);
  const actives = lignes.filter(l => l.actif).length;
  const modeReel = planSource === "reel";
  const etatConso = !modeReel
    ? "théorique — production ÷ (arêtes × DDV classeur)"
    : (consoReelle
        ? "réelle extrapolée — lue le " + consoReelle.lueLe + " (" + consoReelle.fichiers.join(", ") + ")"
        : "réelle — mais aucun classeur lu : lis un fichier ci-dessous");
  return `
    <div class="simul-note">Le pas-à-pas commercial : chaque ligne est un article actuel, sa consommation en production, et la cible SPK — révélée quand TU décides de poser son état. Le total ne compte que les lignes étatées.</div>
    <div class="simul-controles" style="flex-wrap:wrap;">
      <span style="font-weight:600;">Consommation :</span>
      <label style="cursor:pointer;"><input type="radio" name="consoSource" value="theo" ${!modeReel ? "checked" : ""}> théorique</label>
      <label style="cursor:pointer;"><input type="radio" name="consoSource" value="reel" ${modeReel ? "checked" : ""}> réelle extrapolée</label>
      <label class="ghost small" for="consoFichier" style="cursor:pointer;">📂 Lire un classeur de consommation…</label>
      <input type="file" id="consoFichier" accept=".xlsm,.xlsx" multiple hidden>
      <span id="consoEtat" style="font-size:13px; color:#1b5ea6;">${etatConso}</span>
    </div>
    ${modeReel && consoReelle ? `<p class="panel-hint">⚠ Consommation réelle = une semaine de tes classeurs × 52 (régime supposé constant). Les articles sans consommation lue perdent leur gain — jamais complétés en silence (§3.5).</p>` : ""}
    <table class="simul-table">
      <thead><tr><th>Article actuel</th><th>Libellés ISO</th><th>Prix actuel</th><th>Consommation</th><th>Cible SPK</th><th>Prix cible</th><th>État</th><th>Gain / an</th></tr></thead>
      <tbody>
      ${lignes.map((l, i) => {
        const isoCible = l.cibleIso || l.isos[0] || "";
        return `<tr>
          <td class="mono">${escapeAttr(l.mabec)}</td>
          <td style="font-size:11.5px; color:#888;">${l.isos.map(x => escapeAttr(x)).join("<br>")}</td>
          <td class="mono">${fmt(l.prixA, 2)} €</td>
          <td class="mono">${l.sourceConso === "reelle"
            ? `${fmt(l.piecesAn, 0)} plq/an <span style="color:#1b5ea6;">(réel)</span><br><span style="color:#888;">${fmtEuroCourt(Math.round(l.piecesAn * l.prixA))} estimé/an</span>`
            : (l.sourceConso === "sans"
                ? `<span style="color:#b45309;">pas de conso réelle lue</span>`
                : `${fmtEuroCourt(Math.round(l.coutAnnuel))}/an<br><span style="color:#888;">${fmt(l.piecesAn, 0)} plq/an</span>`)}</td>
          <td><input class="cell" style="width:190px; font-size:12px;" data-plan="${l.mabec}" data-field="isoCible" value="${escapeAttr(l.cibleIso)}" placeholder="plaquette SPK${l.auto ? " (LKT640 suggérée)" : ""}"></td>
          <td><input class="cell" style="width:74px; font-family:var(--font-mono);" type="number" step="0.01" data-plan="${l.mabec}" data-field="prixCible" value="${l.ciblePrix === "" ? "" : l.ciblePrix}" placeholder="5"></td>
          <td><select class="cell small" data-plan="${l.mabec}" data-field="etat">
            <option value="">—</option>
            ${PLAN_ETATS.map(e => `<option value="${e}" ${l.etat === e ? "selected" : ""}>${e}</option>`).join("")}
          </select></td>
          <td class="mono" style="${l.gain ? "color:#1a7a3f; font-weight:600;" : "color:#888;"}">${l.gain != null ? "− " + fmtEuroCourt(Math.round(l.gain)) : "potentiel"}</td>
        </tr>`;
      }).join("")}
      </tbody>
    </table>
    <div class="simul-resultat">${actives
      ? `Promesse posée : <b>${actives} article(s)</b> en conversion — économie simulée <b>− ${fmtEuroCourt(Math.round(total))} / an</b>.`
      : `Pose un état sur une ligne (même « à proposer ») pour l’ajouter à la promesse — le pas-à-pas t’appartient.`}</div>
    <div class="simul-actions" style="margin-top:12px;">
      <button class="ghost small" id="planExporter">⤵ Exporter le plan (CSV)</button>
      <button class="ghost small" id="planMaxiBtn" title="Projection en réunion">⛶ Plein écran</button>
    </div>`;
}

function renderPlan(){
  const wrap = document.getElementById("planPanel");
  if(!wrap) return;
  wrap.innerHTML = `<h3>⚔️ Plan de conversion — vers les plaquettes SPK</h3>` + planHTML();
  wrap.querySelectorAll("[data-plan]").forEach(inp => inp.addEventListener("change", () => {
    const mabec = inp.getAttribute("data-plan"), field = inp.getAttribute("data-field");
    let e = plan.find(x => x.mabec === mabec);
    if(!e){ e = normalizePlanEntry({ mabec }); plan.push(e); }
    e[field] = field === "prixCible" ? (inp.value === "" ? "" : Number(inp.value)) : inp.value;
    saveData(); renderPlan();
  }));
  const ex = document.getElementById("planExporter");
  if(ex) ex.addEventListener("click", planExporter);
  const mx = document.getElementById("planMaxiBtn");
  if(mx) mx.addEventListener("click", () => basculerMaxi("planPanel", mx));
  wrap.querySelectorAll('input[name="consoSource"]').forEach(r => r.addEventListener("change", () => {
    planSource = r.value; renderPlan();
  }));
  const fich = document.getElementById("consoFichier");
  if(fich) fich.addEventListener("change", async () => {
    const fichiers = Array.from(fich.files || []);
    if(!fichiers.length) return;
    const parArticle = {}; const noms = [];
    for(const f of fichiers){
      try{
        const lu = await consoLireClasseur(f);
        noms.push(lu.fichier);
        for(const [art, v] of Object.entries(lu.parArticle)){
          const e = parArticle[art] = parArticle[art] || { qtySemaine: 0, lignes: new Set() };
          e.qtySemaine += v.qtySemaine;
          v.lignes.forEach(x => e.lignes.add(x));
        }
      }catch(err){ dialogueAlerte("Lecture impossible : " + err.message, "Classeur de consommation"); }
    }
    consoReelle = { lueLe: new Date().toLocaleDateString("fr-FR"), fichiers: noms, parArticle };
    planSource = "reel";
    renderPlan();
  });
}
function ouvrirPlan(){
  fermerPanneaux();
  ouvrirPanneau("planPanel");
  renderPlan();
}

function planCSV(){
  const num = v => String(v === "" || v == null ? "" : Math.round(v * 10000) / 10000).replace(".", ",");
  const cell = v => /[";\r\n]/.test(String(v)) ? '"' + String(v).replace(/"/g, '""') + '"' : String(v);
  const lignes = planLignes();
  const L = ["sep=;", "Plan de conversion SPK - " + new Date().toLocaleDateString("fr-FR"), "",
    "Consommation;" + (planSource === "reel" ? "REELLE extrapolee (classeur x 52)" : "theorique (DDV classeur)"), "",
    "Article actuel (MABEC);Libelles ISO;Prix actuel (EUR);Consommation (EUR/an);Plaquettes/an;Cible SPK;Prix cible (EUR);Etat;Gain (EUR/an)"];
  lignes.forEach(l => L.push([l.mabec, l.isos.join(" | "), num(l.prixA),
    l.sourceConso === "reelle" ? num(l.piecesAn * l.prixA) : num(l.coutAnnuel),
    num(l.piecesAn), l.cibleIso, num(l.ciblePrix), l.etat, l.gain != null ? num(l.gain) : ""].map(cell).join(";")));
  const total = lignes.reduce((a, l) => a + (l.actif && l.gain ? l.gain : 0), 0);
  L.push(["TOTAL (etat pose)", "", "", "", "", "", "", "", num(total)].map(cell).join(";"));
  return "\ufeff" + L.join("\r\n");
}
function planExporter(){
  const blob = new Blob([planCSV()], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = "Plan_conversion_SPK.csv";
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

