/* ---- v4.25 — clôture d'un essai arrêté avant sa charnière (casse, brut, incident) ----
   Le statut d'un essai est CALCULÉ : sans ça, un essai arrêté net (insert cassé sans
   sortie de tolérance mesurée) restait "en cours — X pièces à saisir" pour toujours et
   re-remplissait le bandeau de reprise. La clôture pose une décision de record : le
   statut devient "arrêté", il sort du protocole 5× et de la reprise, et le rapport
   d'essai le documente avec le motif. Réouvrable : la donnée n'est jamais perdue. */
function renderCloturePanel(){
  const wrap = document.getElementById("cloturePanel");
  if(!wrap || wrap.hidden) return;
  const sc = data.find(s => s.id === (clotureCtx && clotureCtx.scId));
  const es = sc && (sc.essais || []).find(e => e.id === (clotureCtx && clotureCtx.essaiId));
  if(!es){ fermerPanneaux(); return; }
  const c = es.cloture || {};
  const options = MOTIFS_ARRET.map(([v, l]) => `<option value="${v}" ${c.motif === v ? "selected" : ""}>${escapeAttr(l)}</option>`).join("");
  wrap.innerHTML = `
    <h3>${c.motif ? "Essai arrêté" : "Clôturer l'essai"} — ${escapeAttr(es.titre || "")}</h3>
    <p class="panel-hint">Un essai arrêté avant sa charnière reste dans le suivi et dans le rapport d'essai (avec le motif), mais il ne compte ni comme conforme ni comme non conforme : il sort du compteur 5× et du bandeau de reprise. Ses prélèvements restent intacts — courbes et historique ne bougent pas. Réouvrable à tout moment.</p>
    <label class="cloture-champ">Motif d'arrêt
      <select id="clotureMotif" class="cell">${options}</select></label>
    <label class="cloture-champ">Précision
      <input id="clotureDetail" class="cell ref" value="${escapeAttr(c.detail || "")}" placeholder="ex. éclat d'arête Inter à la pièce 37"></label>
    <label class="cloture-champ">Date d'arrêt
      <input id="clotureDate" type="date" min="2025-01-01" max="2035-12-31" class="cell" value="${escapeAttr(c.date || new Date().toISOString().slice(0,10))}"></label>
    <div class="panel-actions">
      <button class="ghost" id="clotureAnnuler">Annuler</button>
      ${c.motif ? `<button class="ghost" id="clotureReouvrir">Réouvrir l'essai</button>` : ""}
      <button class="primary" id="clotureGo">${c.motif ? "Mettre à jour" : "Clôturer l'essai"}</button>
    </div>`;
  document.getElementById("clotureAnnuler").addEventListener("click", fermerPanneaux);
  document.getElementById("clotureGo").addEventListener("click", () => {
    es.cloture = {
      motif: document.getElementById("clotureMotif").value,
      detail: document.getElementById("clotureDetail").value.trim(),
      date: document.getElementById("clotureDate").value
    };
    toucherEssai(es); saveData(); fermerPanneaux(); render();
  });
  const re = document.getElementById("clotureReouvrir");
  if(re) re.addEventListener("click", () => {
    dialogueConfirmer("Réouvrir cet essai ? Il redevient « en cours » et repart à sa place dans le protocole.", { titre: "Réouvrir l'essai ?", okLabel: "Réouvrir" }).then(ok => {
      if(!ok) return;
      delete es.cloture;
      toucherEssai(es); saveData(); fermerPanneaux(); render();
    });
  });
}
