/* ============================================================================
   LIGNES DE SEPT FONS (v4.27) — référentiel atelier
   ----------------------------------------------------------------------------
   Les lignes de machines, du FOND de l'atelier vers l'ENTRÉE (info Matis/Benjamin) :
   Weisser 1 → 4, HESSAPP (double OP droite/gauche, comme EMAG 1), EMAG 1 (double OP),
   EMAG 2, EMAG 3, PCI 1, PCI 2. Ce référentiel sert à deux choses :
   - le SEMIS : au premier lancement de cette version, les lignes manquantes sont
     créées vides et tout l'arbre est remis dans l'ordre physique (une seule fois —
     une ligne supprimée volontairement ensuite ne revient pas) ;
   - la TEINTE de fond : quand une ligne est affichée, la page prend une teinte légère
     selon la famille de machines (Weisser = rouge, HESSAPP = kaki, EMAG = gris,
     PCI = bleu) avec le code ligne en filigrane répété — pour se repérer d'un coup
     d'œil sans lire le fil d'Ariane.
   ============================================================================ */
const LIGNES_SEPT_FONS = [
  { nom: "Weisser 1", famille: "weisser", code: "W1", machines: [] },
  { nom: "Weisser 2", famille: "weisser", code: "W2", machines: [] },
  { nom: "Weisser 3", famille: "weisser", code: "W3", machines: [] },
  { nom: "Weisser 4", famille: "weisser", code: "W4", machines: [] },
  { nom: "HESSAPP", famille: "hessapp", code: "HESSAPP",
    machines: [{ code:"OP10", nom:"Ébauche" }, { code:"OP15", nom:"" }, { code:"OP20", nom:"" }, { code:"OP40", nom:"Finition" }] },
  { nom: "EMAG 1", famille: "emag", code: "E1",
    machines: [{ code:"OP10", nom:"Ébauche piste" }, { code:"OP20", nom:"Ébauche piste ext." }, { code:"OP30", nom:"Perçages" }, { code:"OP40", nom:"Finition pistes" }] },
  { nom: "EMAG 2", famille: "emag", code: "E2",
    machines: [{ code:"OP10", nom:"Ébauche" }, { code:"OP30", nom:"Perçages" }, { code:"OP40", nom:"Finition" }] },
  { nom: "EMAG 3", famille: "emag", code: "E3",
    machines: [{ code:"OP10", nom:"Ébauche" }, { code:"OP40", nom:"Finition" }] },
  { nom: "PCI 1", famille: "pci", code: "P1", machines: [] },
  { nom: "PCI 2", famille: "pci", code: "P2", machines: [] }
];
const FAMILLES_LIGNE = {
  weisser: { encre: "#E2001A", alpha: 0.07 },
  hessapp: { encre: "#556b2f", alpha: 0.13, sansFiligrane: true }, // ligne unique : la couleur suffit
  emag:    { encre: "#545e68", alpha: 0.08 },
  pci:     { encre: "#1b5ea6", alpha: 0.07 }
};
function familleDeLigne(nom){
  const n = String(nom || "").trim().toLowerCase();
  if(n.startsWith("weisser")) return "weisser";
  if(n.startsWith("hessap")) return "hessapp";
  if(n.startsWith("emag")) return "emag";
  if(n.startsWith("pci")) return "pci";
  return "";
}
function rangLigneSeptFons(nom){
  const n = String(nom || "").trim().toLowerCase();
  const i = LIGNES_SEPT_FONS.findIndex(d => d.nom.toLowerCase() === n);
  return i === -1 ? LIGNES_SEPT_FONS.length : i; // lignes inconnues : après le référentiel
}
const CLE_SEMIS_LIGNES = "spk_lignes_septfons_semees";
function semerLignesSeptFons(){
  try{
    if(localStorage.getItem(CLE_SEMIS_LIGNES) === "1") return;
    let ajoute = false;
    LIGNES_SEPT_FONS.forEach(def => {
      const existe = lignes.some(l => String(l.nom || "").trim().toLowerCase() === def.nom.toLowerCase());
      if(existe) return;
      lignes.push(normalizeLigne({ id: uid("l"), nom: def.nom, references: [] }));
      ajoute = true;
    });
    lignes.sort((a, b) => rangLigneSeptFons(a.nom) - rangLigneSeptFons(b.nom));
    try{ localStorage.setItem(CLE_SEMIS_LIGNES, "1"); }catch(e){}
    if(ajoute) saveData();
  }catch(e){}
}
/* la teinte : fond de page légèrement coloré + code ligne en filigrane répété.
   En data-URL SVG sur le body (multiple backgrounds) : rien ne flotte au-dessus du
   contenu, l'encre s'adapte au thème (encre sombre sur fond clair, blanche sur fond
   sombre), et l'impression n'imprime ni l'un ni l'autre. */
function appliquerFondLigne(){
  const lg = getActiveLigne();
  const fam = familleDeLigne(lg && lg.nom);
  const def = FAMILLES_LIGNE[fam];
  if(!def){
    document.body.style.backgroundColor = "";
    document.body.style.backgroundImage = "";
    return;
  }
  const nomNorm = String(lg.nom || "").trim().toLowerCase();
  const trouvee = LIGNES_SEPT_FONS.find(d => d.nom.toLowerCase() === nomNorm);
  const code = trouvee ? trouvee.code : String(lg.nom || "").trim().toUpperCase().slice(0, 8);
  // encre du filigrane : sombre sur thème clair, claire sur thème sombre
  const bg = getComputedStyle(document.body).backgroundColor || "rgb(255,255,255)";
  const rgb = bg.match(/\d+/g) || ["255","255","255"];
  const sombre = (Number(rgb[0]) + Number(rgb[1]) + Number(rgb[2])) < 384;
  const encreTexte = sombre ? "#ffffff" : def.encre;
  const opaTexte = sombre ? Math.min(def.alpha + 0.04, 0.12) : def.alpha + 0.02;
  // la tuile porte la TEINTE (rect) et le FILIGRANE (texte) : un seul background-image
  // répété, posé sur le body — rien ne flotte au-dessus du contenu, aucun z-index à gérer.
  // sansFiligrane (HESSAPP, ligne unique) : la teinte seule identifie, pas de texte.
  const texte = def.sansFiligrane ? "" :
    `<text x='120' y='97' font-family='Archivo,Arial,sans-serif' font-size='54' font-weight='800' ` +
    `fill='${encreTexte}' fill-opacity='${opaTexte}' text-anchor='middle'>${code}</text>`;
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='240' height='150'>` +
    `<rect width='240' height='150' fill='${def.encre}' fill-opacity='${def.alpha}'/>` +
    texte + `</svg>`;
  document.body.style.backgroundColor = "";
  document.body.style.backgroundImage = `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
}

semerLignesSeptFons();
render();
/* v4.74 — la migration des outils D1/D2 séparés : détectée au chargement,
   proposée UNE fois avec les noms, appliquée à la demande (§7.4 : la donnée
   se touche avec consentement et rapport). Disparaît quand il n'y a plus rien
   à regrouper, et revient si des données fraîchement importées ramènent des
   doubles. */
function renduMigrBandeau(){
  const wrap = document.getElementById("migrBandeau");
  if(!wrap) return;
  const n = compterOutilsD1D2();
  const nInv = compterInversionsMabec();
  wrap.hidden = (n === 0 && nInv === 0);
  if(n === 0 && nInv === 0) { wrap.innerHTML = ""; return; }
  const parties = [];
  if(n) parties.push(`🔧 <b>${n} porte-outil${n > 1 ? "s" : ""}</b> saisi${n > 1 ? "s" : ""} en outils séparés (T543 D1 + T543 D2…) : la règle atelier dit <b>un porte-outil = un outil à logements</b>`);
  if(nInv) parties.push(`🏷️ <b>${nInv} logement${nInv > 1 ? "s" : ""}</b> attendent leur référence plaquette — l'ISO est complété depuis le classeur quand il y est connu`);
  wrap.innerHTML = `
    <div class="migr-bandeau">
      <span>${parties.join("<br>")}
      <button class="primary small" id="migrCorriger">Corriger maintenant</button>
      <button class="ghost small" id="migrPlusTard">Plus tard</button></span>
      <div class="migr-rapport" id="migrRapport" hidden></div>
    </div>`;
  document.getElementById("migrCorriger").addEventListener("click", () => {
    const res = migrerOutilsD1D2();
    const rapInv = migrerInversionMabec();
    saveData();
    render();
    const rap = document.getElementById("migrRapport");
    const wrap2 = document.getElementById("migrBandeau");
    if(rap && wrap2){
      wrap2.hidden = false;
      rap.hidden = false;
      const tout = [];
      if(res.rapport.length) tout.push(`<b>Regroupements — ${res.rapport.length} :</b> ` + res.rapport.map(x => escapeAttr(x)).join(" · "));
      if(rapInv.length) tout.push(`<b>MABEC remis en place — ${rapInv.length} :</b> ` + rapInv.map(x => escapeAttr(x)).join(" · "));
      rap.innerHTML = tout.length ? tout.join("<br>") : `Rien à corriger.`;
      wrap2.querySelectorAll("button").forEach(b => b.hidden = true);
    }
  });
  document.getElementById("migrPlusTard").addEventListener("click", () => { wrap.hidden = true; });
}

