/* ---- transport : fetch avec délai max (un proxy qui hang ne doit pas bloquer l'outil) ---- */
function cloudFetch(url, opts, delai){
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), delai || 15000);
  return fetch(url, Object.assign({}, opts, { signal: ctl.signal })).finally(() => clearTimeout(t));
}
function cloudEntetes(extra){
  return Object.assign({
    "apikey": CLOUD_KEY,
    "Authorization": "Bearer " + (cloudSession ? cloudSession.access_token : CLOUD_KEY),
    "Content-Type": "application/json"
  }, extra || {});
}

/* ---- auth : email + mot de passe, session rafraîchie à la demande ---- */
async function cloudRequeteAuth(grant, body){
  const r = await cloudFetch(CLOUD_URL + "/auth/v1/token?grant_type=" + grant, {
    method: "POST",
    headers: { "apikey": CLOUD_KEY, "Content-Type": "application/json" },
    body: JSON.stringify(body)
  });
  const j = await r.json().catch(() => ({}));
  if(!r.ok){
    const brut = j.error_description || j.msg || j.message || "connexion refusée";
    const err = new Error(/invalid login credentials/i.test(brut) ? "Email ou mot de passe incorrect." : brut);
    /* 400/401/403 = le serveur a REJETE le jeton (révoqué, déjà utilisé, mauvais identifiants) :
       définitif. Un 5xx ou une réponse illisible est temporaire — crucial pour ne pas
       détruire une session encore valable à cause d'une indisponibilité passagère. */
    if(r.status === 400 || r.status === 401 || r.status === 403) err.definitif = true;
    throw err;
  }
  return j;
}
async function cloudConnexion(email, motDePasse){
  const j = await cloudRequeteAuth("password", { email, password: motDePasse });
  cloudSession = {
    access_token: j.access_token, refresh_token: j.refresh_token,
    expires_at: Date.now() + (j.expires_in || 3600) * 1000,
    email: (j.user && j.user.email) || email
  };
  cloudSauverSession();
  cloudErreur = "";
  cloudRenduOptions(); cloudRenduPastille();
  cloudSync("connexion");
}
async function cloudRafraichirSession(){
  if(!cloudSession || Date.now() < cloudSession.expires_at - 60000) return cloudSession ? true : false;
  try{
    const j = await cloudRequeteAuth("refresh_token", { refresh_token: cloudSession.refresh_token });
    cloudSession.access_token = j.access_token;
    cloudSession.refresh_token = j.refresh_token;
    cloudSession.expires_at = Date.now() + (j.expires_in || 3600) * 1000;
    cloudSauverSession();
    return true;
  }catch(e){
    /* v4.17 — la session ne meurt plus qu'en cas de refus DEFINITIF du serveur (jeton
       révoqué, refresh déjà consommé). Avant : TOUT échec détruisait la session — y
       compris un simple "Failed to fetch" ou un AbortError du délai d'attente. Ouvrir
       l'outil hors réseau (usine, démarrage avant la montée du Wi-Fi) suffisait donc à
       se faire déconnecter, alors que le refresh token restait parfaitement valable :
       il fallait se reconnecter à chaque ouverture. Désormais la session est conservée
       et le rafraîchissement retentera au prochain contact (focus, 90 s, saisie). */
    if(!e || !e.definitif){
      cloudErreur = "cloud injoignable — session conservée, nouvelle tentative au prochain contact";
      cloudRenduOptions(); cloudRenduPastille();
      return false;
    }
    cloudSession = null; cloudSauverSession();
    cloudErreur = "session expirée — reconnectez-vous dans Options";
    cloudRenduOptions(); cloudRenduPastille();
    return false;
  }
}
async function cloudDeconnexion(){
  try{ await cloudFetch(CLOUD_URL + "/auth/v1/logout", { method:"POST", headers: cloudEntetes() }, 5000); }catch(e){}
  cloudSession = null; cloudSauverSession();
  cloudErreur = "";
  cloudRenduOptions(); cloudRenduPastille();
}

/* ---- photos cloud (v4.16) --------------------------------------------------------------
   Le suivi partage le JSON entre postes, mais les PHOTOS d'essai restaient coincées dans
   le dossier local de celui qui les avait prises : l'autre poste (et son rapport) n'en
   voyait rien. Deuxième mode de stockage : le bucket privé `photos` du projet Supabase
   (accès réservé aux comptes de l'équipe). Sans dossier local connecté, une photo ajoutée
   part au cloud et voyage avec le suivi ; l'autre poste la télécharge à la demande et la
   met en cache IndexedDB pour l'usage hors ligne. Le dossier local reste prioritaire quand
   il est connecté (zéro réseau, zéro quota) — les deux modes coexistent photo par photo. */
const CLOUD_PHOTOS_BUCKET = "photos";

function photoCacheOuvrir(){
  return new Promise((resolve, reject) => {
    const req = indexedDB.open("spk_photos_cloud", 1);
    req.onupgradeneeded = () => req.result.createObjectStore("blobs");
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}
async function photoCacheGet(cle){
  try{
    const db = await photoCacheOuvrir();
    return await new Promise((resolve, reject) => {
      const req = db.transaction("blobs", "readonly").objectStore("blobs").get(cle);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => reject(req.error);
    });
  }catch(e){ return null; }
}
async function photoCacheSet(cle, blob){
  try{
    const db = await photoCacheOuvrir();
    await new Promise((resolve, reject) => {
      const tx = db.transaction("blobs", "readwrite");
      tx.objectStore("blobs").put(blob, cle);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }catch(e){ /* le cache est un confort, jamais une condition */ }
}
async function photoCacheEffacer(cle){
  try{
    const db = await photoCacheOuvrir();
    await new Promise((resolve, reject) => {
      const tx = db.transaction("blobs", "readwrite");
      tx.objectStore("blobs").delete(cle);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }catch(e){}
}
/* le blob d'une photo cloud : cache d'abord, téléchargement ensuite (auth par session) */
async function cloudPhotoBlob(chemin){
  const enCache = await photoCacheGet(chemin);
  if(enCache) return enCache;
  if(!await cloudRafraichirSession()) throw new Error("non connecté au cloud (Options → Cloud)");
  const rep = await fetch(CLOUD_URL + "/storage/v1/object/" + CLOUD_PHOTOS_BUCKET + "/" + chemin, {
    headers: { "Authorization": "Bearer " + cloudSession.access_token }
  });
  if(!rep.ok) throw new Error(rep.status === 404 ? "photo introuvable dans le cloud" : "téléchargement impossible (" + rep.status + ")");
  const blob = await rep.blob();
  await photoCacheSet(chemin, blob);
  return blob;
}
async function cloudPhotoEnvoyer(chemin, blob){
  if(!await cloudRafraichirSession()) throw new Error("non connecté au cloud (Options → Cloud)");
  const rep = await fetch(CLOUD_URL + "/storage/v1/object/" + CLOUD_PHOTOS_BUCKET + "/" + chemin, {
    method: "POST",
    headers: { "Authorization": "Bearer " + cloudSession.access_token, "Content-Type": (blob && blob.type) || "image/jpeg" },
    body: blob
  });
  if(!rep.ok){
    // 400 "Duplicate" = la photo existe déjà (ré-essai après un upload réussi) : pas une erreur
    const corps = await rep.text().catch(() => "");
    if(!/duplicate/i.test(corps)) throw new Error("envoi impossible (" + rep.status + ")");
  }
  await photoCacheSet(chemin, blob);
}
async function cloudPhotoSupprimer(chemin){
  await photoCacheEffacer(chemin);
  if(!await cloudRafraichirSession()) return; // le retrait du JSON suffit ; nettoyage du bucket à la prochaine suppression
  await fetch(CLOUD_URL + "/storage/v1/object/" + CLOUD_PHOTOS_BUCKET + "/" + chemin, {
    method: "DELETE",
    headers: { "Authorization": "Bearer " + cloudSession.access_token }
  }).catch(() => {});
}
/* objectURL d'une photo quel que soit son mode (dossier local ou cloud) — à révoquer
   par l'appelant une fois l'image décodée. null = indisponible sur ce poste.
   (rédefinit le stub du script principal, qui ne sait lire que le dossier local) */
async function photoObjectURL(p){
  if(!p) return null;
  if(p.stockage === "cloud"){
    try{
      const blob = await cloudPhotoBlob(p.filename);
      return URL.createObjectURL(blob);
    }catch(e){
      cloudPhotoErreurDerniere = e.message || "erreur";
      return null;
    }
  }
  return readPhotoURL(p.filename);
}

/* ---- lectures / écritures de l'état partagé ---- */
async function cloudLireEtat(){
  const r = await cloudFetch(CLOUD_URL + "/rest/v1/etat?id=eq.1&select=donnees,modifie_le,modifie_par", { headers: cloudEntetes() });
  if(!r.ok) throw new Error("cloud injoignable (" + r.status + ")");
  const j = await r.json();
  return j[0] || null;
}
/* v4.81.0 — la lecture LÉGÈRE : le tampon horaire seul, sans le `donnees`.
   L'état partagé pèse 3 à 4 Mo ; chaque cycle de synchro qui le re-télécharge
   en entier pour lire une date a épuisé le quota de bande sortante du plan
   gratuit (exceed_egress_quota, 12/10/2026 — service restreint). Désormais la
   synchro de routine passe par ici (~100 octets) et la lecture lourde ne se
   paie que lorsqu'une décision a besoin du contenu : premier contact,
   adoption, fusion. Mêmes décisions, même ordre — seul le poids du regard
   change. */
async function cloudLireTampon(){
  const r = await cloudFetch(CLOUD_URL + "/rest/v1/etat?id=eq.1&select=modifie_le,modifie_par", { headers: cloudEntetes() });
  if(!r.ok) throw new Error("cloud injoignable (" + r.status + ")");
  const j = await r.json();
  return j[0] || null;
}
/* Dépose la version locale : archive l'ancienne (historique 20 versions), écrit la
   nouvelle, retient le tampon horaire renvoyé par la base (jamais calculé côté client). */
async function cloudEcrireEtat(){
  syncActiveOp();
  const donnees = JSON.parse(payloadSuivi());
  const avant = await cloudLireEtat();
  if(avant){
    await cloudFetch(CLOUD_URL + "/rest/v1/etat_historique", {
      method:"POST", headers: cloudEntetes({ "Prefer":"return=minimal" }),
      body: JSON.stringify({ donnees: avant.donnees, sauve_par: avant.modifie_par || "" })
    });
  }
  const corps = { id:1, donnees, modifie_par: auteurNom || (cloudSession && cloudSession.email) || "" };
  let r = await cloudFetch(CLOUD_URL + "/rest/v1/etat?id=eq.1", {
    method:"PATCH", headers: cloudEntetes({ "Prefer":"return=representation" }),
    body: JSON.stringify(corps)
  });
  if(!r.ok) throw new Error("cloud injoignable (" + r.status + ")");
  let j = await r.json();
  if(!j.length){
    r = await cloudFetch(CLOUD_URL + "/rest/v1/etat", {
      method:"POST", headers: cloudEntetes({ "Prefer":"resolution=merge-duplicates,return=representation" }),
      body: JSON.stringify(corps)
    });
    if(!r.ok) throw new Error("cloud injoignable (" + r.status + ")");
    j = await r.json();
  }
  cloudStamp = j[0].modifie_le;
  cloudSauverStamp();
  cloudSale = false;
  cloudDernierOK = new Date();
  cloudInfo = { vide:false, modifie_le: cloudStamp, modifie_par: corps.modifie_par };
}
async function cloudArchiverLeCloudActuel(row){
  await cloudFetch(CLOUD_URL + "/rest/v1/etat_historique", {
    method:"POST", headers: cloudEntetes({ "Prefer":"return=minimal" }),
    body: JSON.stringify({ donnees: row.donnees, sauve_par: row.modifie_par || "" })
  });
}

/* ---- comptage d'essais, pour les résumés affichés avant décision ---- */
function cloudCompterEssais(arbre){
  return (arbre || []).reduce((n,l) => n + (l.references || []).reduce((m,r) => m + (r.ops || []).reduce((k,o) =>
    k + (o.scenarios || []).reduce((x,s) => x + ((s.essais || []).length), 0), 0), 0), 0);
}
function cloudLocalEstExemple(){
  try{
    const l = lignes && lignes[0];
    return !!l && (JSON.stringify(l).indexOf("[Exemple]") !== -1);
  }catch(e){ return false; }
}

/* export de secours téléchargé AVANT tout remplacement des données locales */
function cloudExportSecours(motif){
  try{
    const obj = JSON.parse(payloadSuivi());
    obj.exporteLe = new Date().toISOString();
    obj.exportePar = (auteurNom || "?") + " — secours avant " + motif;
    const blob = new Blob([JSON.stringify(obj, null, 2)], { type:"application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    const d = new Date();
    const stamp = d.getFullYear() + String(d.getMonth()+1).padStart(2,"0") + String(d.getDate()).padStart(2,"0")
                + "-" + String(d.getHours()).padStart(2,"0") + String(d.getMinutes()).padStart(2,"0");
    a.href = url;
    a.download = "SuiviOptimisation_secours_" + stamp + ".json";
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  }catch(e){}
}

/* applique la version du cloud au poste — le même chemin qu'un import « remplacer tout »,
   avec son ↺ Restaurer et sa sauvegarde de sécurité ; silencieux = tirage de routine */
async function cloudAdopter(row, silencieux){
  const prep = preparerImportDepuis(row.donnees);
  if(!prep){ cloudErreur = "contenu cloud illisible"; cloudRenduPastille(); return false; }
  if(!silencieux) cloudExportSecours("la prise de la version du cloud");
  const optionsOuvertes = !document.getElementById("optionsPanel").hidden;
  cloudPause = true;
  try{
    importEnAttente = Object.assign({ parsed: row.donnees }, prep);
    appliquerImport("remplace");
  } finally { cloudPause = false; }
  cloudStamp = row.modifie_le;
  cloudSale = false;
  cloudSauverStamp();
  cloudDernierOK = new Date();
  if(optionsOuvertes) ouvrirPanneau("optionsPanel");
  return true;
}

/* premier contact avec un cloud déjà rempli : qui fait autorité ? Toujours demandé,
   jamais tranché en silence — c'est la garde-fou « les données de Matis d'abord ». */
async function cloudPremierContact(row){
  const d = row.donnees || {};
  const nCloud = cloudCompterEssais(d.lignes);
  const quand = row.modifie_le ? new Date(row.modifie_le).toLocaleString("fr-FR") : "date inconnue";
  const par = row.modifie_par || "inconnu";
  const nLocal = cloudCompterEssais(lignes);
  const ok = await dialogueConfirmer(
    "Le cloud contient déjà un suivi : " + nCloud + " essai(s), dernière modification le " + quand + " par " + par + ".\n\n" +
    "Votre version locale compte " + nLocal + " essai(s)" + (cloudLocalEstExemple() ? " et semble être le jeu d'exemple [Exemple]." : ".") + "\n\n" +
    "Prendre la version du cloud sur ce poste ? Un export de secours de votre version locale sera téléchargé avant.",
    { titre:"Cloud — ce poste et le cloud diffèrent", okLabel:"Prendre le cloud" });
  if(ok){ await cloudAdopter(row, false); return; }
  const ok2 = await dialogueConfirmer(
    "Garder votre version locale et déposer celle-ci dans le cloud à la place ?\n\n" +
    "La version actuellement dans le cloud ne est pas perdue : elle part dans l'historique (20 dernières versions gardées).",
    { titre:"Déposer votre version à la place ?", danger:true, okLabel:"Déposer ma version" });
  if(ok2){
    try{ await cloudEcrireEtat(); cloudErreur = ""; }
    catch(e){ cloudErreur = e.message || "dépôt impossible"; }
  } else {
    // on ne re-posera pas la question tant que le cloud n'a pas bougé
    cloudStamp = row.modifie_le; cloudSauverStamp();
  }
}

/* le cloud a bougé pendant que ce poste avait des saisies non déposées : depuis la
   v4.10, FUSION AUTOMATIQUE essai par essai (le plus récent gagne pour un même essai,
   les essais de chacun s'ajoutent, les réglages du scénario restent à la version
   locale) — plus de choix binaire « prendre / écraser ». Le bilan s'affiche dans le
   panneau de fusion, la version du cloud remplacée part à l'archive, et le résultat
   fusionné repart au cloud au prochain cycle avec une note embarquée que l'autre
   poste lira à sa prochaine ouverture. */
async function cloudConflit(row){
  const quand = new Date(row.modifie_le).toLocaleString("fr-FR");
  const par = row.modifie_par || "l'autre poste";
  try{ await cloudArchiverLeCloudActuel(row); }catch(e){}
  const prep = preparerImportDepuis(row.donnees);
  if(!prep){ cloudErreur = "contenu cloud illisible"; cloudRenduPastille(); return; }
  importEnAttente = Object.assign({ parsed: row.donnees }, prep);
  const bilan = appliquerImport("fusion") || { essaisAjoutes:0, essaisMaj:0, essaisConserves:0, conflits:[] };
  // dans le flux import, le panneau de bilan est déjà ouvert par le choix Fusionner ;
  // ici il faut l'ouvrir soi-même — c'est le « message » qui raconte la fusion
  if(bilan) ouvrirPanneau("importPanel");
  synchroNote = {
    par: auteurNom || (cloudSession && cloudSession.email) || "?",
    quand: new Date().toISOString(),
    texte: "fusion automatique après le dépôt de " + par + " (" + quand + ") : " +
      bilan.essaisAjoutes + " essai(s) ajouté(s), " + bilan.essaisMaj + " mis à jour, " +
      (bilan.essaisConserves || 0) + " conservé(s)" +
      ((bilan.conflits && bilan.conflits.length) ? ", " + bilan.conflits.length + " conflit(s) à vérifier (rapport de fusion ci-dessous)" : "")
  };
  saveData(); // repersiste la note ; le dépôt du fusionné part au prochain cycle (4 s)
  cloudStamp = row.modifie_le; // version du cloud vue et fusionnée
  cloudSale = true;
  cloudSauverStamp();
  cloudDernierOK = new Date();
}

/* ---- le moteur : un aller-retour qui décrit tout ce qui peut se rencontrer ---- */
async function cloudSync(raison){
  if(!cloudSession || cloudEnCours) return;
  if(!(await cloudRafraichirSession())) return;
  cloudEnCours = true;
  cloudRenduPastille();
  try{
    /* v4.81.0 — le tampon d'abord (~100 o), le contenu lourd seulement si une
       décision l'exige. Le flux et l'ordre des décisions sont INCHANGÉS :
       cloud vide → rien ; premier contact → dialogue ; bougé + saisies locales
       → fusion ; bougé + poste propre → adoption silencieuse ; pas bougé +
       saisies → dépôt ; rien → point d'horloge. */
    const tampon = await cloudLireTampon();
    cloudInfo = tampon
      ? { vide:false, modifie_le: tampon.modifie_le, modifie_par: tampon.modifie_par }
      : { vide:true, modifie_le:null, modifie_par:null };

    if(!tampon){
      // cloud vide : rien à tirer. Le dépôt initial reste volontaire (bouton dans
      // Options) — jamais un effet de bord d'une saisie, sinon le jeu d'exemple
      // d'un poste partirait au cloud par accident.
      cloudDernierOK = new Date();
      cloudErreur = "";
      return;
    }
    if(cloudStamp === null){
      await cloudPremierContact(await cloudLireEtat());
      return;
    }
    if(tampon.modifie_le !== cloudStamp){
      if(cloudSale){
        await cloudConflit(await cloudLireEtat());
      } else {
        // tirage silencieux — le cas nominal. Si la version vient de l'autre poste et
        // n'avait jamais été vue : message à l'ouverture (le journal de synchro).
        const row = await cloudLireEtat();
        const annonce = (tampon.modifie_le !== cloudVu) && ((tampon.modifie_par || "") !== cloudMonIdentite());
        await cloudAdopter(row, true);
        if(annonce) cloudAnnoncerVersion(row);
      }
    } else if(cloudSale){
      await cloudEcrireEtat();               // dépôt automatique après saisie
    } else {
      cloudDernierOK = new Date();
    }
    if(!cloudErreur) cloudErreur = "";
  }catch(e){
    cloudErreur = (e && e.name === "AbortError") ? "cloud injoignable (délai dépassé)" : ((e && e.message) || "cloud injoignable");
  }finally{
    cloudEnCours = false;
    cloudMarquerVu();
    cloudRenduPastille();
    const opt = document.getElementById("optionsPanel");
    if(opt && !opt.hidden) cloudRenduOptions();
  }
}

/* ---- déclencheurs ---- */
/* appelé par saveData() à chaque saisie (voir hook dans le script principal) */
function cloudApresSauvegarde(){
  if(cloudPause || !cloudSession) return;
  cloudSale = true;
  cloudRenduPastille();
  clearTimeout(cloudTimerPush);
  cloudTimerPush = setTimeout(() => cloudSync("saisie"), 4000);
}
function cloudAuFocus(){
  if(!cloudSession) return;
  const t = Date.now();
  if(t - cloudDernierFocus < 10000) return;
  cloudDernierFocus = t;
  clearTimeout(cloudTimerFocus);
  cloudTimerFocus = setTimeout(() => cloudSync("focus"), 800);
}

/* dépôt initial volontaire (bouton Options, cloud vide) */
async function cloudDeposerManuel(){
  if(!cloudSession) return;
  const nLocal = cloudCompterEssais(lignes);
  const ok = await dialogueConfirmer(
    "Déposer ce suivi dans le cloud ?\n\nIl compte " + nLocal + " essai(s). Il deviendra la version partagée que l'autre poste recevra à sa connexion." +
    (cloudLocalEstExemple() ? "\n\nATTENTION : cette version semble être le jeu d'exemple [Exemple] — ne pas la déposer si le vrai suivi existe déjà sur un autre poste." : ""),
    { titre:"Déposer ce suivi dans le cloud ?", danger: cloudLocalEstExemple(), okLabel:"Déposer" });
  if(!ok) return;
  cloudEnCours = true; cloudRenduPastille();
  try{ await cloudEcrireEtat(); cloudErreur = ""; }
  catch(e){ cloudErreur = e.message || "dépôt impossible"; }
  cloudEnCours = false;
  cloudRenduPastille(); cloudRenduOptions();
}

/* ---- pastille de pied de page ---- */
function cloudRenduPastille(){
  const el = document.getElementById("footCloud");
  if(!el) return;
  if(!cloudSession){ el.hidden = true; return; }
  el.hidden = false;
  el.classList.remove("alerte","critique");
  let txt = "☁ à jour", title = "Synchro cloud du suivi";
  if(cloudEnCours){ txt = "☁ synchro…"; }
  else if(cloudErreur){
    if(/conflit/.test(cloudErreur)){ txt = "☁ conflit"; el.classList.add("alerte"); }
    else if(/expirée/.test(cloudErreur)){ txt = "☁ déconnecté"; el.classList.add("critique"); }
    else { txt = "☁ hors ligne"; el.classList.add("alerte"); }
    title += " — " + cloudErreur;
  }
  else if(cloudStamp === null && cloudInfo.vide === false){ txt = "☁ à régler"; el.classList.add("alerte"); title += " — première synchronisation à confirmer"; }
  else if(cloudSale){ txt = "☁ en attente d'envoi"; }
  else if(cloudInfo.vide){ txt = "☁ vide — dépôt à faire"; el.classList.add("alerte"); title += " — le cloud est vide : déposez ce suivi depuis Options"; }
  if(cloudDernierOK && txt === "☁ à jour") title += " — dernière synchro " + cloudDernierOK.toLocaleTimeString("fr-FR");
  el.textContent = txt;
  el.title = title;
}

/* ---- zone Cloud du panneau Options ---- */
function cloudRenduOptions(){
  const z = document.getElementById("cloudZone");
  if(!z) return;
  if(!cloudSession){
    z.innerHTML = `
      <label>Synchro entre postes <i class="opt-scope">Tous</i></label>
      <span class="opt-note" style="margin-bottom:10px; display:block;">Partage automatique du suivi entre vous et Matis : chaque saisie repart seule quelques secondes après, les modifications de l'autre arrivent à l'ouverture de l'outil ou en revenant sur l'onglet. Chaque poste garde sa copie locale — l'outil continue de marcher sans réseau.</span>
      <div style="display:flex; gap:8px; flex-wrap:wrap; align-items:center;">
        <input type="email" id="cloudEmail" placeholder="email" autocomplete="username" style="flex:1 1 170px; min-width:150px; text-align:left;">
        <input type="password" id="cloudMdp" placeholder="mot de passe" autocomplete="current-password" style="flex:1 1 130px; min-width:120px; text-align:left;">
        <button class="primary" id="cloudBtnConnexion">Se connecter</button>
      </div>
      <div class="opt-statut ko" id="cloudErreurUI" ${cloudErreur ? "" : "hidden"} style="margin-top:8px;"></div>`;
    const btn = z.querySelector("#cloudBtnConnexion");
    btn.addEventListener("click", async () => {
      const email = z.querySelector("#cloudEmail").value.trim();
      const mdp = z.querySelector("#cloudMdp").value;
      if(!email || !mdp){
        const e = z.querySelector("#cloudErreurUI"); e.hidden = false; e.textContent = "Email et mot de passe requis.";
        return;
      }
      btn.disabled = true; btn.textContent = "Connexion…";
      try{ await cloudConnexion(email, mdp); }
      catch(err){
        btn.disabled = false; btn.textContent = "Se connecter";
        const e = z.querySelector("#cloudErreurUI"); e.hidden = false; e.textContent = err.message || "Connexion impossible.";
      }
    });
    z.querySelector("#cloudMdp").addEventListener("keydown", ev => { if(ev.key === "Enter") btn.click(); });
    return;
  }
  const dernier = cloudDernierOK ? cloudDernierOK.toLocaleString("fr-FR") : "—";
  let etatCloud;
  if(cloudInfo.vide === null) etatCloud = "non encore lu";
  else if(cloudInfo.vide) etatCloud = "<b>vide</b> — ce poste peut y déposer son suivi";
  else etatCloud = "dernier dépôt le " + new Date(cloudInfo.modifie_le).toLocaleString("fr-FR") + " par <b>" + escapeAttr(cloudInfo.modifie_par || "?") + "</b>";
  z.innerHTML = `
    <label>Connexion <i class="opt-scope">Tous</i></label>
    <span class="opt-note" style="display:block; margin-bottom:8px;">Connecté en tant que <b>${escapeAttr(cloudSession.email || "?")}</b> — dernière synchro ${dernier}.</span>
    <span class="opt-note" style="display:block; margin-bottom:10px;">État du cloud : ${etatCloud}.</span>
    <div style="display:flex; gap:8px; flex-wrap:wrap;">
      ${cloudInfo.vide ? `<button class="primary" id="cloudBtnDeposer">Déposer ce suivi</button>` : ""}
      <button class="ghost" id="cloudBtnSync">Synchroniser maintenant</button>
      <button class="ghost" id="cloudBtnSortir">Se déconnecter</button>
    </div>
    <div class="opt-statut ko" id="cloudErreurUI" ${cloudErreur ? "" : "hidden"} style="margin-top:8px;"></div>`;
  const errUI = z.querySelector("#cloudErreurUI");
  if(cloudErreur){ errUI.hidden = false; errUI.textContent = cloudErreur; }
  const d = z.querySelector("#cloudBtnDeposer");
  if(d) d.addEventListener("click", cloudDeposerManuel);
  z.querySelector("#cloudBtnSync").addEventListener("click", async (ev) => {
    ev.target.disabled = true; ev.target.textContent = "Synchronisation…";
    await cloudSync("manuel");
  });
  z.querySelector("#cloudBtnSortir").addEventListener("click", cloudDeconnexion);
}

function cloudDemarrage(){
  const btnOpt = document.getElementById("optionsBtn");
  if(btnOpt) btnOpt.addEventListener("click", cloudRenduOptions);
  document.addEventListener("visibilitychange", () => { if(!document.hidden) cloudAuFocus(); });
  window.addEventListener("focus", cloudAuFocus);
  setInterval(() => cloudSync("periode"), 90000);
  const el = document.getElementById("footCloud");
  if(el) el.addEventListener("click", () => {
    dialogueAlerte(cloudSession
      ? "Synchro cloud : " + (cloudErreur || ("à jour" + (cloudDernierOK ? " (dernier échange " + cloudDernierOK.toLocaleTimeString("fr-FR") + ")" : ""))) + ".\nLe détail et les actions sont dans Options, section Cloud."
      : "Synchro cloud désactivée : connectez-vous dans Options, section Cloud.", "Synchro cloud");
  });
  if(cloudSession) cloudSync("demarrage");
  cloudRenduPastille();
}
cloudDemarrage();

;


/* ── v4.79 — LES PROMESSES DE L'INTERFACE ─────────────────────────────────────
   Contrôle voulu par Hermes (Tours 50-51) et construit ici, main passée. Le
   constat de départ : « un bouton n'appelle que des fonctions qui existent ».
   La méthode exacte — « une question sur le code se pose au code » : chaque
   promesse est vérifiée par typeof DANS LA PORTÉE du script, là où le clic
   résout ses noms. Aucune analyse du source, aucun regex sur le JavaScript —
   la réponse vient du moteur. (Le scanner d'attributs onclick imaginé d'abord
   n'avait rien à mordre : ce fichier compte 0 onclick= et 166 addEventListener.)

   La liste est ÉCRITE À LA MAIN, porte par porte, en lisant les gestionnaires —
   c'est sa force (zéro faux positif) et sa limite (une porte nouvelle n'est
   couverte que si sa promesse entre ici ; la constitution §6.9 le sait déjà :
   les tests protègent ce qu'on a programmé). Chaque porte nomme les fonctions
   SANS lesquelles son clic est mort. Les portes internes (fermetures, dialogues
   génériques) sont regroupées ; les portes mortes CONNUES et non construites
   (import de livraison, photos de machines) ne figurent pas ici : elles sont
   des chantiers, pas des promesses. */
