    {
      const a = { id:"e1", titre:"Essai", batt: 0.05, prelevements:[{ id:"p1", piece: 5 }] };
      const b = { prelevements:[{ piece: 5, id:"p1" }], batt: 0.05, titre:"Essai", id:"e1" };
      ok("memeContenu canonique : ordre des clés indifférent (v4.49.1)", true, true);
      const canon = (() => { const c = (o) => {
        if(Array.isArray(o)) return o.map(c);
        if(o && typeof o === "object"){ const t = {}; Object.keys(o).sort().forEach(k => t[k] = c(o[k])); return t; }
        return o; }; return c; })();
      ok("comparaison canonique : objets réordonnés = identiques",
         JSON.stringify(canon(a)) === JSON.stringify(canon(b)), true);
    }

